export const FITA_R32_33 = {
 ca: ['21 de novembre de 2026, nit · Onades R32.29 a R32.33 · L’Atles 2D a Disseny, cada sessió amb les seues dades i el lector de pantalla en la teua llengua',
  'Les Onades R32.29 a R32.33 de <strong>Sóc de Poble</strong> fan la plataforma més <strong>forta</strong> per dins. Cada <strong>sessió</strong> es queda amb les seues <strong>dades</strong>; el <strong>lector de pantalla</strong> parla la <strong>llengua triada</strong> en moltes més pantalles; i les pantalles aguanten millor una <strong>data</strong> o un <strong>import estrany</strong>.',
  'Les aplicacions passen a la <strong>versió 1.2.19 (build 24)</strong> al <strong>repositori</strong> i, quan s’escriu esta crònica, la versió encara <strong>no consta a cap botiga</strong>. El <strong>connector de WordPress</strong> publicat a WordPress.org és la <strong>1.1.26</strong>; la 1.1.27 del repositori <strong>encara no s’ha publicat</strong>.',
  'Quan s’escriu esta crònica, la versió <strong>no canvia res</strong> al <strong>servidor de Sóc de Poble</strong>. Els <strong>avisos del xat</strong> a les aplicacions del mòbil encara <strong>no estan encesos</strong>, la <strong>política de privacitat</strong> continua en la <strong>versió 2.5</strong>, i encendre els avisos depén d’una <strong>decisió del Mestre</strong>.',
  ['Novetat · L’Atles 2D, a Disseny', `A ${enllacIntern(ENLLAC_DISSENY, 'Disseny')}, la carpeta <strong>Atles 2D</strong> reunix en <strong>cinc pàgines</strong> l’estudi d’un <strong>poble virtual</strong>, el de l’Assaig a la Plaça, amb <strong>veïns simulats</strong>, dotze <strong>xarxes del món</strong>, el <strong>mapa de les cinc entitats</strong> i una proposta de <strong>motor d’estudis</strong>. És un estudi per a decidir: no afig cap funció nova, i la carpeta Inventari es diu ara Recursos.`],
  ['Millora · Cada sessió, amb les seues dades', `Si al <strong>mateix aparell</strong> algú <strong>tanca la sessió</strong> i n’obri una altra, el ${enllacIntern(ENLLAC_PERFIL, 'perfil')} i la IAIA ja <strong>no mostren</strong> cap <strong>resposta</strong> que arribe tard de la primera, i una <strong>denúncia</strong> que s’estava enviant amb la primera <strong>no ix</strong> amb la segona.`],
  ['Millora · El lector de pantalla, en la teua llengua', 'Les <strong>etiquetes</strong> que llig el <strong>lector de pantalla</strong> i els <strong>textos d’ajuda</strong> dels camps parlen la <strong>llengua triada</strong> d’entre les <strong>cinc</strong> en moltes més pantalles, com ara el <strong>Mur</strong>, el Calendari, els Dispositius, el Perfil, la <strong>Gestoria</strong> i els panells d’administració.'],
  ['Millora · Pantalles més resistents', 'Una <strong>data impossible</strong> desada a l’aparell ja no tomba els <strong>crèdits</strong> de la <strong>fitxa d’un poble</strong>; i la <strong>Gestoria</strong>, el <strong>Bar</strong> i altres aplicacions petites aguanten millor les <strong>dates</strong> i els <strong>imports</strong> que falten o que no quadren.'],
  ['Millora · Els fulls de la Salut, en la teua llengua', 'En <strong>exportar</strong> el full de la <strong>Salut</strong>, els <strong>noms</strong> de les columnes ixen en la <strong>llengua triada</strong>, i en <strong>importar-lo</strong> es reconeixen en qualsevol de les cinc. Un full exportat en una llengua que no siga el valencià només el llig esta <strong>versió</strong> o una de més nova.'],
  ['Millora · Una fitxa, una sola adreça', 'Si algú escriu l’adreça de la <strong>fitxa d’un poble</strong> o d’un <strong>producte</strong> amb alguna <strong>lletra en codi</strong>, com %61 en lloc de la «a», la fitxa diu als <strong>cercadors</strong> que és la <strong>mateixa</strong>, amb la seua <strong>adreça neta</strong>, i no una de nova.'],
  ['Millora · El connector de WordPress 1.1.27', 'Els <strong>ajustos</strong> del connector <strong>deixen de carregar-se</strong> a cada pàgina del WordPress (si el connector ja hi era, des que un <strong>administrador</strong> obri el <strong>tauler</strong>), i la pantalla de <strong>Salut del lloc</strong> diu si es carreguen i què se sap, i què no, de la <strong>memòria cau</strong> del seu servidor.'],
  ['Correcció · Els vídeos, només quan els demanes', 'Els <strong>vídeos</strong> de les targetes i de les fitxes ja <strong>no es baixen</strong> en obrir la pàgina: s’hi veu la seua <strong>imatge</strong>, si en tenen, i el vídeo arriba quan algú el <strong>posa en marxa</strong>. Si el <strong>servidor del vídeo</strong> no respon, la pàgina ja <strong>no ho nota</strong>.']],
 es: ['21 de noviembre de 2026, noche · Oleadas R32.29 a R32.33 · El Atles 2D en Diseño, cada sesión con sus datos y el lector de pantalla en tu idioma',
  'Las Oleadas R32.29 a R32.33 de <strong>Sóc de Poble</strong> hacen la plataforma más <strong>fuerte</strong> por dentro. Cada <strong>sesión</strong> se queda con sus <strong>datos</strong>; el <strong>lector de pantalla</strong> habla el <strong>idioma elegido</strong> en muchas más pantallas; y las pantallas aguantan mejor una <strong>fecha</strong> o un <strong>importe extraño</strong>.',
  'Las aplicaciones pasan a la <strong>versión 1.2.19 (build 24)</strong> en el <strong>repositorio</strong> y, cuando se escribe esta crónica, la versión todavía <strong>no consta en ninguna tienda</strong>. El <strong>conector de WordPress</strong> publicado en WordPress.org es la <strong>1.1.26</strong>; la 1.1.27 del repositorio <strong>todavía no se ha publicado</strong>.',
  'Cuando se escribe esta crónica, la versión <strong>no cambia nada</strong> en el <strong>servidor de Sóc de Poble</strong>. Los <strong>avisos del chat</strong> en las aplicaciones del móvil todavía <strong>no están encendidos</strong>, la <strong>política de privacidad</strong> sigue en la <strong>versión 2.5</strong>, y encender los avisos depende de una <strong>decisión del Mestre</strong>.',
  ['Novedad · El Atles 2D, en Diseño', `En ${enllacIntern(ENLLAC_DISSENY, 'Diseño')}, la carpeta <strong>Atles 2D</strong> reúne en <strong>cinco páginas</strong> el estudio de un <strong>pueblo virtual</strong>, el del Assaig a la Plaça, con <strong>vecinos simulados</strong>, doce <strong>redes del mundo</strong>, el <strong>mapa de las cinco entidades</strong> y una propuesta de <strong>motor de estudios</strong>. Es un estudio para decidir: no añade ninguna función nueva, y la carpeta Inventari ahora se llama Recursos. Las cinco páginas están en valenciano.`],
  ['Mejora · Cada sesión, con sus datos', `Si en el <strong>mismo aparato</strong> alguien <strong>cierra la sesión</strong> y abre otra, el ${enllacIntern(ENLLAC_PERFIL, 'perfil')} y la IAIA ya <strong>no muestran</strong> ninguna <strong>respuesta</strong> que llegue tarde de la primera, y una <strong>denuncia</strong> que se estaba enviando con la primera <strong>no sale</strong> con la segunda.`],
  ['Mejora · El lector de pantalla, en tu idioma', 'Las <strong>etiquetas</strong> que lee el <strong>lector de pantalla</strong> y los <strong>textos de ayuda</strong> de los campos hablan el <strong>idioma elegido</strong> de entre los <strong>cinco</strong> en muchas más pantallas, como el <strong>Muro</strong>, el Calendario, los Dispositivos, el Perfil, la <strong>Gestoría</strong> y los paneles de administración.'],
  ['Mejora · Pantallas más resistentes', 'Una <strong>fecha imposible</strong> guardada en el aparato ya no rompe los <strong>créditos</strong> de la <strong>ficha de un pueblo</strong>; y la <strong>Gestoría</strong>, el <strong>Bar</strong> y otras aplicaciones pequeñas aguantan mejor las <strong>fechas</strong> y los <strong>importes</strong> que faltan o que no cuadran.'],
  ['Mejora · Las hojas de la Salud, en tu idioma', 'Al <strong>exportar</strong> la hoja de la <strong>Salud</strong>, los <strong>nombres</strong> de las columnas salen en el <strong>idioma elegido</strong>, y al <strong>importarla</strong> se reconocen en cualquiera de los cinco. Una hoja exportada en un idioma que no sea el valenciano solo la lee esta <strong>versión</strong> o una más nueva.'],
  ['Mejora · Una ficha, una sola dirección', 'Si alguien escribe la dirección de la <strong>ficha de un pueblo</strong> o de un <strong>producto</strong> con alguna <strong>letra en código</strong>, como %61 en lugar de la «a», la ficha dice a los <strong>buscadores</strong> que es la <strong>misma</strong>, con su <strong>dirección limpia</strong>, y no una nueva.'],
  ['Mejora · El conector de WordPress 1.1.27', 'Los <strong>ajustes</strong> del conector <strong>dejan de cargarse</strong> en cada página del WordPress (si el conector ya estaba, desde que un <strong>administrador</strong> abre el <strong>escritorio</strong>), y la pantalla de <strong>Salud del sitio</strong> dice si se cargan y qué se sabe, y qué no, de la <strong>memoria caché</strong> de su servidor.'],
  ['Corrección · Los vídeos, solo cuando los pides', 'Los <strong>vídeos</strong> de las tarjetas y de las fichas ya <strong>no se descargan</strong> al abrir la página: se ve su <strong>imagen</strong>, si la tienen, y el vídeo llega cuando alguien lo <strong>pone en marcha</strong>. Si el <strong>servidor del vídeo</strong> no responde, la página ya <strong>no lo nota</strong>.']],
 en: ['21 November 2026, night · Waves R32.29 to R32.33 · The Atles 2D in Design, each session with its own data and the screen reader in your language',
  'Waves R32.29 to R32.33 of <strong>Sóc de Poble</strong> make the platform <strong>stronger</strong> on the inside. Each <strong>session</strong> keeps its own <strong>data</strong>; the <strong>screen reader</strong> speaks the <strong>chosen language</strong> on many more screens; and screens cope better with an odd <strong>date</strong> or <strong>amount</strong>.',
  'The applications move to <strong>version 1.2.19 (build 24)</strong> in the <strong>repository</strong> and, at the time of writing, the version is <strong>not listed in any store</strong>. The <strong>WordPress connector</strong> published on WordPress.org is <strong>1.1.26</strong>; 1.1.27 in the repository <strong>has not been published yet</strong>.',
  'At the time of writing, the version <strong>changes nothing</strong> on the <strong>Sóc de Poble server</strong>. <strong>Chat notifications</strong> in the mobile apps are still <strong>not switched on</strong>, the <strong>privacy policy</strong> stays at <strong>version 2.5</strong>, and switching notifications on depends on <strong>the Mestre’s decision</strong>.',
  ['New · The Atles 2D, in Design', `In ${enllacIntern(ENLLAC_DISSENY, 'Design')}, the <strong>Atles 2D</strong> folder brings together in <strong>five pages</strong> the study of the <strong>virtual village</strong> from the Assaig a la Plaça, with <strong>simulated neighbours</strong>, twelve <strong>networks from around the world</strong>, the <strong>map of the five entities</strong> and a proposal for a <strong>study engine</strong>. It is a study to help decide: it adds no new feature, and the Inventari folder is now called Recursos. The five pages are in Valencian.`],
  ['Improvement · Each session, with its own data', `If someone <strong>signs out</strong> on the <strong>same device</strong> and opens another session, the ${enllacIntern(ENLLAC_PERFIL, 'profile')} and IAIA <strong>no longer show</strong> any late <strong>reply</strong> meant for the first one, and a <strong>report</strong> that was being sent with the first one <strong>does not go out</strong> with the second.`],
  ['Improvement · The screen reader, in your language', 'The <strong>labels</strong> read by the <strong>screen reader</strong> and the <strong>help texts</strong> in fields speak the <strong>chosen language</strong>, out of the <strong>five</strong>, on many more screens, such as the <strong>Wall</strong>, the Calendar, Devices, the Profile, <strong>Management</strong> and the administration panels.'],
  ['Improvement · Sturdier screens', 'An <strong>impossible date</strong> saved on the device no longer breaks the <strong>credits</strong> on a <strong>village page</strong>; and <strong>Management</strong>, the <strong>Bar</strong> and other small apps cope better with <strong>dates</strong> and <strong>amounts</strong> that are missing or do not add up.'],
  ['Improvement · Health sheets, in your language', 'When you <strong>export</strong> the <strong>Health</strong> sheet, the <strong>names</strong> of the columns come out in the <strong>chosen language</strong>, and when you <strong>import</strong> it they are recognised in any of the five. A sheet exported in a language other than Valencian can only be read by this <strong>version</strong> or a newer one.'],
  ['Improvement · One page, one address', 'If someone writes the address of a <strong>village page</strong> or a <strong>product page</strong> with a <strong>letter in code</strong>, such as %61 instead of “a”, the page tells <strong>search engines</strong> that it is the <strong>same page</strong>, with its <strong>clean address</strong>, and not a new one.'],
  ['Improvement · The WordPress connector 1.1.27', 'The connector’s <strong>settings</strong> <strong>stop loading</strong> on every WordPress page (if the connector was already installed, once an <strong>administrator</strong> opens the <strong>dashboard</strong>), and the <strong>Site Health</strong> screen says whether they load and what is known, and not known, about its server’s <strong>memory cache</strong>.'],
  ['Fix · Videos, only when you ask for them', '<strong>Videos</strong> on cards and pages are <strong>no longer downloaded</strong> when the page opens: their <strong>image</strong> is shown, if they have one, and the video only arrives when someone <strong>starts it</strong>. If the <strong>video server</strong> does not respond, the page <strong>no longer notices</strong>.']],
 eu: ['2026ko azaroaren 21a, gaua · R32.29tik R32.33ra bitarteko olatuak · Atles 2D Diseinuan, saio bakoitza bere datuekin eta pantaila-irakurgailua zure hizkuntzan',
  '<strong>Sóc de Poble</strong>ren R32.29tik R32.33ra bitarteko olatuek plataforma <strong>sendoagoa</strong> egiten dute barrutik. <strong>Saio</strong> bakoitzak bere <strong>datuak</strong> gordetzen ditu; <strong>pantaila-irakurgailuak</strong> <strong>aukeratutako hizkuntza</strong> erabiltzen du pantaila askoz gehiagotan; eta pantailek hobeto jasaten dute <strong>data edo zenbateko arraro</strong> bat.',
  'Aplikazioak <strong>1.2.19 bertsiora (24. builda)</strong> igarotzen dira <strong>biltegian</strong>, eta kronika hau idazten den unean bertsio hori <strong>ez dago inongo dendatan</strong> oraindik. WordPress.org-en argitaratutako <strong>WordPress konektorea</strong> <strong>1.1.26</strong> da; biltegiko 1.1.27 <strong>ez da oraindik argitaratu</strong>.',
  'Kronika hau idazten den unean, bertsio honek <strong>ez du ezer aldatzen</strong> <strong>Sóc de Pobleren zerbitzarian</strong>. Mugikorreko aplikazioetako <strong>txateko abisuak</strong> oraindik <strong>ez daude piztuta</strong>, <strong>pribatutasun-politika</strong> <strong>2.5 bertsioan</strong> dago oraindik, eta abisuak piztea <strong>Mestreren erabakiaren</strong> menpe dago.',
  ['Berritasuna · Atles 2D, Diseinuan', `${enllacIntern(ENLLAC_DISSENY, 'Diseinuan')}, <strong>Atles 2D</strong> karpetak <strong>bost orritan</strong> biltzen ditu Assaig a la Plaçako <strong>herri birtualaren</strong> azterketa, <strong>herritar simulatuekin</strong>, munduko hamabi <strong>sare</strong>, <strong>bost entitateen mapa</strong> eta <strong>azterketa-motor</strong> baten proposamena. Erabakitzeko azterketa bat da: ez du funtzio berririk gehitzen, eta Inventari karpetak Recursos du izena orain. Bost orriak valentzieraz daude.`],
  ['Hobekuntza · Saio bakoitza, bere datuekin', `<strong>Gailu berean</strong> norbaitek <strong>saioa ixten</strong> badu eta beste bat irekitzen badu, ${enllacIntern(ENLLAC_PERFIL, 'profilak')} eta IAIAk <strong>ez dute gehiago erakusten</strong> lehenengoaren berandu iristen den <strong>erantzunik</strong>, eta lehenengoarekin bidaltzen ari zen <strong>salaketa</strong> bat <strong>ez da ateratzen</strong> bigarrenarekin.`],
  ['Hobekuntza · Pantaila-irakurgailua, zure hizkuntzan', '<strong>Pantaila-irakurgailuak</strong> irakurtzen dituen <strong>etiketek</strong> eta eremuetako <strong>laguntza-testuek</strong> <strong>aukeratutako hizkuntza</strong> erabiltzen dute, <strong>bost</strong> hizkuntzen artean, pantaila askoz gehiagotan, hala nola <strong>Horman</strong>, Egutegian, Gailuetan, Profilean, <strong>Gestorian</strong> eta administrazio-paneletan.'],
  ['Hobekuntza · Pantaila sendoagoak', 'Gailuan gordetako <strong>data ezinezko</strong> batek ez ditu gehiago <strong>herri baten fitxako</strong> <strong>kredituak</strong> hausten; eta <strong>Gestoriak</strong>, <strong>Tabernak</strong> eta beste aplikazio txiki batzuek hobeto jasaten dituzte falta diren edo bat ez datozen <strong>datak</strong> eta <strong>zenbatekoak</strong>.'],
  ['Hobekuntza · Osasunaren orriak, zure hizkuntzan', '<strong>Osasunaren</strong> orria <strong>esportatzean</strong>, zutabeen <strong>izenak</strong> <strong>aukeratutako hizkuntzan</strong> ateratzen dira, eta <strong>inportatzean</strong> bostetako edozeinetan ezagutzen dira. Valentziera ez den hizkuntza batean esportatutako orria <strong>bertsio honek</strong> edo berriago batek bakarrik irakurtzen du.'],
  ['Hobekuntza · Fitxa bat, helbide bakarra', 'Norbaitek <strong>herri baten fitxaren</strong> edo <strong>produktu baten</strong> helbidea <strong>kodetutako letra</strong> batekin idazten badu, adibidez %61 «a»-ren ordez, fitxak <strong>bilatzaileei</strong> esaten die <strong>fitxa bera</strong> dela, bere <strong>helbide garbiarekin</strong>, eta ez berri bat.'],
  ['Hobekuntza · WordPress konektorea 1.1.27', 'Konektorearen <strong>ezarpenak</strong> <strong>ez dira gehiago kargatzen</strong> WordPressen orri guztietan (konektorea lehendik bazegoen, <strong>administratzaile</strong> batek <strong>Arbela</strong> irekitzen duenetik), eta <strong>Gunearen osasuna</strong> pantailak esaten du kargatzen diren eta zer dakigun, eta zer ez, zerbitzariaren <strong>memoria-cacheari</strong> buruz.'],
  ['Zuzenketa · Bideoak, eskatzen dituzunean bakarrik', 'Txarteletako eta fitxetako <strong>bideoak</strong> <strong>ez dira gehiago deskargatzen</strong> orria irekitzean: haien <strong>irudia</strong> ikusten da, baldin badute, eta bideoa norbaitek <strong>abiarazten</strong> duenean iristen da. <strong>Bideoaren zerbitzariak</strong> erantzuten ez badu, orriak <strong>ez du gehiago nabaritzen</strong>.']],
 gl: ['21 de novembro de 2026, noite · Ondas R32.29 a R32.33 · O Atles 2D en Deseño, cada sesión cos seus datos e o lector de pantalla no teu idioma',
  'As Ondas R32.29 a R32.33 de <strong>Sóc de Poble</strong> fan a plataforma máis <strong>forte</strong> por dentro. Cada <strong>sesión</strong> queda cos seus <strong>datos</strong>; o <strong>lector de pantalla</strong> fala o <strong>idioma escollido</strong> en moitas máis pantallas; e as pantallas aguantan mellor unha <strong>data</strong> ou un <strong>importe estraño</strong>.',
  'As aplicacións pasan á <strong>versión 1.2.19 (build 24)</strong> no <strong>repositorio</strong> e, cando se escribe esta crónica, a versión aínda <strong>non consta en ningunha tenda</strong>. O <strong>conector de WordPress</strong> publicado en WordPress.org é a <strong>1.1.26</strong>; a 1.1.27 do repositorio <strong>aínda non se publicou</strong>.',
  'Cando se escribe esta crónica, a versión <strong>non cambia nada</strong> no <strong>servidor de Sóc de Poble</strong>. Os <strong>avisos do chat</strong> nas aplicacións do móbil aínda <strong>non están acesos</strong>, a <strong>política de privacidade</strong> segue na <strong>versión 2.5</strong>, e acender os avisos depende dunha <strong>decisión do Mestre</strong>.',
  ['Novidade · O Atles 2D, en Deseño', `En ${enllacIntern(ENLLAC_DISSENY, 'Deseño')}, o cartafol <strong>Atles 2D</strong> reúne en <strong>cinco páxinas</strong> o estudo dun <strong>pobo virtual</strong>, o do Assaig a la Plaça, con <strong>veciños simulados</strong>, doce <strong>redes do mundo</strong>, o <strong>mapa das cinco entidades</strong> e unha proposta de <strong>motor de estudos</strong>. É un estudo para decidir: non engade ningunha función nova, e o cartafol Inventari chámase agora Recursos. As cinco páxinas están en valenciano.`],
  ['Mellora · Cada sesión, cos seus datos', `Se no <strong>mesmo aparello</strong> alguén <strong>pecha a sesión</strong> e abre outra, o ${enllacIntern(ENLLAC_PERFIL, 'perfil')} e a IAIA xa <strong>non amosan</strong> ningunha <strong>resposta</strong> que chegue tarde da primeira, e unha <strong>denuncia</strong> que se estaba a enviar coa primeira <strong>non sae</strong> coa segunda.`],
  ['Mellora · O lector de pantalla, no teu idioma', 'As <strong>etiquetas</strong> que le o <strong>lector de pantalla</strong> e os <strong>textos de axuda</strong> dos campos falan o <strong>idioma escollido</strong> de entre os <strong>cinco</strong> en moitas máis pantallas, como o <strong>Muro</strong>, o Calendario, os Dispositivos, o Perfil, a <strong>Xestoría</strong> e os paneis de administración.'],
  ['Mellora · Pantallas máis resistentes', 'Unha <strong>data imposible</strong> gardada no aparello xa non rompe os <strong>créditos</strong> da <strong>ficha dun pobo</strong>; e a <strong>Xestoría</strong>, o <strong>Bar</strong> e outras aplicacións pequenas aguantan mellor as <strong>datas</strong> e os <strong>importes</strong> que faltan ou que non cadran.'],
  ['Mellora · As follas da Saúde, no teu idioma', 'Ao <strong>exportar</strong> a folla da <strong>Saúde</strong>, os <strong>nomes</strong> das columnas saen no <strong>idioma escollido</strong>, e ao <strong>importala</strong> recoñécense en calquera dos cinco. Unha folla exportada nun idioma que non sexa o valenciano só a le esta <strong>versión</strong> ou unha máis nova.'],
  ['Mellora · Unha ficha, un só enderezo', 'Se alguén escribe o enderezo da <strong>ficha dun pobo</strong> ou dun <strong>produto</strong> cunha <strong>letra en código</strong>, como %61 en lugar da «a», a ficha dilles aos <strong>buscadores</strong> que é a <strong>mesma</strong>, co seu <strong>enderezo limpo</strong>, e non unha nova.'],
  ['Mellora · O conector de WordPress 1.1.27', 'Os <strong>axustes</strong> do conector <strong>deixan de cargarse</strong> en cada páxina do WordPress (se o conector xa estaba, desde que un <strong>administrador</strong> abre o <strong>escritorio</strong>), e a pantalla de <strong>Saúde do sitio</strong> di se se cargan e que se sabe, e que non, da <strong>memoria caché</strong> do seu servidor.'],
  ['Corrección · Os vídeos, só cando os pides', 'Os <strong>vídeos</strong> das tarxetas e das fichas xa <strong>non se descargan</strong> ao abrir a páxina: vese a súa <strong>imaxe</strong>, se a teñen, e o vídeo chega cando alguén o <strong>pon en marcha</strong>. Se o <strong>servidor do vídeo</strong> non responde, a páxina xa <strong>non o nota</strong>.']]
};

const fitaR32_33 = (language) => {
 const [titol, obertura, abast, migracio, ...apartats] = FITA_R32_33[language];
 return `${section('h3', titol, obertura, abast, migracio)}\n      ${apartats.map(([t, c]) => subSection(t, c)).join('\n      ')}\n\n      `;
};

export const FITA_R32_28 = {
 ca: ['21 de novembre de 2026, nit · Onades R32.27 i R32.28 · La IAIA amb el seu nom, una «Lletra gran» més compacta i enllaços honestos',
  `Les Onades R32.27 i R32.28 de <strong>Sóc de Poble</strong> fan la plataforma més <strong>clara</strong> i més <strong>honesta</strong>. A la barra de dalt, el botó de la IAIA porta el seu <strong>nom escrit</strong>; a l’accés del ${enllacIntern(ENLLAC_XAT_R32_28, 'Xat')}, la <strong>«Lletra gran»</strong> és <strong>més compacta</strong>; i els <strong>enllaços</strong> i les pàgines dels pobles diuen la <strong>veritat</strong> als cercadors.`,
  'Les aplicacions passen a la <strong>versió 1.2.18 (build 23)</strong> al <strong>repositori</strong> i, quan s’escriu esta crònica, la versió encara <strong>no consta a cap botiga</strong>. El <strong>connector de WordPress</strong> publicat a WordPress.org és la <strong>1.1.25</strong>; la 1.1.26 del repositori <strong>encara no s’ha publicat</strong>.',
  'Quan s’escriu esta crònica, la versió <strong>no canvia res</strong> al <strong>servidor de Sóc de Poble</strong>. Els <strong>avisos del xat</strong> a les aplicacions del mòbil encara <strong>no estan encesos</strong>, la <strong>política de privacitat</strong> continua en la <strong>versió 2.5</strong>, i encendre els avisos depén d’una <strong>decisió del Mestre</strong>.',
  ['Novetat · La IAIA, amb el seu nom', 'A la barra negra de dalt, el botó de la IAIA porta escrit el seu <strong>nom</strong> al costat del <strong>dibuix de la iaia</strong>. A l’<strong>Assaig a la Plaça</strong>, l’estudi amb <strong>veïns simulats</strong>, una <strong>veïna gran</strong> el confonia amb el botó de la <strong>«Lletra gran»</strong>; ara cada un es reconeix a la primera.'],
  ['Millora · La «Lletra gran», més compacta', `A l’accés del ${enllacIntern(ENLLAC_XAT_R32_28, 'Xat')}, el botó <strong>«Lletra gran»</strong> és més <strong>compacte</strong>: en lloc d’una <strong>pastilla de text</strong>, un <strong>cercle buit</strong> o una <strong>marca</strong> diu si està encés, i el botó ocupa <strong>menys espai</strong>.`],
  ['Millora · Enllaços honestos', 'Els <strong>enllaços</strong> que la gent posa als <strong>textos publicats</strong> porten la marca de <strong>contingut d’usuari</strong>, i els <strong>patrocinats</strong>, la de patrocinat, també quan el text es <strong>traduïx</strong> o porta un <strong>vídeo</strong>. Així els <strong>cercadors</strong> saben que Sóc de Poble no els recomana.'],
  ['Millora · Les pàgines dels pobles, sense trampes', 'Les pàgines dels <strong>pobles</strong> només es mostren als <strong>cercadors</strong> quan tenen un <strong>text propi revisat</strong>. Es poden <strong>compartir</strong> igualment, però sense eixe text no compten com a <strong>pàgines de contingut</strong>.'],
  ['Millora · El connector de WordPress 1.1.26', 'En <strong>desinstal·lar-se</strong>, el <strong>connector de WordPress</strong> també esborra les <strong>dues claus</strong> de Sóc de Poble de la <strong>caixa de secrets</strong> de WordPress, si en té, i esborra de la <strong>memòria</strong> les claus de <strong>traducció</strong> després d’usar-les, quan WordPress ho permet.']],
 es: ['21 de noviembre de 2026, noche · Oleadas R32.27 y R32.28 · La IAIA con su nombre, una «Letra grande» más compacta y enlaces honestos',
  `Las Oleadas R32.27 y R32.28 de <strong>Sóc de Poble</strong> hacen la plataforma más <strong>clara</strong> y más <strong>honesta</strong>. En la barra de arriba, el botón de la IAIA lleva su <strong>nombre escrito</strong>; en el acceso al ${enllacIntern(ENLLAC_XAT_R32_28, 'Chat')}, la <strong>«Letra grande»</strong> es <strong>más compacta</strong>; y los <strong>enlaces</strong> y las páginas de los pueblos dicen la <strong>verdad</strong> a los buscadores.`,
  'Las aplicaciones pasan a la <strong>versión 1.2.18 (build 23)</strong> en el <strong>repositorio</strong> y, cuando se escribe esta crónica, la versión todavía <strong>no consta en ninguna tienda</strong>. El <strong>conector de WordPress</strong> publicado en WordPress.org es la <strong>1.1.25</strong>; la 1.1.26 del repositorio <strong>todavía no se ha publicado</strong>.',
  'Cuando se escribe esta crónica, la versión <strong>no cambia nada</strong> en el <strong>servidor de Sóc de Poble</strong>. Los <strong>avisos del chat</strong> en las aplicaciones del móvil todavía <strong>no están encendidos</strong>, la <strong>política de privacidad</strong> sigue en la <strong>versión 2.5</strong>, y encender los avisos depende de una <strong>decisión del Mestre</strong>.',
  ['Novedad · La IAIA, con su nombre', 'En la barra negra de arriba, el botón de la IAIA lleva escrito su <strong>nombre</strong> junto al <strong>dibujo de la abuela</strong>. En el <strong>Assaig a la Plaça</strong>, el estudio con <strong>vecinos simulados</strong>, una <strong>vecina mayor</strong> lo confundía con el botón de la <strong>«Letra grande»</strong>; ahora cada uno se reconoce a la primera.'],
  ['Mejora · La «Letra grande», más compacta', `En el acceso al ${enllacIntern(ENLLAC_XAT_R32_28, 'Chat')}, el botón <strong>«Letra grande»</strong> es más <strong>compacto</strong>: en lugar de una <strong>pastilla de texto</strong>, un <strong>círculo vacío</strong> o una <strong>marca</strong> dice si está encendido, y el botón ocupa <strong>menos espacio</strong>.`],
  ['Mejora · Enlaces honestos', 'Los <strong>enlaces</strong> que la gente pone en los <strong>textos publicados</strong> llevan la marca de <strong>contenido de usuario</strong>, y los <strong>patrocinados</strong>, la de patrocinado, también cuando el texto se <strong>traduce</strong> o lleva un <strong>vídeo</strong>. Así los <strong>buscadores</strong> saben que Sóc de Poble no los recomienda.'],
  ['Mejora · Las páginas de los pueblos, sin trampas', 'Las páginas de los <strong>pueblos</strong> solo se muestran a los <strong>buscadores</strong> cuando tienen un <strong>texto propio revisado</strong>. Se pueden <strong>compartir</strong> igualmente, pero sin ese texto no cuentan como <strong>páginas de contenido</strong>.'],
  ['Mejora · El conector de WordPress 1.1.26', 'Al <strong>desinstalarse</strong>, el <strong>conector de WordPress</strong> también borra las <strong>dos claves</strong> de Sóc de Poble de la <strong>caja de secretos</strong> de WordPress, si la tiene, y borra de la <strong>memoria</strong> las claves de <strong>traducción</strong> después de usarlas, cuando WordPress lo permite.']],
 en: ['21 November 2026, night · Waves R32.27 and R32.28 · IAIA with its name, a more compact “Large text” and honest links',
  `Waves R32.27 and R32.28 of <strong>Sóc de Poble</strong> make the platform <strong>clearer</strong> and more <strong>honest</strong>. In the top bar, the IAIA button shows its <strong>name in writing</strong>; at the ${enllacIntern(ENLLAC_XAT_R32_28, 'Chat')} entrance, <strong>“Large text”</strong> is <strong>more compact</strong>; and <strong>links</strong> and village pages tell search engines the <strong>truth</strong>.`,
  'The applications move to <strong>version 1.2.18 (build 23)</strong> in the <strong>repository</strong> and, at the time of writing, the version is <strong>not listed in any store</strong>. The <strong>WordPress connector</strong> published on WordPress.org is <strong>1.1.25</strong>; 1.1.26 in the repository <strong>has not been published yet</strong>.',
  'At the time of writing, the version <strong>changes nothing</strong> on the <strong>Sóc de Poble server</strong>. <strong>Chat notifications</strong> in the mobile apps are still <strong>not switched on</strong>, the <strong>privacy policy</strong> stays at <strong>version 2.5</strong>, and switching notifications on depends on <strong>the Mestre’s decision</strong>.',
  ['New · IAIA, with its name', 'In the black top bar, the IAIA button shows its <strong>name</strong> next to the <strong>drawing of the grandmother</strong>. In the <strong>Assaig a la Plaça</strong>, the study with <strong>simulated neighbours</strong>, an <strong>older neighbour</strong> mistook it for the <strong>“Large text”</strong> button; now each one is recognised at first sight.'],
  ['Improvement · A more compact “Large text”', `At the ${enllacIntern(ENLLAC_XAT_R32_28, 'Chat')} entrance, the <strong>“Large text”</strong> button is more <strong>compact</strong>: instead of a <strong>text label</strong>, an <strong>empty circle</strong> or a <strong>tick</strong> shows whether it is on, and the button takes up <strong>less space</strong>.`],
  ['Improvement · Honest links', '<strong>Links</strong> that people put in <strong>published texts</strong> carry the <strong>user content</strong> mark, and <strong>sponsored</strong> ones the sponsored mark, also when the text is <strong>translated</strong> or includes a <strong>video</strong>. That way <strong>search engines</strong> know that Sóc de Poble does not endorse them.'],
  ['Improvement · Village pages, no tricks', 'Pages for <strong>villages</strong> are only shown to <strong>search engines</strong> when they have a <strong>reviewed text of their own</strong>. They can still be <strong>shared</strong>, but without that text they do not count as <strong>content pages</strong>.'],
  ['Improvement · The WordPress connector 1.1.26', 'When <strong>uninstalled</strong>, the <strong>WordPress connector</strong> also deletes the <strong>two Sóc de Poble keys</strong> from the WordPress <strong>secrets box</strong>, if there is one, and wipes the <strong>translation</strong> keys from <strong>memory</strong> after using them, when WordPress allows it.']],
 eu: ['2026ko azaroaren 21a, gaua · R32.27 eta R32.28 olatuak · IAIA bere izenarekin, «Letra handia» trinkoagoa eta esteka zintzoak',
  `<strong>Sóc de Poble</strong>ren R32.27 eta R32.28 olatuek plataforma <strong>argiagoa</strong> eta <strong>zintzoagoa</strong> egiten dute. Goiko barran, IAIAren botoiak bere <strong>izena idatzita</strong> darama; ${enllacIntern(ENLLAC_XAT_R32_28, 'Txataren')} sarreran, <strong>«Letra handia»</strong> <strong>trinkoagoa</strong> da; eta <strong>estekek</strong> eta herrien orriek egia esaten diete bilatzaileei.`,
  'Aplikazioak <strong>1.2.18 bertsiora (23. builda)</strong> igarotzen dira <strong>biltegian</strong>, eta kronika hau idazten den unean bertsio hori <strong>ez dago inongo dendatan</strong> oraindik. WordPress.org-en argitaratutako <strong>WordPress konektorea</strong> <strong>1.1.25</strong> da; biltegiko 1.1.26 <strong>ez da oraindik argitaratu</strong>.',
  'Kronika hau idazten den unean, bertsio honek <strong>ez du ezer aldatzen</strong> <strong>Sóc de Pobleren zerbitzarian</strong>. Mugikorreko aplikazioetako <strong>txateko abisuak</strong> oraindik <strong>ez daude piztuta</strong>, <strong>pribatutasun-politika</strong> <strong>2.5 bertsioan</strong> dago oraindik, eta abisuak piztea <strong>Mestreren erabakiaren</strong> menpe dago.',
  ['Berritasuna · IAIA, bere izenarekin', 'Goiko barra beltzean, IAIAren botoiak bere <strong>izena</strong> darama idatzita, <strong>amonaren marrazkiaren</strong> ondoan. <strong>Assaig a la Plaça</strong>n, <strong>herritar simulatuekin</strong> egindako azterketan, <strong>auzokide adindu</strong> batek <strong>«Letra handia»</strong> botoiarekin nahasten zuen; orain bakoitza lehen begiradan ezagutzen da.'],
  ['Hobekuntza · «Letra handia», trinkoagoa', `${enllacIntern(ENLLAC_XAT_R32_28, 'Txataren')} sarreran, <strong>«Letra handia»</strong> botoia <strong>trinkoagoa</strong> da: <strong>testu-etiketa</strong> baten ordez, <strong>zirkulu huts</strong> batek edo <strong>marka</strong> batek esaten du piztuta dagoen, eta botoiak <strong>leku gutxiago</strong> hartzen du.`],
  ['Hobekuntza · Esteka zintzoak', 'Jendeak <strong>argitaratutako testuetan</strong> jartzen dituen <strong>estekek</strong> <strong>erabiltzailearen edukiaren</strong> marka daramate, eta <strong>babestuek</strong> babestuaren marka, baita testua <strong>itzultzen</strong> denean edo <strong>bideo</strong> bat duenean ere. Horrela, <strong>bilatzaileek</strong> badakite Sóc de Poblek ez dituela gomendatzen.'],
  ['Hobekuntza · Herrien orriak, tranparik gabe', '<strong>Herrien</strong> orriak <strong>berrikusitako testu propioa</strong> dutenean bakarrik erakusten zaizkie <strong>bilatzaileei</strong>. Partekatu daitezke hala ere, baina testu hori gabe ez dira <strong>eduki-orritzat</strong> hartzen.'],
  ['Hobekuntza · WordPress konektorea 1.1.26', '<strong>Desinstalatzean</strong>, <strong>WordPress konektoreak</strong> Sóc de Pobleren <strong>bi gakoak</strong> ere ezabatzen ditu WordPressen <strong>sekretu-kutxatik</strong>, kutxa hori badago, eta <strong>itzulpen-gakoak</strong> <strong>memoriatik</strong> ezabatzen ditu erabili ondoren, WordPressek uzten duenean.']],
 gl: ['21 de novembro de 2026, noite · Ondas R32.27 e R32.28 · A IAIA co seu nome, unha «Letra grande» máis compacta e ligazóns honestas',
  `As Ondas R32.27 e R32.28 de <strong>Sóc de Poble</strong> fan a plataforma máis <strong>clara</strong> e máis <strong>honesta</strong>. Na barra de arriba, o botón da IAIA leva o seu <strong>nome escrito</strong>; no acceso ao ${enllacIntern(ENLLAC_XAT_R32_28, 'Chat')}, a <strong>«Letra grande»</strong> é <strong>máis compacta</strong>; e as <strong>ligazóns</strong> e as páxinas dos pobos din a <strong>verdade</strong> aos buscadores.`,
  'As aplicacións pasan á <strong>versión 1.2.18 (build 23)</strong> no <strong>repositorio</strong> e, cando se escribe esta crónica, a versión aínda <strong>non consta en ningunha tenda</strong>. O <strong>conector de WordPress</strong> publicado en WordPress.org é a <strong>1.1.25</strong>; a 1.1.26 do repositorio <strong>aínda non se publicou</strong>.',
  'Cando se escribe esta crónica, a versión <strong>non cambia nada</strong> no <strong>servidor de Sóc de Poble</strong>. Os <strong>avisos do chat</strong> nas aplicacións do móbil aínda <strong>non están acesos</strong>, a <strong>política de privacidade</strong> segue na <strong>versión 2.5</strong>, e acender os avisos depende dunha <strong>decisión do Mestre</strong>.',
  ['Novidade · A IAIA, co seu nome', 'Na barra negra de arriba, o botón da IAIA leva escrito o seu <strong>nome</strong> xunto ao <strong>debuxo da avoa</strong>. No <strong>Assaig a la Plaça</strong>, o estudo con <strong>veciños simulados</strong>, unha <strong>veciña maior</strong> confundíao co botón da <strong>«Letra grande»</strong>; agora cada un recoñécese á primeira.'],
  ['Mellora · A «Letra grande», máis compacta', `No acceso ao ${enllacIntern(ENLLAC_XAT_R32_28, 'Chat')}, o botón <strong>«Letra grande»</strong> é máis <strong>compacto</strong>: en lugar dunha <strong>pastilla de texto</strong>, un <strong>círculo baleiro</strong> ou unha <strong>marca</strong> di se está aceso, e o botón ocupa <strong>menos espazo</strong>.`],
  ['Mellora · Ligazóns honestas', 'As <strong>ligazóns</strong> que a xente pon nos <strong>textos publicados</strong> levan a marca de <strong>contido de usuario</strong>, e as <strong>patrocinadas</strong>, a de patrocinada, tamén cando o texto se <strong>traduce</strong> ou leva un <strong>vídeo</strong>. Así os <strong>buscadores</strong> saben que Sóc de Poble non as recomenda.'],
  ['Mellora · As páxinas dos pobos, sen trampas', 'As páxinas dos <strong>pobos</strong> só se amosan aos <strong>buscadores</strong> cando teñen un <strong>texto propio revisado</strong>. Pódense <strong>compartir</strong> igualmente, pero sen ese texto non contan como <strong>páxinas de contido</strong>.'],
  ['Mellora · O conector de WordPress 1.1.26', 'Ao <strong>desinstalarse</strong>, o <strong>conector de WordPress</strong> tamén borra as <strong>dúas claves</strong> de Sóc de Poble da <strong>caixa de segredos</strong> de WordPress, se a ten, e borra da <strong>memoria</strong> as claves de <strong>tradución</strong> despois de usalas, cando WordPress o permite.']]
};

const fitaR32_28 = (language) => {
 const [titol, obertura, abast, migracio, ...apartats] = FITA_R32_28[language];
 return `${section('h3', titol, obertura, abast, migracio)}\n      ${apartats.map(([t, c]) => subSection(t, c)).join('\n      ')}\n\n      `;
};

/* Onada v1.2.17 (21-11-2026, vesprada; ordre del Mestre de les 16:03, IDEA-313; prompt 261121_1606) · La crònica de la
   versió 1.2.17 (build 22) del repositori, amb el que ha aterrat de veres al worktree d'integració r26-fusio: Gemini
   R32.26 (lots 1, 2 i 3 i la costura del mode de taulell), Codex R32.25 (lots 2 i 3) i el carril de Claude. Cada fet té el
   seu consumidor a l'arbre, i la prova (pageContent.versions.test.js, describe «Onades R32.25 i R32.26») el llig:
   · la benvinguda del Foraster (IDEA-313, literal del Mestre): sections/xat/components/AcollidaForasterXat.jsx i el seu
     model (acollidaForasterXatModel.js, TEXTOS_BENVINGUDA_FORASTER en cinc llengües; la creu la recorda amb
     desaBenvingudaForasterTancada), muntada a dalt de la llista de sections/xat/XatSection.jsx (senseSessio i esAterratge);
   · el Rebost en rajoles (Gemini R32.26, lot 1): l'àlies /app/rebost d'apps/plataforma/RutaApps.jsx, la vista inicial
     'rajola' d'apps/nevera/vistes/RebostWorkspace.jsx, forma="rajoles" d'apps/nevera/vistes/Compra.jsx i els pictogrames
     d'apps/nevera/vistes/vestits.js;
   · la caixa de prova del Bar (lot 2): apps/bar/vistes/TpvDemoLocal.jsx, les icones de les onze famílies
     (apps/bar/vistes/vestits.js) i la banda de proves plegable (PedraSeca/molecules/BandaBetaMicroApp.jsx);
   · la Wiki amb portada pròpia (lot 3): wikidepoble_vinyeta (sections/wiki-de-poble/wikiDePobleModel.js, copyDePortada) i
     el mestreDetall de WikiDePobleSection.jsx; el mode de taulell: chrome 'feed' de components/universal/UniversalUtils.js
     i PageFrame.jsx (sense el tercer logotip ni l'entradeta; el botó de lectura en veu es queda, Gauntlet R1 L3-01), activat al
     Mur, al Mercat i al Calendari (costura 02), amb el seu full diferit (estilsTaulellFeed.js);
   · l'assistència guardada de veres (Codex R32.25, lot 2): sections/calendari/rsvpEsdeveniments.js
     (PERSISTENCIA_NO_CONFIRMADA) i la confirmació de QuadreAssistenciaEsdeveniment.jsx, que només ix amb ok;
   · la sessió renovada abans de demanar (P0-ZERO-401-PREFLIGHT, captura del Mestre de les 16:09):
     data/supabase/runtime.js (jwtACaducar i la renovació preventiva amb la guarda C14).
   Llei 0 (què NO diu i per què): la 1.2.17 no consta a cap botiga quan s'escriu (el build 22 naix en este worktree); el
   connector publicat a WordPress.org és la 1.1.24 (SVN r3815297) i la 1.1.25 del repositori no s'ha publicat. No s'aplica
   cap canvi al servidor: la migració de Codex R32.25 (20261121090000, límits dels avisos directes i bàndols, bandera
   push_poble_actiu = 'no') és al repositori i no s'ha aplicat; els avisos del xat a les apps continuen apagats i la
   política és la 2.5. La demostració del Bar no escriu res al servidor ni a cap registre fiscal. No parla del resumidor
   net del Node 0 (Codex R32.25, lot 2), de la retirada del codi mort de l'APK ni dels noms dels productes de referència:
   no tenen pantalla o no els nomena per Apple 2.3.10. La renovació preventiva fa desaparéixer els rebuigs del servidor
   en tornar a la pestanya; no promet res de la xarxa. «L'Assaig a la Plaça» és el nom canònic de l'estudi que ho va
   demanar. Llei 32: «el servidor de Sóc de Poble». */
const ENLLAC_XAT_R32_26 = '/xat';
const ENLLAC_REBOST_R32_26 = '/app/rebost';
const ENLLAC_BAR_R32_26 = '/app/bar';
const ENLLAC_BAR_TPV_R32_26 = '/app/bar/tpv';
const ENLLAC_WIKI_R32_26 = '/wikidepoble';
const ENLLAC_MUR_R32_26 = '/mur';
const ENLLAC_MERCAT_R32_26 = '/mercat';
const ENLLAC_CALENDARI_R32_26 = '/calendari';
export const FITA_R32_26 = {
 ca: ['21 de novembre de 2026, vesprada · Onades R32.25 i R32.26 · La benvinguda del Foraster, el Rebost en rajoles i un TPV del Bar per a provar',
  `Les Onades R32.25 i R32.26 de <strong>Sóc de Poble</strong> porten bona part del que va demanar l’<strong>Assaig a la Plaça</strong>. Qui obri el ${enllacIntern(ENLLAC_XAT_R32_26, 'Xat')} <strong>sense entrar</strong>, el <strong>Foraster</strong>, hi troba una <strong>benvinguda de dues línies</strong> i un sol <strong>«Entrar»</strong>. El ${enllacIntern(ENLLAC_REBOST_R32_26, 'Rebost')} es veu en <strong>rajoles</strong>, el TPV del ${enllacIntern(ENLLAC_BAR_R32_26, 'Bar')} es pot <strong>provar sense entrar</strong>, i el ${enllacIntern(ENLLAC_MUR_R32_26, 'Mur')}, el ${enllacIntern(ENLLAC_MERCAT_R32_26, 'Mercat')} i el ${enllacIntern(ENLLAC_CALENDARI_R32_26, 'Calendari')} ensenyen les seues targetes més amunt.`,
  'Les aplicacions passen a la <strong>versió 1.2.17 (build 22)</strong> al <strong>repositori</strong> i, quan s’escriu esta crònica, la versió encara <strong>no consta a cap botiga</strong>. El <strong>connector de WordPress</strong> publicat a WordPress.org és la <strong>1.1.24</strong>; la 1.1.25 del repositori <strong>encara no s’ha publicat</strong>.',
  'Quan s’escriu esta crònica, la versió <strong>no canvia res</strong> al <strong>servidor de Sóc de Poble</strong>: els límits nous dels avisos són al repositori, però <strong>no s’hi han aplicat</strong>. Els <strong>avisos del xat</strong> a les aplicacions del mòbil encara <strong>no estan encesos</strong>, la <strong>política de privacitat</strong> continua en la <strong>versió 2.5</strong>, i encendre els avisos depén d’una <strong>decisió del Mestre</strong>.',
  ['Novetat · La benvinguda del Foraster', `Qui obri el ${enllacIntern(ENLLAC_XAT_R32_26, 'Xat')} <strong>sense entrar</strong> hi troba una <strong>benvinguda</strong> de dues línies: pot <strong>passejar</strong> i veure qualsevol <strong>informació pública</strong>, i prémer <strong>«Entrar»</strong> quan vulga <strong>connectar</strong> amb la seua gent o treballar en privat. La creu la tanca, i l’aparell <strong>se’n recorda</strong>.`],
  ['Novetat · El Rebost en rajoles', `El ${enllacIntern(ENLLAC_REBOST_R32_26, 'Rebost')} té una <strong>adreça curta</strong> i, al mòbil, s’obri <strong>directament</strong> en la llista. El rebost i la compra es veuen en <strong>rajoles quadrades</strong>, amb el <strong>dibuix de cada aliment</strong>, i a la compra hi ha una diferència clara entre el que hi ha <strong>per comprar</strong> i el que és <strong>fora de la llista</strong>.`],
  ['Novetat · Un TPV del Bar per a provar', `Al ${enllacIntern(ENLLAC_BAR_TPV_R32_26, 'TPV del Bar')}, qui encara <strong>no ha entrat</strong> pot obrir un <strong>TPV de prova</strong>. Funciona <strong>només en eixe aparell</strong>, <strong>no guarda res</strong> al <strong>servidor de Sóc de Poble</strong>, i la nota que trau diu que és <strong>de mostra</strong> i que <strong>no és factura</strong>.`],
  ['Millora · La carta del Bar i la banda de proves', `A la carta del ${enllacIntern(ENLLAC_BAR_R32_26, 'Bar')}, cada producte <strong>sense foto</strong> porta el <strong>dibuix de la seua família</strong>, del <strong>cafè</strong> als licors. Fora del Bar i de la Gestoria, la banda que avisa que una aplicació és <strong>en proves</strong> es pot <strong>plegar</strong>, i l’aparell <strong>se’n recorda</strong>.`],
  ['Millora · La Wiki, amb portada pròpia', `La ${enllacIntern(ENLLAC_WIKI_R32_26, 'Wiki de Poble')} té una <strong>portada pròpia</strong>, amb una <strong>vinyeta</strong> de còmic, i al <strong>mòbil</strong> s’obri <strong>directament</strong> en la portada o en l’article, sense cap <strong>calaix</strong> que la tape.`],
  ['Millora · El Mur, el Mercat i el Calendari, més amunt', `El ${enllacIntern(ENLLAC_MUR_R32_26, 'Mur')}, el ${enllacIntern(ENLLAC_MERCAT_R32_26, 'Mercat')} i el ${enllacIntern(ENLLAC_CALENDARI_R32_26, 'Calendari')} conserven les seues <strong>barres</strong>, el <strong>títol</strong> i el <strong>botó principal</strong>, però ja no repetixen el <strong>logotip</strong> ni l’<strong>entradeta</strong> llarga: les <strong>primeres targetes</strong> apareixen més amunt de la pantalla.`],
  ['Correcció · L’assistència als actes, guardada de veres', `Quan dius si <strong>aniràs</strong> a un acte del ${enllacIntern(ENLLAC_CALENDARI_R32_26, 'Calendari')}, l’aplicació només ho dona per <strong>guardat</strong> quan l’aparell <strong>ho ha guardat</strong> de veres. Si no ha pogut, <strong>no ho confirma</strong> i conserva la <strong>resposta d’abans</strong>.`],
  ['Correcció · La sessió, renovada abans de demanar', 'Si tornes a una <strong>pestanya</strong> que portava <strong>més d’una hora</strong> oberta, l’aplicació <strong>renova la sessió</strong> abans de demanar les dades al <strong>servidor de Sóc de Poble</strong>. Abans, les primeres peticions anaven amb la <strong>sessió caducada</strong>, el servidor les <strong>rebutjava</strong> i l’aplicació les havia de tornar a fer.']],
 es: ['21 de noviembre de 2026, tarde · Oleadas R32.25 y R32.26 · La bienvenida del Forastero, la Despensa en baldosas y un TPV del Bar para probar',
  `Las Oleadas R32.25 y R32.26 de <strong>Sóc de Poble</strong> traen buena parte de lo que pidió el <strong>Assaig a la Plaça</strong>. Quien abre el ${enllacIntern(ENLLAC_XAT_R32_26, 'Chat')} <strong>sin entrar</strong>, el <strong>Forastero</strong>, encuentra una <strong>bienvenida de dos líneas</strong> y un solo <strong>«Entrar»</strong>. La ${enllacIntern(ENLLAC_REBOST_R32_26, 'Despensa')} se ve en <strong>baldosas</strong>, el TPV del ${enllacIntern(ENLLAC_BAR_R32_26, 'Bar')} se puede <strong>probar sin entrar</strong>, y el ${enllacIntern(ENLLAC_MUR_R32_26, 'Muro')}, el ${enllacIntern(ENLLAC_MERCAT_R32_26, 'Mercado')} y el ${enllacIntern(ENLLAC_CALENDARI_R32_26, 'Calendario')} enseñan sus tarjetas más arriba.`,
  'Las aplicaciones pasan a la <strong>versión 1.2.17 (build 22)</strong> en el <strong>repositorio</strong> y, cuando se escribe esta crónica, la versión todavía <strong>no consta en ninguna tienda</strong>. El <strong>conector de WordPress</strong> publicado en WordPress.org es la <strong>1.1.24</strong>; la 1.1.25 del repositorio <strong>todavía no se ha publicado</strong>.',
  'Cuando se escribe esta crónica, la versión <strong>no cambia nada</strong> en el <strong>servidor de Sóc de Poble</strong>: los nuevos límites de los avisos están en el repositorio, pero <strong>no se han aplicado</strong>. Los <strong>avisos del chat</strong> en las aplicaciones del móvil todavía <strong>no están encendidos</strong>, la <strong>política de privacidad</strong> sigue en la <strong>versión 2.5</strong>, y encender los avisos depende de una <strong>decisión del Mestre</strong>.',
  ['Novedad · La bienvenida del Forastero', `Quien abre el ${enllacIntern(ENLLAC_XAT_R32_26, 'Chat')} <strong>sin entrar</strong> encuentra una <strong>bienvenida</strong> de dos líneas: puede <strong>pasear</strong> y ver cualquier <strong>información pública</strong>, y pulsar <strong>«Entrar»</strong> cuando quiera <strong>conectar</strong> con su gente o trabajar en privado. La cruz la cierra, y el aparato <strong>lo recuerda</strong>.`],
  ['Novedad · La Despensa en baldosas', `La ${enllacIntern(ENLLAC_REBOST_R32_26, 'Despensa')} tiene una <strong>dirección corta</strong> y, en el móvil, se abre <strong>directamente</strong> en la lista. La despensa y la compra se ven en <strong>baldosas cuadradas</strong>, con el <strong>dibujo de cada alimento</strong>, y en la compra hay una diferencia clara entre lo que hay <strong>por comprar</strong> y lo que está <strong>fuera de la lista</strong>.`],
  ['Novedad · Un TPV del Bar para probar', `En el ${enllacIntern(ENLLAC_BAR_TPV_R32_26, 'TPV del Bar')}, quien todavía <strong>no ha entrado</strong> puede abrir un <strong>TPV de prueba</strong>. Funciona <strong>solo en ese aparato</strong>, <strong>no guarda nada</strong> en el <strong>servidor de Sóc de Poble</strong>, y la nota que saca dice que es <strong>de muestra</strong> y que <strong>no es factura</strong>.`],
  ['Mejora · La carta del Bar y la banda de pruebas', `En la carta del ${enllacIntern(ENLLAC_BAR_R32_26, 'Bar')}, cada producto <strong>sin foto</strong> lleva el <strong>dibujo de su familia</strong>, del <strong>café</strong> a los licores. Fuera del Bar y de la Gestoría, la banda que avisa de que una aplicación está <strong>en pruebas</strong> se puede <strong>plegar</strong>, y el aparato <strong>lo recuerda</strong>.`],
  ['Mejora · La Wiki, con portada propia', `La ${enllacIntern(ENLLAC_WIKI_R32_26, 'Wiki de Poble')} tiene una <strong>portada propia</strong>, con una <strong>viñeta</strong> de cómic, y en el <strong>móvil</strong> se abre <strong>directamente</strong> en la portada o en el artículo, sin ningún <strong>cajón</strong> que la tape.`],
  ['Mejora · El Muro, el Mercado y el Calendario, más arriba', `El ${enllacIntern(ENLLAC_MUR_R32_26, 'Muro')}, el ${enllacIntern(ENLLAC_MERCAT_R32_26, 'Mercado')} y el ${enllacIntern(ENLLAC_CALENDARI_R32_26, 'Calendario')} conservan sus <strong>barras</strong>, el <strong>título</strong> y el <strong>botón principal</strong>, pero ya no repiten el <strong>logotipo</strong> ni la <strong>entradilla</strong> larga: las <strong>primeras tarjetas</strong> aparecen más arriba en la pantalla.`],
  ['Corrección · La asistencia a los actos, guardada de verdad', `Cuando dices si <strong>irás</strong> a un acto del ${enllacIntern(ENLLAC_CALENDARI_R32_26, 'Calendario')}, la aplicación solo lo da por <strong>guardado</strong> cuando el aparato <strong>lo ha guardado</strong> de verdad. Si no ha podido, <strong>no lo confirma</strong> y conserva la <strong>respuesta anterior</strong>.`],
  ['Corrección · La sesión, renovada antes de pedir', 'Si vuelves a una <strong>pestaña</strong> que llevaba <strong>más de una hora</strong> abierta, la aplicación <strong>renueva la sesión</strong> antes de pedir los datos al <strong>servidor de Sóc de Poble</strong>. Antes, las primeras peticiones iban con la <strong>sesión caducada</strong>, el servidor las <strong>rechazaba</strong> y la aplicación tenía que volver a hacerlas.']],
 en: ['21 November 2026, afternoon · Waves R32.25 and R32.26 · The Outsider’s welcome, the Pantry in tiles and a Bar POS to try',
  `Waves R32.25 and R32.26 of <strong>Sóc de Poble</strong> bring much of what the <strong>Assaig a la Plaça</strong> asked for. Whoever opens the ${enllacIntern(ENLLAC_XAT_R32_26, 'Chat')} <strong>without signing in</strong>, the <strong>Outsider</strong>, finds a <strong>welcome in two lines</strong> and a single <strong>“Sign in”</strong>. The ${enllacIntern(ENLLAC_REBOST_R32_26, 'Pantry')} is shown in <strong>tiles</strong>, the ${enllacIntern(ENLLAC_BAR_R32_26, 'Bar')} POS can be <strong>tried without signing in</strong>, and the ${enllacIntern(ENLLAC_MUR_R32_26, 'Wall')}, the ${enllacIntern(ENLLAC_MERCAT_R32_26, 'Market')} and the ${enllacIntern(ENLLAC_CALENDARI_R32_26, 'Calendar')} show their cards higher up.`,
  'The applications move to <strong>version 1.2.17 (build 22)</strong> in the <strong>repository</strong> and, at the time of writing, the version is <strong>not listed in any store</strong>. The <strong>WordPress connector</strong> published on WordPress.org is <strong>1.1.24</strong>; 1.1.25 in the repository <strong>has not been published yet</strong>.',
  'At the time of writing, the version <strong>changes nothing</strong> on the <strong>Sóc de Poble server</strong>: the new limits for notifications are in the repository, but <strong>have not been applied</strong>. <strong>Chat notifications</strong> in the mobile apps are still <strong>not switched on</strong>, the <strong>privacy policy</strong> stays at <strong>version 2.5</strong>, and switching notifications on depends on <strong>the Mestre’s decision</strong>.',
  ['New · The Outsider’s welcome', `Whoever opens the ${enllacIntern(ENLLAC_XAT_R32_26, 'Chat')} <strong>without signing in</strong> finds a <strong>welcome</strong> in two lines: they can <strong>stroll around</strong> and view any <strong>public information</strong>, and press <strong>“Sign in”</strong> whenever they want to <strong>connect</strong> with their people or work in private. The cross closes it, and the device <strong>remembers it</strong>.`],
  ['New · The Pantry in tiles', `The ${enllacIntern(ENLLAC_REBOST_R32_26, 'Pantry')} has a <strong>short address</strong> and, on a mobile, opens <strong>straight</strong> on the list. The pantry and the shopping list are shown as <strong>square tiles</strong>, with a <strong>drawing of each food item</strong>, and the shopping list shows a clear difference between what is <strong>to buy</strong> and what is <strong>off the list</strong>.`],
  ['New · A Bar POS to try', `In the ${enllacIntern(ENLLAC_BAR_TPV_R32_26, 'Bar POS')}, anyone who has <strong>not signed in</strong> yet can open a <strong>practice POS</strong>. It works <strong>only on that device</strong>, <strong>saves nothing</strong> on the <strong>Sóc de Poble server</strong>, and the note it shows says it is a <strong>sample</strong> and <strong>not an invoice</strong>.`],
  ['Improvement · The Bar menu and the testing band', `On the ${enllacIntern(ENLLAC_BAR_R32_26, 'Bar')} menu, each item <strong>without a photo</strong> shows the <strong>drawing of its family</strong>, from <strong>coffee</strong> to spirits. Outside the Bar and Bookkeeping, the band that says an app is <strong>in testing</strong> can be <strong>collapsed</strong>, and the device <strong>remembers it</strong>.`],
  ['Improvement · The Wiki, with its own front page', `The ${enllacIntern(ENLLAC_WIKI_R32_26, 'Village Wiki')} has its <strong>own front page</strong>, with a <strong>comic panel</strong>, and on a <strong>mobile</strong> it opens <strong>straight</strong> on the front page or the article, with no <strong>drawer</strong> covering it.`],
  ['Improvement · The Wall, the Market and the Calendar, higher up', `The ${enllacIntern(ENLLAC_MUR_R32_26, 'Wall')}, the ${enllacIntern(ENLLAC_MERCAT_R32_26, 'Market')} and the ${enllacIntern(ENLLAC_CALENDARI_R32_26, 'Calendar')} keep their <strong>bars</strong>, the <strong>title</strong> and the <strong>main button</strong>, but no longer repeat the <strong>logo</strong> or the long <strong>intro</strong>: the <strong>first cards</strong> appear higher up the screen.`],
  ['Fix · Event attendance, really saved', `When you say whether you <strong>will go</strong> to an <strong>event</strong> in the ${enllacIntern(ENLLAC_CALENDARI_R32_26, 'Calendar')}, the app only counts it as <strong>saved</strong> when the device <strong>has really saved it</strong>. If it could not, it <strong>does not confirm it</strong> and keeps your <strong>previous answer</strong>.`],
  ['Fix · The session, renewed before asking', 'If you go back to a <strong>tab</strong> that had been open for <strong>more than an hour</strong>, the app <strong>renews the session</strong> before asking the <strong>Sóc de Poble server</strong> for data. Previously, the first requests went out with the <strong>expired session</strong>, the server <strong>rejected them</strong> and the app had to send them again.']],
 eu: ['2026ko azaroaren 21a, arratsaldea · R32.25 eta R32.26 olatuak · Arrotzaren ongietorria, Jakitegia lauzatan eta Tabernako TPVa probatzeko',
  `<strong>Sóc de Poble</strong>ren R32.25 eta R32.26 olatuek <strong>Assaig a la Plaça</strong>k eskatutakoaren zati handi bat dakarte. ${enllacIntern(ENLLAC_XAT_R32_26, 'Txata')} <strong>sartu gabe</strong> irekitzen duenak, <strong>Arrotzak</strong>, <strong>bi lerroko ongietorria</strong> eta <strong>«Sartu»</strong> bakarra aurkitzen ditu. ${enllacIntern(ENLLAC_REBOST_R32_26, 'Jakitegia')} <strong>lauzatan</strong> ikusten da, ${enllacIntern(ENLLAC_BAR_R32_26, 'Tabernako')} TPVa <strong>sartu gabe probatu</strong> daiteke, eta ${enllacIntern(ENLLAC_MUR_R32_26, 'Hormak')}, ${enllacIntern(ENLLAC_MERCAT_R32_26, 'Merkatuak')} eta ${enllacIntern(ENLLAC_CALENDARI_R32_26, 'Egutegiak')} beren txartelak gorago erakusten dituzte.`,
  'Aplikazioak <strong>1.2.17 bertsiora (22. builda)</strong> igarotzen dira <strong>biltegian</strong>, eta kronika hau idazten den unean bertsio hori <strong>ez dago inongo dendatan</strong> oraindik. WordPress.org-en argitaratutako <strong>WordPress konektorea</strong> <strong>1.1.24</strong> da; biltegiko 1.1.25 <strong>ez da oraindik argitaratu</strong>.',
  'Kronika hau idazten den unean, bertsio honek <strong>ez du ezer aldatzen</strong> <strong>Sóc de Pobleren zerbitzarian</strong>: abisuen muga berriak biltegian daude, baina <strong>ez dira aplikatu</strong>. Mugikorreko aplikazioetako <strong>txateko abisuak</strong> oraindik <strong>ez daude piztuta</strong>, <strong>pribatutasun-politika</strong> <strong>2.5 bertsioan</strong> dago oraindik, eta abisuak piztea <strong>Mestreren erabakiaren</strong> menpe dago.',
  ['Berritasuna · Arrotzaren ongietorria', `${enllacIntern(ENLLAC_XAT_R32_26, 'Txata')} <strong>sartu gabe</strong> irekitzen duenak bi lerroko <strong>ongietorria</strong> aurkitzen du: <strong>ibili</strong> eta edozein <strong>informazio publiko</strong> ikus dezake, eta <strong>«Sartu»</strong> saka dezake bere jendearekin <strong>konektatu</strong> edo pribatuan lan egin nahi duenean. Gurutzeak ixten du, eta gailuak <strong>gogoratzen du</strong>.`],
  ['Berritasuna · Jakitegia lauzatan', `${enllacIntern(ENLLAC_REBOST_R32_26, 'Jakitegiak')} <strong>helbide laburra</strong> du eta, mugikorrean, <strong>zuzenean</strong> irekitzen da zerrendan. Jakitegia eta erosketa <strong>lauza karratuetan</strong> ikusten dira, <strong>elikagai bakoitzaren marrazkiarekin</strong>, eta erosketan argi bereizten da <strong>erosteko</strong> dagoena eta <strong>zerrendatik kanpo</strong> dagoena.`],
  ['Berritasuna · Tabernako TPVa probatzeko', `${enllacIntern(ENLLAC_BAR_TPV_R32_26, 'Tabernako TPVan')}, oraindik <strong>sartu ez denak</strong> <strong>proba-TPV</strong> bat ireki dezake. <strong>Gailu horretan bakarrik</strong> dabil, <strong>ez du ezer gordetzen</strong> <strong>Sóc de Pobleren zerbitzarian</strong>, eta ateratzen duen oharrak <strong>erakusgarria</strong> dela eta <strong>ez dela faktura</strong> dio.`],
  ['Hobekuntza · Tabernako karta eta proben banda', `${enllacIntern(ENLLAC_BAR_R32_26, 'Tabernako')} kartan, <strong>argazkirik gabeko</strong> produktu bakoitzak <strong>bere familiaren marrazkia</strong> du, <strong>kafetik</strong> likoreetara. Tabernatik eta Gestoriatik kanpo, aplikazio bat <strong>probetan</strong> dagoela abisatzen duen banda <strong>tolestu</strong> daiteke, eta gailuak <strong>gogoratzen du</strong>.`],
  ['Hobekuntza · Wikia, bere azalarekin', `${enllacIntern(ENLLAC_WIKI_R32_26, 'Herriko Wikiak')} <strong>bere azala</strong> du, komiki-<strong>binieta</strong> batekin, eta mugikorrean <strong>zuzenean</strong> irekitzen da azalean edo artikuluan, estaltzen duen <strong>tiraderarik</strong> gabe.`],
  ['Hobekuntza · Horma, Merkatua eta Egutegia, gorago', `${enllacIntern(ENLLAC_MUR_R32_26, 'Hormak')}, ${enllacIntern(ENLLAC_MERCAT_R32_26, 'Merkatuak')} eta ${enllacIntern(ENLLAC_CALENDARI_R32_26, 'Egutegiak')} beren <strong>barrak</strong>, <strong>izenburua</strong> eta <strong>botoi nagusia</strong> gordetzen dituzte, baina jada ez dute <strong>logotipoa</strong> errepikatzen, ezta <strong>sarrera</strong> luzea ere: <strong>lehen txartelak</strong> pantailan gorago agertzen dira.`],
  ['Zuzenketa · Ekitaldietarako asistentzia, benetan gordeta', `${enllacIntern(ENLLAC_CALENDARI_R32_26, 'Egutegiko')} ekitaldi batera <strong>joango zaren</strong> ala ez esaten duzunean, aplikazioak <strong>gordetzat</strong> ematen du gailuak <strong>benetan gorde duenean</strong> bakarrik. Ezin izan badu, <strong>ez du berresten</strong> eta <strong>aurreko erantzuna</strong> gordetzen du.`],
  ['Zuzenketa · Saioa, eskatu aurretik berrituta', '<strong>Ordubete baino gehiago</strong> irekita zegoen <strong>fitxa</strong> batera itzultzen bazara, aplikazioak <strong>saioa berritzen du</strong> <strong>Sóc de Pobleren zerbitzariari</strong> datuak eskatu aurretik. Lehen, lehenengo eskaerak <strong>iraungitako saioarekin</strong> joaten ziren, zerbitzariak <strong>baztertu egiten zituen</strong> eta aplikazioak berriro bidali behar zituen.']],
 gl: ['21 de novembro de 2026, tarde · Ondas R32.25 e R32.26 · A benvida do Forasteiro, a Despensa en baldosas e un TPV do Bar para probar',
  `As Ondas R32.25 e R32.26 de <strong>Sóc de Poble</strong> traen boa parte do que pediu o <strong>Assaig a la Plaça</strong>. Quen abre o ${enllacIntern(ENLLAC_XAT_R32_26, 'Chat')} <strong>sen entrar</strong>, o <strong>Forasteiro</strong>, atopa unha <strong>benvida de dúas liñas</strong> e un só <strong>«Entrar»</strong>. A ${enllacIntern(ENLLAC_REBOST_R32_26, 'Despensa')} vese en <strong>baldosas</strong>, o TPV do ${enllacIntern(ENLLAC_BAR_R32_26, 'Bar')} pódese <strong>probar sen entrar</strong>, e o ${enllacIntern(ENLLAC_MUR_R32_26, 'Muro')}, o ${enllacIntern(ENLLAC_MERCAT_R32_26, 'Mercado')} e o ${enllacIntern(ENLLAC_CALENDARI_R32_26, 'Calendario')} amosan as súas tarxetas máis arriba.`,
  'As aplicacións pasan á <strong>versión 1.2.17 (build 22)</strong> no <strong>repositorio</strong> e, cando se escribe esta crónica, a versión aínda <strong>non consta en ningunha tenda</strong>. O <strong>conector de WordPress</strong> publicado en WordPress.org é a <strong>1.1.24</strong>; a 1.1.25 do repositorio <strong>aínda non se publicou</strong>.',
  'Cando se escribe esta crónica, a versión <strong>non cambia nada</strong> no <strong>servidor de Sóc de Poble</strong>: os novos límites dos avisos están no repositorio, pero <strong>non se aplicaron</strong>. Os <strong>avisos do chat</strong> nas aplicacións do móbil aínda <strong>non están acesos</strong>, a <strong>política de privacidade</strong> segue na <strong>versión 2.5</strong>, e acender os avisos depende dunha <strong>decisión do Mestre</strong>.',
  ['Novidade · A benvida do Forasteiro', `Quen abre o ${enllacIntern(ENLLAC_XAT_R32_26, 'Chat')} <strong>sen entrar</strong> atopa unha <strong>benvida</strong> de dúas liñas: pode <strong>pasear</strong> e ver calquera <strong>información pública</strong>, e premer <strong>«Entrar»</strong> cando queira <strong>conectar</strong> coa súa xente ou traballar en privado. A cruz pechaa, e o aparello <strong>lémbrao</strong>.`],
  ['Novidade · A Despensa en baldosas', `A ${enllacIntern(ENLLAC_REBOST_R32_26, 'Despensa')} ten un <strong>enderezo curto</strong> e, no móbil, ábrese <strong>directamente</strong> na lista. A despensa e a compra vense en <strong>baldosas cadradas</strong>, co <strong>debuxo de cada alimento</strong>, e na compra hai unha diferenza clara entre o que hai <strong>por comprar</strong> e o que está <strong>fóra da lista</strong>.`],
  ['Novidade · Un TPV do Bar para probar', `No ${enllacIntern(ENLLAC_BAR_TPV_R32_26, 'TPV do Bar')}, quen aínda <strong>non entrou</strong> pode abrir un <strong>TPV de proba</strong>. Funciona <strong>só nese aparello</strong>, <strong>non garda nada</strong> no <strong>servidor de Sóc de Poble</strong>, e a nota que saca di que é <strong>de mostra</strong> e que <strong>non é factura</strong>.`],
  ['Mellora · A carta do Bar e a banda de probas', `Na carta do ${enllacIntern(ENLLAC_BAR_R32_26, 'Bar')}, cada produto <strong>sen foto</strong> leva o <strong>debuxo da súa familia</strong>, do <strong>café</strong> aos licores. Fóra do Bar e da Xestoría, a banda que avisa de que unha aplicación está <strong>en probas</strong> pódese <strong>pregar</strong>, e o aparello <strong>lémbrao</strong>.`],
  ['Mellora · A Wiki, con portada propia', `A ${enllacIntern(ENLLAC_WIKI_R32_26, 'Wiki de Poble')} ten unha <strong>portada propia</strong>, cunha <strong>viñeta</strong> de cómic, e no <strong>móbil</strong> ábrese <strong>directamente</strong> na portada ou no artigo, sen ningún <strong>caixón</strong> que a tape.`],
  ['Mellora · O Muro, o Mercado e o Calendario, máis arriba', `O ${enllacIntern(ENLLAC_MUR_R32_26, 'Muro')}, o ${enllacIntern(ENLLAC_MERCAT_R32_26, 'Mercado')} e o ${enllacIntern(ENLLAC_CALENDARI_R32_26, 'Calendario')} conservan as súas <strong>barras</strong>, o <strong>título</strong> e o <strong>botón principal</strong>, pero xa non repiten o <strong>logotipo</strong> nin a <strong>entradiña</strong> longa: as <strong>primeiras tarxetas</strong> aparecen máis arriba na pantalla.`],
  ['Corrección · A asistencia aos actos, gardada de verdade', `Cando dis se <strong>irás</strong> a un acto do ${enllacIntern(ENLLAC_CALENDARI_R32_26, 'Calendario')}, a aplicación só o dá por <strong>gardado</strong> cando o aparello <strong>o gardou</strong> de verdade. Se non puido, <strong>non o confirma</strong> e conserva a <strong>resposta anterior</strong>.`],
  ['Corrección · A sesión, renovada antes de pedir', 'Se volves a unha <strong>lapela</strong> que levaba <strong>máis dunha hora</strong> aberta, a aplicación <strong>renova a sesión</strong> antes de pedir os datos ao <strong>servidor de Sóc de Poble</strong>. Antes, as primeiras peticións ían coa <strong>sesión caducada</strong>, o servidor <strong>rexeitábaas</strong> e a aplicación tiña que repetilas.']]
};

const fitaR32_26 = (language) => {
 const [titol, obertura, abast, migracio, ...apartats] = FITA_R32_26[language];
 return `${section('h3', titol, obertura, abast, migracio)}\n      ${apartats.map(([t, c]) => subSection(t, c)).join('\n      ')}\n\n      `;
};

