const ENLLAC_SISTEMA_NERVIOS_R32_4 = '/wikidepoble?item=sistema_nervios_skills_i_repositoris';
export const FITA_R32_4 = {
 ca: ['17 de novembre de 2026, vesprada · Onada R32.4 · L’idioma i l’eixida al calaix d’identitats, les Aplicacions en un sol enllaç del Perfil i comptes exactes al TPV i a la Gestoria',
  `L’<strong>Onada R32.4</strong> de <strong>Sóc de Poble</strong> porta l’<strong>idioma</strong> i l’<strong>eixida</strong> de la sessió al calaix «Amb qui actues?», deixa les <strong>Aplicacions</strong> del ${enllacIntern(ENLLAC_PERFIL, '<strong>Perfil</strong>')} en un <strong>sol enllaç</strong> i fa que el TPV del Bar i la Gestoria facen els <strong>comptes exactes</strong>.`,
  'Les aplicacions passen a la <strong>versió 1.2.6 (build 11)</strong> al repositori. Està <strong>previst</strong> pujar-la al <strong>canal de proves</strong> d’una de les dues botigues i preparar els <strong>paquets signats</strong> per a l’altra, on la pujada automàtica encara espera la <strong>clau del compte de servei</strong>. El <strong>connector de WordPress</strong> publicat a WordPress.org continua en la <strong>1.1.12</strong>.',
  'El <strong>17 de novembre</strong> (1.55) s’han aplicat al <strong>servidor compartit</strong> <strong>cinc migracions</strong>: les <strong>tres de l’Onada R32</strong>, la que blinda les set funcions antigues (<code>20261116170000</code>), la del xat propi (<code>20261116170100</code>) i la de la baixa del compte (<code>20261116170200</code>), i les <strong>dues del Xat</strong> de l’Onada R24, la d’<strong>una sola conversa directa</strong> per parella i poble (<code>20261114060000</code>) i la dels <strong>rebuts d’entrega</strong> (<code>20261114061000</code>), que ja hi era des del 14 de novembre i s’ha tornat a passar.',
  ['Novetat · Una pàgina que explica el sistema nerviós de Sóc de Poble', `La pàgina ${enllacIntern(ENLLAC_SISTEMA_NERVIOS_R32_4, 'El <strong>Sistema Nerviós</strong> de Sóc de Poble')} explica en <strong>cinc llengües</strong>, per a qualsevol <strong>persona sense formació informàtica</strong>, què són les <strong>instruccions d’ofici</strong> (skills), què comproven els <strong>tractors automàtics</strong> i d’on ve cada peça que s’estudia o es guarda al <strong>Node 0</strong>.`],
  ['Millora · L’idioma i l’eixida, al calaix «Amb qui actues?» i al Perfil', `La <strong>barra negra</strong> ja no porta el botó d’<strong>Idioma</strong>, i al mòbil deixa més lloc al logotip. El calaix «Amb qui actues?» té ara dos botons, <strong>«Idioma del sistema»</strong> i <strong>«Eixir de Sóc de Poble»</strong>, que també són <strong>apartats</strong> del ${enllacIntern(ENLLAC_PERFIL, '<strong>Perfil</strong>')}.`],
  ['Millora · Les Aplicacions, en un sol enllaç del Perfil, i una sola icona per apartat', `Al ${enllacIntern(ENLLAC_PERFIL, '<strong>Perfil</strong>')}, les <strong>Aplicacions</strong> ja no ocupen un grup propi a la primera columna: són un <strong>sol enllaç</strong> dins del grup de la persona. A l’<strong>Administració del sistema</strong>, cada apartat porta una sola <strong>icona dibuixada</strong>, sense l’<strong>emoticona</strong> repetida al nom.`],
  ['Millora · Un README d’enginyeria per a equips tècnics de fora', 'El <strong>README</strong> del repositori és ara una guia d’<strong>enginyeria</strong> per a <strong>equips tècnics de fora</strong>: on viu cada peça, l’<strong>arquitectura modular</strong>, el <strong>port de dades</strong>, les <strong>portes automàtiques</strong> i els canals de distribució.'],
  ['Correcció · Comptes exactes al TPV del Bar i a la Gestoria', 'El <strong>TPV del Bar</strong> calcula l’<strong>IVA</strong>, els descomptes i les devolucions amb <strong>nombres enters exactes</strong>, i la <strong>Gestoria</strong> estima els models 303 i 130 sense perdre cap cèntim; quan un import ix del marge segur, ho <strong>avisa</strong> en lloc de donar un resultat insegur. Les dues eines continuen «En proves · Beta oberta»: <strong>no són programes homologats</strong> i <strong>no envien res a VeriFactu</strong>.'],
  ['Correcció · El Perfil avisa mentre carrega un apartat', `Mentre es carrega un <strong>apartat</strong> del ${enllacIntern(ENLLAC_PERFIL, '<strong>Perfil</strong>')}, ara ix l’avís <strong>«Carregant el teu perfil…»</strong>, que també anuncien els <strong>lectors de pantalla</strong>, en lloc d’un <strong>espai buit</strong>.`],
  ['Correcció · Els títols dels apartats del Perfil, al mòbil més estret', `Al mòbil estret, els títols dels apartats del ${enllacIntern(ENLLAC_PERFIL, '<strong>Perfil</strong>')} fan servir una <strong>lletra més estreta</strong>, i a <strong>320 píxels</strong> les <strong>paraules llargues</strong> dels noms del sistema, com «Desplegament», ja <strong>no es partixen</strong> per la meitat.`],
  ['Correcció · Els tractors automàtics ja no aproven el que no han pogut llegir', 'Els <strong>tractors automàtics</strong> que vigilen el <strong>codi</strong> ja no donen per bo el que no han pogut llegir: un fitxer <strong>absent</strong>, <strong>buit</strong> o que no s’entén fa <strong>fallar</strong> la comprovació en lloc d’aprovar-la, i cadascun d’estos errors té la seua <strong>contraprova</strong>.']],
 es: ['17 de noviembre de 2026, tarde · Oleada R32.4 · El idioma y la salida en el cajón de identidades, las Aplicaciones en un solo enlace del Perfil y cuentas exactas en el TPV y la Gestoria',
  `La <strong>Oleada R32.4</strong> de <strong>Sóc de Poble</strong> lleva el <strong>idioma</strong> y la <strong>salida</strong> de la sesión al cajón «Amb qui actues?», deja las <strong>Aplicaciones</strong> del ${enllacIntern(ENLLAC_PERFIL, '<strong>Perfil</strong>')} en un <strong>solo enlace</strong> y hace que el TPV del Bar y la Gestoria hagan las <strong>cuentas exactas</strong>.`,
  'Las aplicaciones pasan a la <strong>versión 1.2.6 (build 11)</strong> en el repositorio. Está <strong>previsto</strong> subirla al <strong>canal de pruebas</strong> de una de las dos tiendas y preparar los <strong>paquetes firmados</strong> para la otra, donde la subida automática todavía espera la <strong>clave de la cuenta de servicio</strong>. El <strong>conector de WordPress</strong> publicado en WordPress.org sigue en la <strong>1.1.12</strong>.',
  'El <strong>17 de noviembre</strong> (1.55) se han aplicado en el <strong>servidor compartido</strong> <strong>cinco migraciones</strong>: las <strong>tres de la Oleada R32</strong>, la que blinda las siete funciones antiguas (<code>20261116170000</code>), la del chat propio (<code>20261116170100</code>) y la de la baja de la cuenta (<code>20261116170200</code>), y las <strong>dos del Chat</strong> de la Oleada R24, la de <strong>una sola conversación directa</strong> por pareja y pueblo (<code>20261114060000</code>) y la de los <strong>acuses de entrega</strong> (<code>20261114061000</code>), que ya estaba desde el 14 de noviembre y se ha vuelto a pasar.',
  ['Novedad · Una página que explica el sistema nervioso de Sóc de Poble', `La página ${enllacIntern(ENLLAC_SISTEMA_NERVIOS_R32_4, 'El <strong>Sistema Nervioso</strong> de Sóc de Poble')} explica en <strong>cinco lenguas</strong>, para cualquier <strong>persona sin formación informática</strong>, qué son las <strong>instrucciones de oficio</strong> (skills), qué comprueban los <strong>tractores automáticos</strong> y de dónde procede cada pieza que se estudia o se guarda en el <strong>Node 0</strong>.`],
  ['Mejora · El idioma y la salida, en el cajón «Amb qui actues?» y en el Perfil', `La <strong>barra negra</strong> ya no lleva el botón de <strong>Idioma</strong>, y en el móvil deja más sitio al logotipo. El cajón «Amb qui actues?» tiene ahora dos botones, <strong>«Idioma del sistema»</strong> y <strong>«Salir de Sóc de Poble»</strong>, que también son <strong>apartados</strong> del ${enllacIntern(ENLLAC_PERFIL, '<strong>Perfil</strong>')}.`],
  ['Mejora · Las Aplicaciones, en un solo enlace del Perfil, y un solo icono por apartado', `En el ${enllacIntern(ENLLAC_PERFIL, '<strong>Perfil</strong>')}, las <strong>Aplicaciones</strong> ya no ocupan un grupo propio en la primera columna: son un <strong>solo enlace</strong> dentro del grupo de la persona. En la <strong>Administración del sistema</strong>, cada apartado lleva un solo <strong>icono dibujado</strong>, sin el <strong>emoticono</strong> repetido en el nombre.`],
  ['Mejora · Un README de ingeniería para equipos técnicos de fuera', 'El <strong>README</strong> del repositorio es ahora una guía de <strong>ingeniería</strong> para <strong>equipos técnicos de fuera</strong>: dónde vive cada pieza, la <strong>arquitectura modular</strong>, el <strong>puerto de datos</strong>, las <strong>comprobaciones automáticas</strong> y los canales de distribución.'],
  ['Corrección · Cuentas exactas en el TPV del Bar y en la Gestoria', 'El <strong>TPV del Bar</strong> calcula el <strong>IVA</strong>, los descuentos y las devoluciones con <strong>números enteros exactos</strong>, y la <strong>Gestoria</strong> estima los modelos 303 y 130 sin perder ningún céntimo; cuando un importe se sale del margen seguro, lo <strong>avisa</strong> en lugar de dar una cifra insegura. Las dos herramientas siguen «En pruebas · Beta abierta»: <strong>no son programas homologados</strong> y <strong>no envían nada a VeriFactu</strong>.'],
  ['Corrección · El Perfil avisa mientras carga un apartado', `Mientras se carga un <strong>apartado</strong> del ${enllacIntern(ENLLAC_PERFIL, '<strong>Perfil</strong>')}, ahora aparece el aviso <strong>«Cargando tu perfil…»</strong>, que también anuncian los <strong>lectores de pantalla</strong>, en lugar de un <strong>espacio vacío</strong>.`],
  ['Corrección · Los títulos de los apartados del Perfil, en el móvil más estrecho', `En el móvil estrecho, los títulos de los apartados del ${enllacIntern(ENLLAC_PERFIL, '<strong>Perfil</strong>')} usan una <strong>letra más estrecha</strong>, y a <strong>320 píxeles</strong> las <strong>palabras largas</strong> de los nombres del sistema ya <strong>no se parten</strong> por la mitad.`],
  ['Corrección · Los tractores automáticos ya no aprueban lo que no han podido leer', 'Los <strong>tractores automáticos</strong> que vigilan el <strong>código</strong> ya no dan por bueno lo que no han podido leer: un archivo <strong>ausente</strong>, <strong>vacío</strong> o que no se entiende hace <strong>fallar</strong> la comprobación en lugar de aprobarla, y cada caso tiene su <strong>contraprueba</strong>.']],
 en: ['17 November 2026, afternoon · Wave R32.4 · Language and sign-out in the identity drawer, Apps as a single Profile link and exact sums in the TPV and the Gestoria',
  `<strong>Wave R32.4</strong> of <strong>Sóc de Poble</strong> moves the <strong>language</strong> and <strong>sign-out</strong> into the “Amb qui actues?” drawer, turns the <strong>Apps</strong> in the ${enllacIntern(ENLLAC_PERFIL, '<strong>Profile</strong>')} into a <strong>single link</strong> and makes the TPV del Bar and the Gestoria do <strong>exact sums</strong>.`,
  'The applications move to <strong>version 1.2.6 (build 11)</strong> in the repository. The <strong>plan</strong> is to upload it to the <strong>testing channel</strong> of one of the two stores and to prepare the <strong>signed packages</strong> for the other, where the automatic upload is still waiting for the <strong>service account key</strong>. The <strong>WordPress plugin</strong> published on WordPress.org stays on <strong>1.1.12</strong>.',
  'On <strong>17 November</strong> (01:55) <strong>five migrations</strong> were applied on the <strong>shared server</strong>: the <strong>three from Wave R32</strong>, the one that tightens the seven older functions (<code>20261116170000</code>), the one for your own chat (<code>20261116170100</code>) and the one for account deletion (<code>20261116170200</code>), and the <strong>two Chat migrations</strong> from Wave R24, the one for <strong>a single direct conversation</strong> per pair and village (<code>20261114060000</code>) and the one for <strong>delivery receipts</strong> (<code>20261114061000</code>), which was already there since 14 November and has been run again.',
  ['New · A page that explains the nervous system of Sóc de Poble', `The page ${enllacIntern(ENLLAC_SISTEMA_NERVIOS_R32_4, 'The <strong>Nervous System</strong> of Sóc de Poble')} explains in <strong>five languages</strong>, for <strong>anyone without a computing background</strong>, what <strong>craft instructions</strong> (skills) are, what the <strong>automated tractors</strong> verify and where each piece studied or stored on <strong>Node 0</strong> comes from.`],
  ['Improvement · Language and sign-out, in the “Amb qui actues?” drawer and in the Profile', `The <strong>black bar</strong> no longer carries the <strong>Language</strong> button, and on mobile it leaves more room for the logo. The “Amb qui actues?” drawer now has two buttons, <strong>“System language”</strong> and <strong>“Sign out of Sóc de Poble”</strong>, which are also <strong>sections</strong> of the ${enllacIntern(ENLLAC_PERFIL, '<strong>Profile</strong>')}.`],
  ['Improvement · Apps as a single Profile link, and one icon per section', `In the ${enllacIntern(ENLLAC_PERFIL, '<strong>Profile</strong>')}, the <strong>Apps</strong> no longer take up a group of their own in the first column: they are a <strong>single link</strong> inside the person’s group. In <strong>System administration</strong>, each section carries a single <strong>drawn icon</strong>, without the <strong>emoji</strong> repeated in its name.`],
  ['Improvement · An engineering README for outside technical teams', 'The repository <strong>README</strong> is now an <strong>engineering</strong> guide for <strong>outside technical teams</strong>: where each piece lives, the <strong>modular architecture</strong>, the <strong>data port</strong>, the <strong>automated checks</strong> and the distribution channels.'],
  ['Fix · Exact sums in the TPV del Bar and the Gestoria', 'The <strong>TPV del Bar</strong> works out <strong>VAT</strong>, discounts and refunds with <strong>exact whole numbers</strong>, and the <strong>Gestoria</strong> estimates forms 303 and 130 without losing a cent; when an amount goes beyond the safe range, it <strong>warns</strong> instead of giving an unsafe figure. Both tools stay “In testing · Open beta”: they are <strong>not certified software</strong> and <strong>send nothing to VeriFactu</strong>.'],
  ['Fix · The Profile tells you while a section is loading', `While a <strong>section</strong> of the ${enllacIntern(ENLLAC_PERFIL, '<strong>Profile</strong>')} is loading, the notice <strong>“Loading your profile…”</strong> now appears, which <strong>screen readers</strong> also announce, instead of an <strong>empty space</strong>.`],
  ['Fix · Profile section titles on the narrowest phones', `On narrow phones, the section titles of the ${enllacIntern(ENLLAC_PERFIL, '<strong>Profile</strong>')} use a <strong>narrower typeface</strong>, and at <strong>320 pixels</strong> the <strong>long words</strong> in the system names are <strong>no longer split</strong> in half.`],
  ['Fix · Automated tractors no longer approve what they could not read', '<strong>Automated tractors</strong> that watch over the code no longer accept what they could not read: a <strong>missing</strong>, <strong>empty</strong> or unreadable file makes the check <strong>fail</strong> instead of passing it, and each case has its own <strong>counter-test</strong>.']],
 eu: ['2026ko azaroaren 17a, arratsaldea · R32.4 olatua · Hizkuntza eta irteera identitateen tiraderan, Aplikazioak Profileko esteka bakarrean eta kontu zehatzak TPV del Bar tresnan eta Gestorian',
  `<strong>Sóc de Poble</strong> plataformako <strong>R32.4 olatuak</strong> <strong>hizkuntza</strong> eta saioko <strong>irteera</strong> «Amb qui actues?» tiraderara eramaten ditu, ${enllacIntern(ENLLAC_PERFIL, '<strong>Profileko</strong>')} <strong>Aplikazioak</strong> esteka bakar batean biltzen ditu, eta TPV del Bar tresnak eta Gestoriak <strong>kontu zehatzak</strong> egitea lortzen du.`,
  'Aplikazioak <strong>1.2.6 bertsiora (11. builda)</strong> igarotzen dira biltegian. Bi dendetako baten <strong>proba-kanalera</strong> igotzea eta bestearentzat <strong>sinatutako paketeak</strong> prestatzea <strong>aurreikusita</strong> dago; beste horretan, igoera automatikoak <strong>zerbitzu-kontuaren gakoa</strong> itxaroten du oraindik. WordPress.org direktorioan argitaratutako <strong>WordPress konektorea</strong> <strong>1.1.12</strong> da oraindik.',
  '<strong>Azaroaren 17an</strong> (01:55ean) <strong>bost migrazio</strong> aplikatu dira <strong>zerbitzari partekatuan</strong>: <strong>R32 olatuko hirurak</strong>, zazpi funtzio zaharrak blindatzen dituena (<code>20261116170000</code>), txat propioarena (<code>20261116170100</code>) eta kontuaren bajarena (<code>20261116170200</code>), eta R24 olatuko <strong>Txateko biak</strong>, bikote eta herri bakoitzeko <strong>elkarrizketa zuzen bakarrarena</strong> (<code>20261114060000</code>) eta <strong>entrega-agiriena</strong> (<code>20261114061000</code>), azaroaren 14tik bazegoena eta berriro exekutatu dena.',
  ['Berritasuna · Sóc de Pobleren nerbio-sistema azaltzen duen orria', `${enllacIntern(ENLLAC_SISTEMA_NERVIOS_R32_4, 'Sóc de Pobleren <strong>Nerbio Sistema</strong>')} orriak <strong>bost hizkuntzatan</strong> azaltzen dio <strong>informatika-prestakuntzarik ez duen edonori</strong> zer diren <strong>lanbide-jarraibideak</strong> (skillak), zer egiaztatzen duten <strong>traktore automatikoek</strong> eta nondik datorren <strong>Node 0n</strong> aztertzen edo gordetzen den pieza bakoitza.`],
  ['Hobekuntza · Hizkuntza eta irteera, «Amb qui actues?» tiraderan eta Profilean', `<strong>Barra beltzak</strong> ez du jada <strong>Hizkuntza</strong> botoirik, eta mugikorrean leku gehiago uzten dio logotipoari. «Amb qui actues?» tiraderak bi botoi ditu orain, <strong>«Sistemaren hizkuntza»</strong> eta <strong>«Irten Sóc de Pobletik»</strong>, eta biak ${enllacIntern(ENLLAC_PERFIL, '<strong>Profileko</strong>')} <strong>atalak</strong> ere badira.`],
  ['Hobekuntza · Aplikazioak Profileko esteka bakarrean, eta ikono bakarra atal bakoitzeko', `${enllacIntern(ENLLAC_PERFIL, '<strong>Profilean</strong>')}, <strong>Aplikazioek</strong> ez dute jada talde propiorik lehen zutabean: <strong>esteka bakarra</strong> dira pertsonaren taldearen barruan. <strong>Sistemaren administrazioan</strong>, atal bakoitzak <strong>marraztutako ikono</strong> bakarra du, izenean errepikatutako <strong>emotikonorik</strong> gabe.`],
  ['Hobekuntza · Kanpoko talde teknikoentzako ingeniaritza-README bat', 'Biltegiko <strong>README fitxategia</strong> ingeniaritza-gida bat da orain <strong>kanpoko talde teknikoentzat</strong>: pieza bakoitza non dagoen, <strong>arkitektura modularra</strong>, datu-ataka, <strong>egiaztapen automatikoak</strong> eta banaketa-kanalak.'],
  ['Zuzenketa · Kontu zehatzak TPV del Bar tresnan eta Gestorian', '<strong>TPV del Bar</strong> tresnak <strong>BEZa</strong>, deskontuak eta itzulketak <strong>zenbaki oso zehatzekin</strong> kalkulatzen ditu, eta <strong>Gestoriak</strong> 303 eta 130 ereduak zentimorik galdu gabe kalkulatzen ditu; zenbateko bat tarte segurutik ateratzen denean, <strong>abisatu</strong> egiten du, seguru ez den zenbateko bat eman beharrean. Bi tresnak «Probetan · Beta irekia» daude oraindik: <strong>ez dira programa homologatuak</strong> eta <strong>ez diote ezer bidaltzen VeriFactu-ri</strong>.'],
  ['Zuzenketa · Profilak abisatzen du atal bat kargatzen ari den bitartean', `${enllacIntern(ENLLAC_PERFIL, '<strong>Profileko</strong>')} atal bat kargatzen ari den bitartean, <strong>«Zure profila kargatzen…»</strong> abisua agertzen da orain, <strong>pantaila-irakurgailuek</strong> ere iragartzen dutena, <strong>leku huts</strong> baten ordez.`],
  ['Zuzenketa · Profileko atalen izenburuak mugikor estuenetan', `Mugikor estuetan, ${enllacIntern(ENLLAC_PERFIL, '<strong>Profileko</strong>')} atalen izenburuek <strong>letra estuagoa</strong> erabiltzen dute, eta <strong>320 pixeletan</strong> sistemaren izenetako <strong>hitz luzeak</strong> ez dira jada erditik zatitzen.`],
  ['Zuzenketa · Traktore automatikoek ez dute jada onartzen irakurri ezin izan dutena', 'Kodea zaintzen duten <strong>traktore automatikoek</strong> ez dute jada ontzat ematen irakurri ezin izan dutena: <strong>falta den</strong>, <strong>hutsik dagoen</strong> edo ulertzen ez den fitxategi batek egiaztapena <strong>huts eginarazten</strong> du onartu beharrean, eta kasu bakoitzak bere <strong>kontraproba</strong> du.']],
 gl: ['17 de novembro de 2026, tarde · Onda R32.4 · O idioma e a saída no caixón de identidades, as Aplicacións nunha soa ligazón do Perfil e contas exactas no TPV e na Gestoria',
  `A <strong>Onda R32.4</strong> de <strong>Sóc de Poble</strong> leva o <strong>idioma</strong> e a <strong>saída</strong> da sesión ao caixón «Amb qui actues?», deixa as <strong>Aplicacións</strong> do ${enllacIntern(ENLLAC_PERFIL, '<strong>Perfil</strong>')} nunha <strong>soa ligazón</strong> e fai que o TPV del Bar e a Gestoria fagan as <strong>contas exactas</strong>.`,
  'As aplicacións pasan á <strong>versión 1.2.6 (build 11)</strong> no repositorio. Está <strong>previsto</strong> subila á <strong>canle de probas</strong> dunha das dúas tendas e preparar os <strong>paquetes asinados</strong> para a outra, onde a subida automática aínda espera a <strong>chave da conta de servizo</strong>. O <strong>conector de WordPress</strong> publicado en WordPress.org segue na <strong>1.1.12</strong>.',
  'O <strong>17 de novembro</strong> (1.55) aplicáronse no <strong>servidor compartido</strong> <strong>cinco migracións</strong>: as <strong>tres da Onda R32</strong>, a que blinda as sete funcións antigas (<code>20261116170000</code>), a do chat propio (<code>20261116170100</code>) e a da baixa da conta (<code>20261116170200</code>), e as <strong>dúas do Chat</strong> da Onda R24, a dunha <strong>soa conversa directa</strong> por parella e pobo (<code>20261114060000</code>) e a dos <strong>recibos de entrega</strong> (<code>20261114061000</code>), que xa estaba desde o 14 de novembro e pasouse de novo.',
  ['Novidade · Unha páxina que explica o sistema nervioso de Sóc de Poble', `A páxina ${enllacIntern(ENLLAC_SISTEMA_NERVIOS_R32_4, 'O <strong>Sistema Nervioso</strong> de Sóc de Poble')} explica en <strong>cinco linguas</strong>, para calquera <strong>persoa sen formación informática</strong>, que son as <strong>instrucións de oficio</strong> (skills), que comproban os <strong>tractores automáticos</strong> e de onde vén cada peza que se estuda ou se garda no <strong>Node 0</strong>.`],
  ['Mellora · O idioma e a saída, no caixón «Amb qui actues?» e no Perfil', `A <strong>barra negra</strong> xa non leva o botón de <strong>Idioma</strong>, e no móbil deixa máis sitio ao logotipo. O caixón «Amb qui actues?» ten agora dous botóns, <strong>«Idioma do sistema»</strong> e <strong>«Saír de Sóc de Poble»</strong>, que tamén son <strong>apartados</strong> do ${enllacIntern(ENLLAC_PERFIL, '<strong>Perfil</strong>')}.`],
  ['Mellora · As Aplicacións, nunha soa ligazón do Perfil, e unha soa icona por apartado', `No ${enllacIntern(ENLLAC_PERFIL, '<strong>Perfil</strong>')}, as <strong>Aplicacións</strong> xa non ocupan un grupo propio na primeira columna: son unha <strong>soa ligazón</strong> dentro do grupo da persoa. Na <strong>Administración do sistema</strong>, cada apartado leva unha soa <strong>icona debuxada</strong>, sen o <strong>emoticono</strong> repetido no nome.`],
  ['Mellora · Un README de enxeñaría para equipos técnicos de fóra', 'O <strong>README</strong> do repositorio é agora unha guía de <strong>enxeñaría</strong> para <strong>equipos técnicos de fóra</strong>: onde vive cada peza, a <strong>arquitectura modular</strong>, o <strong>porto de datos</strong>, as <strong>comprobacións automáticas</strong> e as canles de distribución.'],
  ['Corrección · Contas exactas no TPV del Bar e na Gestoria', 'O <strong>TPV del Bar</strong> calcula o <strong>IVE</strong>, os descontos e as devolucións con <strong>números enteiros exactos</strong>, e a <strong>Gestoria</strong> estima os modelos 303 e 130 sen perder ningún céntimo; cando un importe sae da marxe segura, <strong>avisa</strong> en lugar de dar unha cifra insegura. As dúas ferramentas seguen «En probas · Beta aberta»: <strong>non son programas homologados</strong> e <strong>non envían nada a VeriFactu</strong>.'],
  ['Corrección · O Perfil avisa mentres carga un apartado', `Mentres se carga un <strong>apartado</strong> do ${enllacIntern(ENLLAC_PERFIL, '<strong>Perfil</strong>')}, agora aparece o aviso <strong>«Cargando o teu perfil…»</strong>, que tamén anuncian os <strong>lectores de pantalla</strong>, en lugar dun <strong>espazo baleiro</strong>.`],
  ['Corrección · Os títulos dos apartados do Perfil, no móbil máis estreito', `No móbil estreito, os títulos dos apartados do ${enllacIntern(ENLLAC_PERFIL, '<strong>Perfil</strong>')} usan unha <strong>letra máis estreita</strong>, e a <strong>320 píxeles</strong> as <strong>palabras longas</strong> dos nomes do sistema xa <strong>non se parten</strong> pola metade.`],
  ['Corrección · Os tractores automáticos xa non aproban o que non puideron ler', 'Os <strong>tractores automáticos</strong> que vixían o <strong>código</strong> xa non dan por bo o que non puideron ler: un ficheiro <strong>ausente</strong>, <strong>baleiro</strong> ou que non se entende fai <strong>fallar</strong> a comprobación en lugar de aprobala, e cada caso ten a súa <strong>contraproba</strong>.']]
};

const fitaR32_4 = (language) => {
 const [titol, obertura, abast, migracions, ...apartats] = FITA_R32_4[language];
 return `${section('h3', titol, obertura, abast, migracions)}\n      ${apartats.map(([t, c]) => subSection(t, c)).join('\n      ')}\n\n      `;
};

/* Onada R32.3 (17-11-2026, matinada; ordre T5 R32.3 del Mestre de 16-11-2026 22:09) · La crònica de la versió 1.2.5
   (build 10) del repositori, amb el que ha aterrat de veres al worktree d'integració: l'avís automàtic de versió nova
   de les aplicacions (src/natiu/actualitzacioAppNativa.js, cablejat a natiu/entrada.jsx i pintat per la
   BarraActualitzacioRecomanada de sempre; consulta /.well-known/ard.json en arrencar i en tornar a primer pla, i sense
   xarxa no fa res); el Perfil en dues columnes al mòbil (duesColumnesEstret: graella.js, AppGridShell.jsx/.css,
   UniversalWorkspace.jsx, modules.css i PerfilShell.jsx; MarIA i Gemini); i la solidesa de R32.2: l'eixida de la sessió
   que marca i torna a provar l'oblit de les carpetes locals i dels títols de la IAIA i que no revoca la sessió d'una
   altra persona que entra mentrestant (SessionContext.jsx, capturaSessio), els apartats d'administració del Perfil que
   no arriben per la xarxa amb «Tornar a provar» (PanellDiferitDelPerfil), l'àlies ?data= del Calendari
   (useEstatCalendari.js), el giny «Salut de l'aparell i espai local» del Panell de Control (GinySalutDispositiuJarvis),
   els cèntims del comparador del Rebost d'El Comú (rebost.js), el nom accessible del selector de fitxers de l'editor
   (UniversalEditorShell.jsx) i l'alta i la baixa dels avisos del Xat sense carreres (avisosPushNatius.js).
   Llei 0 (què NO diu i per què): cap nom d'una altra plataforma mòbil ni de la seua botiga, ni APK ni AAB (regla
   2.3.10: perAppNativa.js llevaria el paràgraf dins de l'app, i perAppNativa.test.js fixa que de /versions només se'n
   va l'apartat de la v1.1.0); per això la botiga que espera la clau del compte de servei (SDP_PLAY_JSON_KEY_PATH, que
   no és configurada a .env.botigues.local el 17-11-2026) és «una de les dues», i el client REST de pujada
   (scripts/botigues/puja-android.mjs) no es nomena. Tampoc no diu TestFlight ni que el build 10 siga a cap canal de
   proves: quan s'escriu, els únics registres de pujada són els del build 9 (16-11-2026, 21.35), i la crònica diu
   «encara no publicada a les botigues». No diu que l'avís ja arribe a cap telèfon: les aplicacions instal·lades (fins
   al build 9) no porten el detector i s'han d'actualitzar una vegada a mà, ard.json porta androidBuild i iosBuild al sòl
   verificable 1 fins que el Mestre confirme els builds que donen les botigues, i el detector no s'ha provat en un
   telèfon real. No promet espai alliberat: el servei de salut no té cap productor del manifest regenerable connectat i
   no esborra res (salutEmmagatzematgeDispositiu.js). Corrector R32.3: l'espai és l'estimació de l'origen
   (navigator.storage.estimate) i, com avisa el mateix giny (notaHonestaNavegador), pot incloure dades de l'amfitrió;
   per això la crònica diu «estimació de l'espai que ocupa este lloc web», no «l'espai de Sóc de Poble». Les tres
   migracions R32 (20261116170000, 20261116170100 i 20261116170200) es van escriure com a NO aplicades; Llei 0 de
   l'Onada R32.4: el Mestre les va aplicar al servidor compartit el 17-11-2026 a les 01:55 CET, i la crònica ho diu
   en les cinc llengües, com la correcció de la R30 (c11c35806) (certificat
   CERTIFICAT_5_DE_5_APLICADES_PRODUCCIO_261117_0155.md; supabase/README.md, files 117 a 119). La primera conserva les set funcions i les blinda (relacions qualificades i
   camí de cerca buit, amb còpia íntegra): «blinda», no «tanca». La segona és la del xat propi (la conversa de cada
   persona amb si mateixa), amb el nom de la crònica R21. El connector publicat
   continua en la 1.1.12. Els avisos del Xat no s'han provat en aparells reals i les claus Push no estan verificades:
   cap paraula de Push. La crònica no parla del xifratge d'extrem a extrem, que continua apagat. Cap promesa de
   Lighthouse, AAA ni zero avisos. Corrector R32.3 (TRV-02): als noms de la columna PERFIL, la regla de dues columnes
   de modules.css (.sdp-workspace-groups .sdp-workspace-nav-item__label) els deixa en -webkit-line-clamp: 3 sobre
   l'overflow amagat i els punts suspensius de la regla base, i la banda d'identitat (.sdp-workspace-context-actiu__nom)
   en 2: un nom que no hi cap es continua tallant. Per això la crònica diu que els noms ocupen «fins a tres línies abans
   de tallar-se», i no que «ja no es tallen». Tampoc no diu res dels títols dels apartats: a 320 px algun encara es
   trenca. */
const ENLLAC_XAT_R32_3 = '/xat';
const ENLLAC_CALENDARI_R32_3 = '/calendari';
export const FITA_R32_3 = {
 ca: ['17 de novembre de 2026, matinada · Onada R32.3 · Les aplicacions avisen soles d’una versió nova, el Perfil en dues columnes al mòbil i una eixida de la sessió més sòlida',
  `L’<strong>Onada R32.3</strong> de <strong>Sóc de Poble</strong> fa que les <strong>aplicacions mòbils</strong> avisen soles quan hi ha una <strong>versió nova</strong>, posa el ${enllacIntern(ENLLAC_PERFIL, '<strong>Perfil</strong>')} en <strong>dues columnes</strong> que es poden tocar al mòbil i fa més sòlida l’<strong>eixida de la sessió</strong>.`,
  'Les aplicacions passen a la <strong>versió 1.2.5 (build 10)</strong> al repositori, encara <strong>no publicada a les botigues</strong>, i la pujada automàtica a una de les dues encara espera la <strong>clau del compte de servei</strong>. El <strong>connector de WordPress</strong> publicat a WordPress.org continua en la <strong>1.1.12</strong>. Les <strong>tres migracions</strong> de l’Onada R32 <strong>ja s’han aplicat</strong> al servidor compartit (17 de novembre, 1.55): la que blinda les set funcions antigues (<code>20261116170000</code>), la del xat propi (<code>20261116170100</code>) i la de la baixa del compte (<code>20261116170200</code>).',
  ['Novetat · Les aplicacions avisen soles quan hi ha una versió nova', 'En obrir l’aplicació i en tornar-hi, ara consulta el <strong>manifest públic</strong> de versions i, si diu que la botiga ja oferix un <strong>build més nou</strong> que el de l’aplicació, mostra la <strong>barra d’actualització</strong> amb un botó que obri la botiga; sense xarxa, <strong>no fa res</strong>. És la <strong>primera versió</strong> que ho porta: les aplicacions ja instal·lades s’han d’actualitzar <strong>una vegada a mà</strong>, i l’avís encara <strong>no s’ha provat</strong> en un telèfon real.'],
  ['Millora · El Perfil, en dues columnes que es poden tocar al mòbil', `Al mòbil, el ${enllacIntern(ENLLAC_PERFIL, '<strong>Perfil</strong>')} mostra alhora la columna <strong>«PERFIL»</strong>, amb tu i les teues organitzacions, i la d’<strong>«APARTATS»</strong>; abans, un <strong>vel fosc</strong> tapava la segona i no s’hi podia tocar. Els noms ocupen <strong>fins a tres línies</strong> abans de tallar-se, un sol parell de botons <strong>plega i torna a obrir</strong> les dues columnes, i una <strong>banda</strong> dalt dels apartats diu de qui són.`],
  ['Millora · L’espai local en este navegador, al Panell de Control', `Al ${enllacIntern(ENLLAC_PANELL, '<strong>Panell de Control</strong>')}, l’apartat «Salut de l’aparell i espai local» mostra una <strong>estimació de l’espai</strong> que ocupa este lloc web en este navegador. La <strong>neteja</strong> de la memòria temporal queda <strong>bloquejada</strong>: hui <strong>no esborra res</strong>.`],
  ['Correcció · En eixir de la sessió, el que no s’ha pogut oblidar es torna a provar', 'Si en <strong>eixir de la sessió</strong> no s’han pogut oblidar d’este dispositiu les <strong>carpetes locals</strong> o els títols de les converses amb la <strong>IAIA</strong>, queden marcats i es <strong>torna a provar</strong> abans de tornar-los a llegir. I si una <strong>altra persona</strong> entra mentre la primera ix, la seua <strong>sessió nova</strong> no es tanca.'],
  ['Correcció · Apartats d’administració, Calendari, Rebost i editor', `Els <strong>apartats d’administració</strong> del Perfil que no arriben per la xarxa mostren <strong>«Tornar a provar»</strong> en lloc de trencar la pàgina. El ${enllacIntern(ENLLAC_CALENDARI_R32_3, '<strong>Calendari</strong>')} accepta l’enllaç amb <code>?data=</code> a més de <code>?date=</code>, el <strong>comparador de preus</strong> de les llistes de Rebost d’El Comú arrodonix bé els <strong>cèntims</strong> i el selector de fitxers de l’editor té <strong>nom accessible</strong>.`],
  ['Correcció · L’alta i la baixa dels avisos del Xat en un telèfon, sense trepitjar-se', `L’<strong>alta</strong> i la <strong>baixa</strong> dels avisos del ${enllacIntern(ENLLAC_XAT_R32_3, '<strong>Xat</strong>')} en un <strong>telèfon</strong> ja no es <strong>trepitgen</strong>: una baixa no deixa viu cap registre que arribe tard, i una d’abans no desfà una <strong>alta nova</strong>. Els avisos encara <strong>no s’han provat</strong> en aparells reals.`]],
 es: ['17 de noviembre de 2026, madrugada · Oleada R32.3 · Las aplicaciones avisan solas de una versión nueva, el Perfil en dos columnas en el móvil y una salida de la sesión más sólida',
  `La <strong>Oleada R32.3</strong> de <strong>Sóc de Poble</strong> hace que las <strong>aplicaciones móviles</strong> avisen solas cuando hay una <strong>versión nueva</strong>, pone el ${enllacIntern(ENLLAC_PERFIL, '<strong>Perfil</strong>')} en <strong>dos columnas</strong> que se pueden tocar en el móvil y hace más sólida la <strong>salida de la sesión</strong>.`,
  'Las aplicaciones pasan a la <strong>versión 1.2.5 (build 10)</strong> en el repositorio, todavía <strong>no publicada en las tiendas</strong>, y la subida automática a una de las dos todavía espera la <strong>clave de la cuenta de servicio</strong>. El <strong>conector de WordPress</strong> publicado en WordPress.org sigue en la <strong>1.1.12</strong>. Las <strong>tres migraciones</strong> de la Oleada R32 <strong>ya se han aplicado</strong> en el servidor compartido (17 de noviembre, 1.55): la que blinda las siete funciones antiguas (<code>20261116170000</code>), la del chat propio (<code>20261116170100</code>) y la de la baja de la cuenta (<code>20261116170200</code>).',
  ['Novedad · Las aplicaciones avisan solas cuando hay una versión nueva', 'Al abrir la aplicación y al volver a ella, ahora consulta el <strong>manifiesto público</strong> de versiones y, si dice que la tienda ya ofrece un <strong>build más nuevo</strong> que el de la aplicación, muestra la <strong>barra de actualización</strong> con un botón que abre la tienda; sin red, <strong>no hace nada</strong>. Es la <strong>primera versión</strong> que lo lleva: las aplicaciones ya instaladas se tienen que actualizar <strong>una vez a mano</strong>, y el aviso todavía <strong>no se ha probado</strong> en un teléfono real.'],
  ['Mejora · El Perfil, en dos columnas que se pueden tocar en el móvil', `En el móvil, el ${enllacIntern(ENLLAC_PERFIL, '<strong>Perfil</strong>')} muestra a la vez la columna <strong>«PERFIL»</strong>, contigo y tus organizaciones, y la de <strong>«APARTADOS»</strong>; antes, un <strong>velo oscuro</strong> tapaba la segunda y no se podía tocar. Los nombres ocupan <strong>hasta tres líneas</strong> antes de cortarse, un solo par de botones <strong>pliega y vuelve a abrir</strong> las dos columnas, y una <strong>banda</strong> encima de los apartados dice de quién son.`],
  ['Mejora · El espacio local en este navegador, en el Panel de Control', `En el ${enllacIntern(ENLLAC_PANELL, '<strong>Panel de Control</strong>')}, el apartado «Salud del dispositivo y espacio local» muestra una <strong>estimación del espacio</strong> que ocupa este sitio web en este navegador. La <strong>limpieza</strong> de la memoria temporal queda <strong>bloqueada</strong>: hoy <strong>no borra nada</strong>.`],
  ['Corrección · Al salir de la sesión, lo que no se ha podido olvidar se vuelve a intentar', 'Si al <strong>salir de la sesión</strong> no se han podido olvidar de este dispositivo las <strong>carpetas locales</strong> o los títulos de las conversaciones con la <strong>IAIA</strong>, quedan marcados y se <strong>vuelve a intentar</strong> antes de volver a leerlos. Y si <strong>otra persona</strong> entra mientras la primera sale, su <strong>sesión nueva</strong> no se cierra.'],
  ['Corrección · Apartados de administración, Calendario, Rebost y editor', `Los <strong>apartados de administración</strong> del Perfil que no llegan por la red muestran <strong>«Volver a probar»</strong> en lugar de romper la página. El ${enllacIntern(ENLLAC_CALENDARI_R32_3, '<strong>Calendario</strong>')} acepta el enlace con <code>?data=</code> además de <code>?date=</code>, el <strong>comparador de precios</strong> de las listas de Rebost de El Comú redondea bien los <strong>céntimos</strong> y el selector de archivos del editor tiene <strong>nombre accesible</strong>.`],
  ['Corrección · El alta y la baja de los avisos del Chat en un teléfono, sin pisarse', `El <strong>alta</strong> y la <strong>baja</strong> de los avisos del ${enllacIntern(ENLLAC_XAT_R32_3, '<strong>Chat</strong>')} en un <strong>teléfono</strong> ya no se <strong>pisan</strong>: una baja no deja vivo ningún registro que llegue tarde, y una anterior no deshace un <strong>alta nueva</strong>. Los avisos todavía <strong>no se han probado</strong> en aparatos reales.`]],
 en: ['17 November 2026, early morning · Wave R32.3 · The apps announce a new version on their own, the Profile in two columns on mobile and a sturdier sign-out',
  `<strong>Wave R32.3</strong> of <strong>Sóc de Poble</strong> makes the <strong>mobile apps</strong> announce a <strong>new version</strong> on their own, puts the ${enllacIntern(ENLLAC_PERFIL, '<strong>Profile</strong>')} in <strong>two columns</strong> you can tap on mobile and makes <strong>signing out</strong> sturdier.`,
  'The applications move to <strong>version 1.2.5 (build 10)</strong> in the repository, <strong>not yet published in the stores</strong>, and the automatic upload to one of the two is still waiting for the <strong>service account key</strong>. The <strong>WordPress plugin</strong> published on WordPress.org stays on <strong>1.1.12</strong>. The <strong>three migrations</strong> of Wave R32 <strong>have already been applied</strong> on the shared server (17 November, 01:55): the one that tightens the seven older functions (<code>20261116170000</code>), the one for your own chat (<code>20261116170100</code>) and the one for account deletion (<code>20261116170200</code>).',
  ['New · The apps announce a new version on their own', 'When you open the app and when you come back to it, it now checks the <strong>public manifest</strong> of versions and, if it says the store already offers a <strong>newer build</strong> than the app’s, shows the <strong>update bar</strong> with a button that opens the store; with no network, it <strong>does nothing</strong>. This is the <strong>first version</strong> that carries it: apps already installed must be updated <strong>once by hand</strong>, and the notice has <strong>not yet been tested</strong> on a real phone.'],
  ['Improvement · The Profile, in two columns you can tap on mobile', `On mobile, the ${enllacIntern(ENLLAC_PERFIL, '<strong>Profile</strong>')} shows the <strong>“PROFILE”</strong> column, with you and your organisations, side by side with the <strong>“SECTIONS”</strong> column; before, a <strong>dark veil</strong> covered the second one and it could not be tapped. Names take <strong>up to three lines</strong> before they are cut off, a single pair of buttons <strong>folds and reopens</strong> both columns, and a <strong>band</strong> above the sections says whose they are.`],
  ['Improvement · Local storage in this browser, in the Control Panel', `In the ${enllacIntern(ENLLAC_PANELL, '<strong>Control Panel</strong>')}, the “Device health and local storage” section shows an <strong>estimate of the storage</strong> this website uses in this browser. Clearing the <strong>temporary memory</strong> stays <strong>blocked</strong>: today it <strong>deletes nothing</strong>.`],
  ['Fix · When you sign out, what could not be forgotten is tried again', 'If, when you <strong>sign out</strong>, the <strong>local folders</strong> or the titles of your conversations with the <strong>IAIA</strong> cannot be forgotten from this device, they stay marked and it is <strong>tried again</strong> before they are read again. And if <strong>someone else</strong> signs in while the first person is signing out, their <strong>new session</strong> is not closed.'],
  ['Fix · Admin sections, Calendar, Rebost and editor', `Profile <strong>admin sections</strong> that do not arrive over the network show <strong>“Try again”</strong> instead of breaking the page. The ${enllacIntern(ENLLAC_CALENDARI_R32_3, '<strong>Calendar</strong>')} accepts links with <code>?data=</code> as well as <code>?date=</code>, the <strong>price comparison</strong> in El Comú’s Rebost lists rounds <strong>cents</strong> correctly and the editor’s file picker has an <strong>accessible name</strong>.`],
  ['Fix · Turning Chat notifications on and off on a phone, without clashing', `Turning ${enllacIntern(ENLLAC_XAT_R32_3, '<strong>Chat</strong>')} <strong>notifications</strong> on and off on a <strong>phone</strong> <strong>no longer clashes</strong>: turning them off leaves <strong>no late registration</strong> alive, and an older request does not undo a <strong>new one</strong>. Notifications have <strong>not yet been tested</strong> on real devices.`]],
 eu: ['2026ko azaroaren 17a, goizaldea · R32.3 olatua · Aplikazioek bertsio berri baten berri ematen dute beren kabuz, Profila bi zutabetan mugikorrean eta saio-irteera sendoagoa',
  `<strong>Sóc de Poble</strong> plataformako <strong>R32.3 olatuak</strong> lortzen du <strong>aplikazio mugikorrek</strong> <strong>bertsio berri</strong> baten berri beren kabuz ematea, ${enllacIntern(ENLLAC_PERFIL, '<strong>Profila</strong>')} mugikorrean uki daitezkeen <strong>bi zutabetan</strong> jartzen du eta <strong>saio-irteera</strong> sendoagoa egiten du.`,
  'Aplikazioak <strong>1.2.5 bertsiora (10. builda)</strong> igarotzen dira biltegian, oraindik <strong>dendetan argitaratu gabe</strong>, eta bietako baterako igoera automatikoak <strong>zerbitzu-kontuaren gakoa</strong> itxaroten du oraindik. WordPress.org direktorioan argitaratutako <strong>WordPress konektorea</strong> <strong>1.1.12</strong> da oraindik. R32 olatuko <strong>hiru migrazioak</strong> <strong>jada aplikatu dira</strong> zerbitzari partekatuan (azaroaren 17an, 01:55ean): zazpi funtzio zaharrak blindatzen dituena (<code>20261116170000</code>), txat propioarena (<code>20261116170100</code>) eta kontuaren bajarena (<code>20261116170200</code>).',
  ['Berritasuna · Aplikazioek bertsio berri baten berri ematen dute beren kabuz', 'Aplikazioa irekitzean eta hara itzultzean, bertsioen <strong>manifestu publikoa</strong> kontsultatzen du orain eta, dendak aplikazioarena baino <strong>build berriagoa</strong> eskaintzen duela badio, <strong>eguneratze-barra</strong> erakusten du denda irekitzen duen botoi batekin; sarerik gabe, <strong>ez du ezer egiten</strong>. Hori daraman <strong>lehen bertsioa</strong> da: instalatuta dauden aplikazioak <strong>behin eskuz</strong> eguneratu behar dira, eta abisua <strong>ez da oraindik probatu</strong> benetako telefono batean.'],
  ['Hobekuntza · Profila, mugikorrean uki daitezkeen bi zutabetan', `Mugikorrean, ${enllacIntern(ENLLAC_PERFIL, '<strong>Profilak</strong>')} aldi berean erakusten ditu <strong>«PROFILA»</strong> zutabea, zu eta zure erakundeekin, eta <strong>«ATALAK»</strong> zutabea; lehen, <strong>estalki ilun</strong> batek bigarrena estaltzen zuen eta ezin zen ukitu. Izenek <strong>gehienez hiru lerro</strong> hartzen dituzte moztu aurretik, botoi pare bakar batek bi zutabeak <strong>tolestu eta berriro irekitzen</strong> ditu, eta atalen gaineko <strong>banda</strong> batek norenak diren esaten du.`],
  ['Hobekuntza · Tokiko biltegia nabigatzaile honetan, Kontrol panelean', `${enllacIntern(ENLLAC_PANELL, '<strong>Kontrol panelean</strong>')}, «Gailuaren osasuna eta tokiko biltegia» atalak webgune honek nabigatzaile honetan hartzen duen <strong>lekuaren estimazioa</strong> erakusten du. Aldi baterako <strong>memoriaren garbiketa</strong> <strong>blokeatuta</strong> dago: gaur <strong>ez du ezer ezabatzen</strong>.`],
  ['Zuzenketa · Saiotik irtetean huts egin duen ahazteko saiakera errepikatu egiten da', '<strong>Saiotik irtetean</strong> gailu honetatik ezin badira ahaztu <strong>tokiko karpetak</strong> edo <strong>IAIArekin</strong> izandako elkarrizketen izenburuak, markatuta geratzen dira, eta berriz irakurri aurretik <strong>ahazteko saiakera errepikatzen da</strong>. Eta lehenengoa irteten ari den bitartean <strong>beste pertsona bat</strong> sartzen bada, haren <strong>saio berria</strong> ez da ixten.'],
  ['Zuzenketa · Administrazio-atalak, Egutegia, Rebost eta editorea', `Sarearen bidez iristen ez diren Profileko <strong>administrazio-atalek</strong> <strong>«Saiatu berriro»</strong> erakusten dute orria hautsi beharrean. ${enllacIntern(ENLLAC_CALENDARI_R32_3, '<strong>Egutegiak</strong>')} <code>?data=</code> duen esteka onartzen du, <code>?date=</code> duenaz gain, El Comú-ren Rebost zerrendetako <strong>prezio-konparatzaileak</strong> <strong>zentimoak</strong> ondo biribiltzen ditu eta editoreko fitxategi-hautatzaileak <strong>izen irisgarria</strong> du.`],
  ['Zuzenketa · Txateko abisuen alta eta baja telefono batean, talkarik gabe', `${enllacIntern(ENLLAC_XAT_R32_3, '<strong>Txateko</strong>')} abisuen <strong>alta</strong> eta <strong>baja</strong> <strong>telefono</strong> batean ez dute jada elkarren artean <strong>talka egiten</strong>: baja batek ez du berandu iristen den erregistrorik bizirik uzten, eta lehenagoko batek ez du <strong>alta berri</strong> bat desegiten. Abisuak <strong>ez dira oraindik probatu</strong> benetako gailuetan.`]],
 gl: ['17 de novembro de 2026, madrugada · Onda R32.3 · As aplicacións avisan soas dunha versión nova, o Perfil en dúas columnas no móbil e unha saída da sesión máis sólida',
  `A <strong>Onda R32.3</strong> de <strong>Sóc de Poble</strong> fai que as <strong>aplicacións móbiles</strong> avisen soas cando hai unha <strong>versión nova</strong>, pon o ${enllacIntern(ENLLAC_PERFIL, '<strong>Perfil</strong>')} en <strong>dúas columnas</strong> que se poden tocar no móbil e fai máis sólida a <strong>saída da sesión</strong>.`,
  'As aplicacións pasan á <strong>versión 1.2.5 (build 10)</strong> no repositorio, aínda <strong>non publicada nas tendas</strong>, e a subida automática a unha das dúas aínda espera a <strong>chave da conta de servizo</strong>. O <strong>conector de WordPress</strong> publicado en WordPress.org segue na <strong>1.1.12</strong>. As <strong>tres migracións</strong> da Onda R32 <strong>xa se aplicaron</strong> no servidor compartido (17 de novembro, 1.55): a que blinda as sete funcións antigas (<code>20261116170000</code>), a do chat propio (<code>20261116170100</code>) e a da baixa da conta (<code>20261116170200</code>).',
  ['Novidade · As aplicacións avisan soas cando hai unha versión nova', 'Ao abrir a aplicación e ao volver a ela, agora consulta o <strong>manifesto público</strong> de versións e, se di que a tenda xa ofrece un <strong>build máis novo</strong> ca o da aplicación, amosa a <strong>barra de actualización</strong> cun botón que abre a tenda; sen rede, <strong>non fai nada</strong>. É a <strong>primeira versión</strong> que o leva: as aplicacións xa instaladas teñen que actualizarse <strong>unha vez a man</strong>, e o aviso aínda <strong>non se probou</strong> nun teléfono real.'],
  ['Mellora · O Perfil, en dúas columnas que se poden tocar no móbil', `No móbil, o ${enllacIntern(ENLLAC_PERFIL, '<strong>Perfil</strong>')} amosa á vez a columna <strong>«PERFIL»</strong>, contigo e coas túas organizacións, e a de <strong>«APARTADOS»</strong>; antes, un <strong>veo escuro</strong> tapaba a segunda e non se podía tocar. Os nomes ocupan <strong>ata tres liñas</strong> antes de cortarse, un só par de botóns <strong>prega e volve abrir</strong> as dúas columnas, e unha <strong>banda</strong> enriba dos apartados di de quen son.`],
  ['Mellora · O espazo local neste navegador, no Panel de Control', `No ${enllacIntern(ENLLAC_PANELL, '<strong>Panel de Control</strong>')}, o apartado «Saúde do dispositivo e espazo local» amosa unha <strong>estimación do espazo</strong> que ocupa este sitio web neste navegador. A <strong>limpeza</strong> da memoria temporal queda <strong>bloqueada</strong>: hoxe <strong>non borra nada</strong>.`],
  ['Corrección · Ao saír da sesión, o que non se puido esquecer vólvese tentar', 'Se ao <strong>saír da sesión</strong> non se puideron esquecer deste dispositivo os <strong>cartafoles locais</strong> ou os títulos das conversas coa <strong>IAIA</strong>, quedan marcados e <strong>vólvese tentar</strong> antes de lelos de novo. E se <strong>outra persoa</strong> entra mentres a primeira sae, a súa <strong>sesión nova</strong> non se pecha.'],
  ['Corrección · Apartados de administración, Calendario, Rebost e editor', `Os <strong>apartados de administración</strong> do Perfil que non chegan pola rede amosan <strong>«Volver probar»</strong> en lugar de romper a páxina. O ${enllacIntern(ENLLAC_CALENDARI_R32_3, '<strong>Calendario</strong>')} acepta a ligazón con <code>?data=</code> ademais de <code>?date=</code>, o <strong>comparador de prezos</strong> das listas de Rebost de El Comú arredonda ben os <strong>céntimos</strong> e o selector de ficheiros do editor ten <strong>nome accesible</strong>.`],
  ['Corrección · A alta e a baixa dos avisos do Chat nun teléfono, sen pisarse', `A <strong>alta</strong> e a <strong>baixa</strong> dos avisos do ${enllacIntern(ENLLAC_XAT_R32_3, '<strong>Chat</strong>')} nun <strong>teléfono</strong> xa non se <strong>pisan</strong>: unha baixa non deixa vivo ningún rexistro que chegue tarde, e unha anterior non desfai unha <strong>alta nova</strong>. Os avisos aínda <strong>non se probaron</strong> en aparellos reais.`]]
};

const fitaR32_3 = (language) => {
 const [titol, obertura, abast, ...apartats] = FITA_R32_3[language];
 return `${section('h3', titol, obertura, abast)}\n      ${apartats.map(([t, c]) => subSection(t, c)).join('\n      ')}\n\n      `;
};

/* Onada R32 (16-11-2026, vesprada) · La crònica de la versió 1.2.4 (build 9) del repositori, amb el que ha aterrat de
   veres al worktree d'integració després del Gauntlet R32 (wf1_resultat.json, resolució i correcció de cada clúster):
   el Xat que no passa a error quan la sessió es renova mentre s'envia, que reenvia una sola vegada amb el mateix id i
   que només dona per enviat el que el servidor ha numerat (cablejat R30.2 de Codex, XatContext.cablejatR30_2.test.jsx);
   les carpetes noves del Bloc de Notes fora de l'espai reservat (esIdReservat, carpetesCreades.js) i el llegat ambigu
   que no puja (migracioCarpetesLocals.js); la guia public/llms.txt i l'índex public/.well-known/ard.json; la poda de
   28 classes CSS mortes (4 que semblaven mortes eren vives i es conserven); la retirada del contingut d'una nota
   eliminada que fa el dispositiu del Mode rural (compactaCrdtRural, amb un ACK remot opcional); i l'SQL
   que el Mestre va aplicar al servidor compartit el 16-11-2026 (receptari 261116_sql_produccio_r30_r31, captura
   15.03): 2611110455, 20261115230000, 2611110110 amb la quota R29, 20261116031000 i 20261116040000 (29 funcions
   SECURITY DEFINER amb search_path buit). Llei 0: la 1.2.4 (build 9) és la del repositori i la crònica no diu res de
   les botigues ni de TestFlight; el connector publicat continua en la 1.1.12; E2EE_ACTIU_PER_DEFECTE continua false,
   la crònica ho diu i el text del missatge xifrat tancat no canvia (R29-E2EE-02); l'APK/AAB 1.2.4+9 porta el pont
   natiu CiclePushNatiu, però el Push d'Android continua apagat (sense google-services.json ni claus) i la crònica no
   nomena cap plataforma (2.3.10); les claus Push VAPID/FCM/APNs i la prova en aparells físics no estan verificades,
   i la crònica diu que els avisos no s'han provat en aparells reals; l'ACK remot de la PF-03 (R30.2) és un contracte
   opcional (transportCrdtRemot) sense cap endpoint configurat, i el certificat de retirada és local del dispositiu i
   no s'accepta mai d'una còpia de fora; la retirada és de l'estat del dispositiu i no de la carpeta: el certificat no
   viatja mai per la carpeta i la carpeta conserva intacte el Markdown d'una nota retirada (invariants 9 i 10 de
   sincronitzadorCarpetaLocal.js), i per això la crònica ho diu del dispositiu i no de la carpeta (corrector R32); la
   guarda d'ACK per col·lisió (MOTIU_COLISIO) només mira les carpetes creades en este navegador i no defén una carpeta
   del servidor feta en un altre dispositiu, i la crònica no en fa cap promesa (corrector R32); l'espai entre l'hora i
   la data del botó de data i hora (WCAG 2.5.3) no canvia cap píxel (la pastilla és inline-flex en columna) ni el que
   diuen els lectors de pantalla (l'aria-label ja les separava), i la crònica no en parla (corrector R32); el CAS de publicacions (actualitza_publicacio_amb_versio) no ha aterrat i la
   crònica no en parla; la candidatura NLnet 2026-08-1a6 no va passar la primera selecció i no hi ha cap candidatura al
   NGI0 Commons Fund; cap promesa de Lighthouse ni de zero avisos. Per a l'Onada R33 quedaven les 7 funcions fòssils fora de Git i
   una sonda vàlida de 2611121630: el registre del T2 del 13-11 la dona aplicada, i supabase/README.md ho recull.
   Llei 0 de l'Onada R32.4: el Mestre va blindar les 7 funcions fòssils el 17-11-2026 a les 01:55 CET amb
   20261116170000 (certificat CERTIFICAT_5_DE_5_APLICADES_PRODUCCIO_261117_0155.md, supabase/README.md fila 117), i
   l'apartat del servidor ho diu en les cinc llengües en lloc de «per revisar».
   Les claus Push i la prova en aparells físics continuen pendents, i la crònica no en diu res més. */
const ENLLAC_XAT_R32 = '/xat';
const ENLLAC_MODE_RURAL_R32 = '/control?fitxa=mode-rural';
export const FITA_R32 = {
 ca: ['16 de novembre de 2026, vesprada · Onada R32 · Missatges del Xat que no cauen en error en renovar la sessió, carpetes del Bloc de Notes que no es confonen i més seguretat al servidor compartit',
  `L’<strong>Onada R32</strong> de <strong>Sóc de Poble</strong> fa que un missatge del ${enllacIntern(ENLLAC_XAT_R32, '<strong>Xat</strong>')} no caiga en <strong>error</strong> quan la sessió es renova mentre s’envia, evita que una <strong>carpeta</strong> del ${enllacIntern(ENLLAC_NOTES, '<strong>Bloc de Notes</strong>')} es confonga amb una de les de sèrie i lliga al <strong>servidor compartit</strong> els avisos del Xat a la teua sessió.`,
  'Les aplicacions passen a la <strong>versió 1.2.4 (build 9)</strong> al repositori, i el <strong>connector de WordPress</strong> publicat a WordPress.org continua en la <strong>1.1.12</strong>. El <strong>16 de novembre</strong> (15.03) s’han aplicat al <strong>servidor compartit</strong> cinc migracions: les revisions de les entrades importades de WordPress i el seu <strong>control de versions</strong> (<code>2611110455</code> i <code>20261115230000</code>), les campanyes de revisió dels arbres amb un límit per persona (<code>2611110110</code>), els avisos del Xat lligats a la sessió (<code>20261116031000</code>) i les funcions del servidor més tancades (<code>20261116040000</code>).',
  ['Novetat · Una guia pública per als assistents d’intel·ligència artificial', 'El repositori porta una <strong>guia pública</strong> per als <strong>assistents d’intel·ligència artificial</strong> que lligen la web, amb les pàgines principals, les <strong>llicències lliures</strong> i les <strong>dades obertes</strong>, i un <strong>índex</strong> dels recursos públics que poden llegir els programes. La guia diu que la candidatura 2026-08-1a6 a <strong>NLnet</strong> no va passar la primera selecció; tampoc no hi ha cap candidatura al NGI0 Commons Fund.'],
  ['Millora · Els avisos del Xat, lligats a la teua sessió, i funcions del servidor més tancades', 'Al <strong>servidor compartit</strong>, cada registre d’<strong>avisos del Xat</strong> en un dispositiu queda lligat a la <strong>sessió</strong> que el va fer i s’esborra quan la tanques; els registres d’abans, que no portaven sessió, s’han retirat. Els avisos encara <strong>no s’han provat</strong> en aparells reals. Les <strong>29 funcions</strong> del repositori que actuen amb permisos especials treballen ara amb una configuració <strong>més tancada</strong>, i les <strong>set antigues</strong>, que no són al repositori, s’han blindat el 17 de novembre (1.55).'],
  ['Millora · Menys estils sense ús i el Mode rural preparat per a esborrar del tot una nota eliminada', `S’han retirat <strong>28 classes d’estil</strong> que ja no feia servir cap pantalla, sense canviar res del que es veu; quatre més que semblaven sense ús eren <strong>vives</strong> i es queden. Al ${enllacIntern(ENLLAC_MODE_RURAL_R32, '<strong>Mode rural</strong>')}, este <strong>dispositiu</strong> ja sap esborrar per sempre de les seues dades el contingut d’una <strong>nota eliminada</strong> quan un servidor ho confirme, però hui <strong>no n’hi ha cap</strong> de configurat; ni la <strong>carpeta de notes</strong> ni una còpia que vinga de fora no ho poden fer mai, i la carpeta conserva els fitxers d’eixa nota tal com eren.`],
  ['Correcció · Els missatges del Xat ja no cauen en error quan es renova la sessió', `Si envies un missatge al ${enllacIntern(ENLLAC_XAT_R32, '<strong>Xat</strong>')} just quan la teua <strong>sessió</strong> es renova, la bombolla ja no passa a <strong>error</strong>: es queda <strong>pendent</strong> fins que el servidor la confirma, i el missatge arriba <strong>una sola vegada</strong>. Un missatge només es dona per <strong>enviat</strong> quan el servidor confirma que l’ha rebut. El xifratge d’extrem a extrem continua <strong>apagat</strong>.`],
  ['Correcció · Les carpetes noves del Bloc de Notes ja no es confonen amb les de sèrie', `Una <strong>carpeta nova</strong> del ${enllacIntern(ENLLAC_NOTES, '<strong>Bloc de Notes</strong>')} ja no pot rebre el mateix <strong>identificador intern</strong> que una de les de <strong>sèrie</strong> o que una del servidor: en rep un de propi, i el nom que li has posat no canvia. Una <strong>carpeta antiga</strong> d’este navegador que ja es podia confondre es queda on era i <strong>no puja sola</strong> al servidor.`]],
 es: ['16 de noviembre de 2026, tarde · Oleada R32 · Mensajes del Chat que no caen en error al renovar la sesión, carpetas del Bloc de Notas que no se confunden y más seguridad en el servidor compartido',
  `La <strong>Oleada R32</strong> de <strong>Sóc de Poble</strong> hace que un mensaje del ${enllacIntern(ENLLAC_XAT_R32, '<strong>Chat</strong>')} no caiga en <strong>error</strong> cuando la sesión se renueva mientras se envía, evita que una <strong>carpeta</strong> del ${enllacIntern(ENLLAC_NOTES, '<strong>Bloc de Notas</strong>')} se confunda con una de las de serie y vincula en el <strong>servidor compartido</strong> los avisos del Chat a tu sesión.`,
  'Las aplicaciones pasan a la <strong>versión 1.2.4 (build 9)</strong> en el repositorio, y el <strong>conector de WordPress</strong> publicado en WordPress.org sigue en la <strong>1.1.12</strong>. El <strong>16 de noviembre</strong> (15.03) se han aplicado en el <strong>servidor compartido</strong> cinco migraciones: las revisiones de las entradas importadas de WordPress y su <strong>control de versiones</strong> (<code>2611110455</code> y <code>20261115230000</code>), las campañas de revisión de los árboles con un límite por persona (<code>2611110110</code>), los avisos del Chat vinculados a la sesión (<code>20261116031000</code>) y las funciones del servidor más cerradas (<code>20261116040000</code>).',
  ['Novedad · Una guía pública para los asistentes de inteligencia artificial', 'El repositorio lleva una <strong>guía pública</strong> para los <strong>asistentes de inteligencia artificial</strong> que leen la web, con las páginas principales, las <strong>licencias libres</strong> y los <strong>datos abiertos</strong>, y un <strong>índice</strong> de los recursos públicos que pueden leer los programas. La guía dice que la candidatura 2026-08-1a6 a <strong>NLnet</strong> no pasó la primera selección; tampoco hay ninguna candidatura al NGI0 Commons Fund.'],
  ['Mejora · Los avisos del Chat, vinculados a tu sesión, y funciones del servidor más cerradas', 'En el <strong>servidor compartido</strong>, cada registro de <strong>avisos del Chat</strong> en un dispositivo queda vinculado a la <strong>sesión</strong> que lo hizo y se borra cuando la cierras; los registros anteriores, que no llevaban sesión, se han retirado. Los avisos todavía <strong>no se han probado</strong> en aparatos reales. Las <strong>29 funciones</strong> del repositorio que actúan con permisos especiales trabajan ahora con una configuración <strong>más cerrada</strong>, y las <strong>siete antiguas</strong>, que no están en el repositorio, se han blindado el 17 de noviembre (1.55).'],
  ['Mejora · Menos estilos sin uso y el Modo rural preparado para borrar del todo una nota eliminada', `Se han retirado <strong>28 clases de estilo</strong> que ya no usaba ninguna pantalla, sin cambiar nada de lo que se ve; otras cuatro que parecían sin uso estaban <strong>vivas</strong> y se quedan. En el ${enllacIntern(ENLLAC_MODE_RURAL_R32, '<strong>Modo rural</strong>')}, este <strong>dispositivo</strong> ya sabe borrar para siempre de sus datos el contenido de una <strong>nota eliminada</strong> cuando un servidor lo confirme, pero hoy <strong>no hay ninguno</strong> configurado; ni la <strong>carpeta de notas</strong> ni una copia que venga de fuera pueden hacerlo nunca, y la carpeta conserva los archivos de esa nota tal como estaban.`],
  ['Corrección · Los mensajes del Chat ya no caen en error cuando se renueva la sesión', `Si envías un mensaje en el ${enllacIntern(ENLLAC_XAT_R32, '<strong>Chat</strong>')} justo cuando tu <strong>sesión</strong> se renueva, la burbuja ya no pasa a <strong>error</strong>: se queda <strong>pendiente</strong> hasta que el servidor la confirma, y el mensaje llega <strong>una sola vez</strong>. Un mensaje solo se da por <strong>enviado</strong> cuando el servidor confirma que lo ha recibido. El cifrado de extremo a extremo sigue <strong>apagado</strong>.`],
  ['Corrección · Las carpetas nuevas del Bloc de Notas ya no se confunden con las de serie', `Una <strong>carpeta nueva</strong> del ${enllacIntern(ENLLAC_NOTES, '<strong>Bloc de Notas</strong>')} ya no puede recibir el mismo <strong>identificador interno</strong> que una de las de <strong>serie</strong> o que una del servidor: recibe uno propio, y el nombre que le has puesto no cambia. Una <strong>carpeta antigua</strong> de este navegador que ya se podía confundir se queda donde estaba y <strong>no sube sola</strong> al servidor.`]],
 en: ['16 November 2026, evening · Wave R32 · Chat messages that no longer fail when the session renews, Notebook folders that are not mixed up and more security on the shared server',
  `<strong>Wave R32</strong> of <strong>Sóc de Poble</strong> stops a message in the ${enllacIntern(ENLLAC_XAT_R32, '<strong>Chat</strong>')} from ending in an <strong>error</strong> when the session renews while it is being sent, keeps a <strong>folder</strong> in the ${enllacIntern(ENLLAC_NOTES, '<strong>Notebook</strong>')} from being mixed up with a built-in one and ties Chat notifications to your session on the <strong>shared server</strong>.`,
  'The applications move to <strong>version 1.2.4 (build 9)</strong> in the repository, and the <strong>WordPress plugin</strong> published on WordPress.org stays on <strong>1.1.12</strong>. On <strong>16 November</strong> (15:03) five migrations were applied on the <strong>shared server</strong>: the reviews of entries imported from WordPress and their <strong>version control</strong> (<code>2611110455</code> and <code>20261115230000</code>), the review campaigns for trees with a limit per person (<code>2611110110</code>), Chat notifications tied to the session (<code>20261116031000</code>) and tighter server functions (<code>20261116040000</code>).',
  ['New · A public guide for artificial intelligence assistants', 'The repository carries a <strong>public guide</strong> for <strong>artificial intelligence assistants</strong> that read the website, with the main pages, the <strong>free licences</strong> and the <strong>open data</strong>, and an <strong>index</strong> of the public resources that programs can read. The guide says that application 2026-08-1a6 to <strong>NLnet</strong> did not pass the first selection; nor is there any application to the NGI0 Commons Fund.'],
  ['Improvement · Chat notifications tied to your session, and tighter server functions', 'On the <strong>shared server</strong>, each device registration for <strong>Chat notifications</strong> is now tied to the <strong>session</strong> that created it and is deleted when you sign out; older registrations, which had no session, have been removed. Notifications have <strong>not yet been tested</strong> on real devices. The <strong>29 functions</strong> in the repository that run with special permissions now work with a <strong>tighter</strong> configuration, and the <strong>seven older ones</strong> that are not in the repository were tightened on 17 November (01:55).'],
  ['Improvement · Fewer unused styles and Rural mode ready to erase a deleted note for good', `<strong>28 style classes</strong> that no screen used any more have been removed, without changing anything you see; four more that looked unused were <strong>in use</strong> and stay. In ${enllacIntern(ENLLAC_MODE_RURAL_R32, '<strong>Rural mode</strong>')}, this <strong>device</strong> can now erase for good from its own data the content of a <strong>deleted note</strong> once a server confirms it, but today <strong>none is configured</strong>; neither the <strong>notes folder</strong> nor a copy coming from elsewhere can ever do it, and the folder keeps that note’s files as they were.`],
  ['Fix · Chat messages no longer fail when the session renews', `If you send a message in the ${enllacIntern(ENLLAC_XAT_R32, '<strong>Chat</strong>')} just as your <strong>session</strong> renews, the bubble no longer turns into an <strong>error</strong>: it stays <strong>pending</strong> until the server confirms it, and the message arrives <strong>only once</strong>. A message only counts as <strong>sent</strong> when the server confirms it has received it. End-to-end encryption stays <strong>switched off</strong>.`],
  ['Fix · New Notebook folders are no longer mixed up with the built-in ones', `A <strong>new folder</strong> in the ${enllacIntern(ENLLAC_NOTES, '<strong>Notebook</strong>')} can no longer get the same <strong>internal identifier</strong> as a <strong>built-in</strong> folder or a server folder: it gets its own, and the name you gave it does not change. An <strong>old folder</strong> in this browser that could already be mixed up stays where it was and is <strong>not uploaded</strong> to the server on its own.`]],
 eu: ['2026ko azaroaren 16a, arratsaldea · R32 olatua · Saioa berritzean errorean geratzen ez diren Txateko mezuak, nahasten ez diren Koadernoko karpetak eta segurtasun handiagoa zerbitzari partekatuan',
  `<strong>Sóc de Poble</strong> plataformako <strong>R32 olatuak</strong> lortzen du ${enllacIntern(ENLLAC_XAT_R32, '<strong>Txateko</strong>')} mezu bat <strong>errorean</strong> ez geratzea bidaltzen ari den bitartean saioa berritzen bada, ${enllacIntern(ENLLAC_NOTES, '<strong>Koadernoko</strong>')} <strong>karpeta</strong> bat lehenetsitako batekin ez nahastea, eta Txateko abisuak zure saioari lotzea <strong>zerbitzari partekatuan</strong>.`,
  'Aplikazioak <strong>1.2.4 bertsiora (9. builda)</strong> igarotzen dira biltegian, eta WordPress.org direktorioan argitaratutako <strong>WordPress konektorea</strong> <strong>1.1.12</strong> da oraindik. <strong>Azaroaren 16an</strong> (15:03) bost migrazio aplikatu dira <strong>zerbitzari partekatuan</strong>: WordPressetik inportatutako sarreren berrikuspenak eta haien <strong>bertsio-kontrola</strong> (<code>2611110455</code> eta <code>20261115230000</code>), zuhaitzen berrikuspen-kanpainak pertsona bakoitzeko muga batekin (<code>2611110110</code>), saioari lotutako Txateko abisuak (<code>20261116031000</code>) eta zerbitzariko funtzio itxiagoak (<code>20261116040000</code>).',
  ['Berritasuna · Adimen artifizialeko laguntzaileentzako gida publikoa', 'Biltegiak <strong>gida publiko</strong> bat dakar weba irakurtzen duten <strong>adimen artifizialeko laguntzaileentzat</strong>, orri nagusiekin, <strong>lizentzia libreekin</strong> eta <strong>datu irekiekin</strong>, eta programek irakur ditzaketen baliabide publikoen <strong>aurkibide</strong> bat. Gidak dio <strong>NLnet</strong> fundazioari aurkeztutako 2026-08-1a6 hautagaitzak ez zuela lehen hautaketa gainditu; NGI0 Commons Fund funtsean ere ez dago hautagaitzarik.'],
  ['Hobekuntza · Txateko abisuak zure saioari lotuta, eta zerbitzariko funtzio itxiagoak', '<strong>Zerbitzari partekatuan</strong>, gailu bateko <strong>Txateko abisuen</strong> erregistro bakoitza sortu zuen <strong>saioari</strong> lotuta geratzen da, eta saioa ixten duzunean ezabatu egiten da; lehengo erregistroak, saiorik ez zutenak, kendu egin dira. Abisuak <strong>ez dira oraindik probatu</strong> benetako gailuetan. Baimen bereziekin jarduten duten biltegiko <strong>29 funtzioek</strong> konfigurazio <strong>itxiagoa</strong> dute orain, eta biltegian ez dauden <strong>zazpi funtzio zaharrak</strong> azaroaren 17an blindatu dira (01:55ean).'],
  ['Hobekuntza · Erabili gabeko estilo gutxiago eta Landa-modua prest ezabatutako ohar bat betiko ezabatzeko', `Jada inongo pantailak erabiltzen ez zituen <strong>28 estilo-klase</strong> kendu dira, ikusten den ezer aldatu gabe; erabili gabe zirudien beste lau <strong>bizirik</strong> zeuden eta geratu egiten dira. ${enllacIntern(ENLLAC_MODE_RURAL_R32, '<strong>Landa-moduan</strong>')}, <strong>gailu</strong> honek badaki <strong>ezabatutako ohar</strong> baten edukia bere datuetatik betiko ezabatzen zerbitzari batek berresten duenean, baina gaur <strong>ez dago bat ere</strong> konfiguratuta; <strong>oharren karpetak</strong> eta kanpotik datorren kopia batek ezin dute hori inoiz egin, eta karpetak ohar horren fitxategiak zeuden bezala gordetzen ditu.`],
  ['Zuzenketa · Txateko mezuak ez dira jada errorean geratzen saioa berritzean', `${enllacIntern(ENLLAC_XAT_R32, '<strong>Txatean</strong>')} mezu bat bidaltzen baduzu zure <strong>saioa</strong> berritzen den unean bertan, burbuila ez da jada <strong>errore</strong> egoerara pasatzen: <strong>zain</strong> geratzen da zerbitzariak berretsi arte, eta mezua <strong>behin bakarrik</strong> iristen da. Mezu bat <strong>bidalitzat</strong> jotzen da soilik zerbitzariak jaso duela berresten duenean. Muturretik muturrerako zifratzea <strong>itzalita</strong> dago oraindik.`],
  ['Zuzenketa · Koadernoko karpeta berriak ez dira jada lehenetsitakoekin nahasten', `${enllacIntern(ENLLAC_NOTES, '<strong>Koadernoko</strong>')} <strong>karpeta berri</strong> batek ezin du jada <strong>lehenetsitako</strong> karpeta baten edo zerbitzariko karpeta baten <strong>barne-identifikatzaile</strong> bera jaso: berea jasotzen du, eta jarri diozun izena ez da aldatzen. Lehendik nahas zitekeen nabigatzaile honetako <strong>karpeta zahar</strong> bat lehen zegoen lekuan geratzen da eta <strong>ez da bere kabuz igotzen</strong> zerbitzarira.`]],
 gl: ['16 de novembro de 2026, tarde · Onda R32 · Mensaxes do Chat que non caen en erro ao renovar a sesión, cartafoles do Caderno de Notas que non se confunden e máis seguridade no servidor compartido',
  `A <strong>Onda R32</strong> de <strong>Sóc de Poble</strong> fai que unha mensaxe do ${enllacIntern(ENLLAC_XAT_R32, '<strong>Chat</strong>')} non caia en <strong>erro</strong> cando a sesión se renova mentres se envía, evita que un <strong>cartafol</strong> do ${enllacIntern(ENLLAC_NOTES, '<strong>Caderno de Notas</strong>')} se confunda cun dos de serie e vincula no <strong>servidor compartido</strong> os avisos do Chat á túa sesión.`,
  'As aplicacións pasan á <strong>versión 1.2.4 (build 9)</strong> no repositorio, e o <strong>conector de WordPress</strong> publicado en WordPress.org segue na <strong>1.1.12</strong>. O <strong>16 de novembro</strong> (15.03) aplicáronse no <strong>servidor compartido</strong> cinco migracións: as revisións das entradas importadas de WordPress e o seu <strong>control de versións</strong> (<code>2611110455</code> e <code>20261115230000</code>), as campañas de revisión das árbores cun límite por persoa (<code>2611110110</code>), os avisos do Chat vinculados á sesión (<code>20261116031000</code>) e as funcións do servidor máis pechadas (<code>20261116040000</code>).',
  ['Novidade · Unha guía pública para os asistentes de intelixencia artificial', 'O repositorio leva unha <strong>guía pública</strong> para os <strong>asistentes de intelixencia artificial</strong> que len a web, coas páxinas principais, as <strong>licenzas libres</strong> e os <strong>datos abertos</strong>, e un <strong>índice</strong> dos recursos públicos que poden ler os programas. A guía di que a candidatura 2026-08-1a6 a <strong>NLnet</strong> non pasou a primeira selección; tampouco hai ningunha candidatura ao NGI0 Commons Fund.'],
  ['Mellora · Os avisos do Chat, vinculados á túa sesión, e funcións do servidor máis pechadas', 'No <strong>servidor compartido</strong>, cada rexistro de <strong>avisos do Chat</strong> nun dispositivo queda vinculado á <strong>sesión</strong> que o fixo e bórrase cando a pechas; os rexistros anteriores, que non levaban sesión, retiráronse. Os avisos aínda <strong>non se probaron</strong> en aparellos reais. As <strong>29 funcións</strong> do repositorio que actúan con permisos especiais traballan agora cunha configuración <strong>máis pechada</strong>, e as <strong>sete antigas</strong>, que non están no repositorio, blindáronse o 17 de novembro (1.55).'],
  ['Mellora · Menos estilos sen uso e o Modo rural preparado para borrar do todo unha nota eliminada', `Retiráronse <strong>28 clases de estilo</strong> que xa non usaba ningunha pantalla, sen cambiar nada do que se ve; outras catro que parecían sen uso estaban <strong>vivas</strong> e quedan. No ${enllacIntern(ENLLAC_MODE_RURAL_R32, '<strong>Modo rural</strong>')}, este <strong>dispositivo</strong> xa sabe borrar para sempre dos seus datos o contido dunha <strong>nota eliminada</strong> cando un servidor o confirme, pero hoxe <strong>non hai ningún</strong> configurado; nin o <strong>cartafol de notas</strong> nin unha copia que veña de fóra o poden facer nunca, e o cartafol conserva os ficheiros desa nota tal como estaban.`],
  ['Corrección · As mensaxes do Chat xa non caen en erro cando se renova a sesión', `Se envías unha mensaxe no ${enllacIntern(ENLLAC_XAT_R32, '<strong>Chat</strong>')} xusto cando a túa <strong>sesión</strong> se renova, a burbulla xa non pasa a <strong>erro</strong>: queda <strong>pendente</strong> ata que o servidor a confirma, e a mensaxe chega <strong>unha soa vez</strong>. Unha mensaxe só se dá por <strong>enviada</strong> cando o servidor confirma que a recibiu. O cifrado de extremo a extremo segue <strong>apagado</strong>.`],
  ['Corrección · Os cartafoles novos do Caderno de Notas xa non se confunden cos de serie', `Un <strong>cartafol novo</strong> do ${enllacIntern(ENLLAC_NOTES, '<strong>Caderno de Notas</strong>')} xa non pode recibir o mesmo <strong>identificador interno</strong> ca un dos de <strong>serie</strong> ou ca un do servidor: recibe un propio, e o nome que lle puxeches non cambia. Un <strong>cartafol antigo</strong> deste navegador que xa se podía confundir queda onde estaba e <strong>non sobe só</strong> ao servidor.`]]
};

const fitaR32 = (language) => {
 const [titol, obertura, abast, ...apartats] = FITA_R32[language];
 return `${section('h3', titol, obertura, abast)}\n      ${apartats.map(([t, c]) => subSection(t, c)).join('\n      ')}\n\n      `;
};

/* Onada R30 (16-11-2026, matinada) · Les carpetes del Bloc de Notes que només eren al navegador es creen al servidor
   en entrar amb sessió, sense esborrar ni reescriure cap carpeta local (PF-01, migracioCarpetesLocals.js); la carpeta
   de notes del Mode rural consolida en sincronitzar les entrades amb ACK del dispositiu de més de 90 dies, sense
   llevar cap operació ni cap tombstone (PF-03, sincronitzadorCarpetaLocal.js); el TPV del Bar, una operació per gest
   (R30-BAR-01 a 03; el Rebost Domèstic no hi canvia); la Gestoria, set lectures lineals (A6-RX1 a RX7); la veu que no
   llig la pàgina d'abans (lot 14 de Codex, useTraduccioPagina.d2.cicle); el connector de WordPress, 8.136 B menys a
   l'arrencada (A4: la meitat del servidor de les revisions editorials ix de l'entrada); el deute de les portes
   (classes foranes 15 → 0, LLEI_06 5 → 1, lots 12 i 13 de Codex, chat_title_suggestion de tancament.mjs); i NAT-04,
   dit sense nomenar cap plataforma (2.3.10), com la icona temàtica de la R28: «als mòbils on els declarava».
   Llei 0: el text del missatge xifrat tancat (R29-E2EE-02) és darrere de la bandera compilada
   E2EE_ACTIU_PER_DEFECTE, que continua apagada, i la crònica ho diu; la 1.2.3 (build 8) és la del repositori i la
   crònica no diu res de les botigues; el connector publicat continua en la 1.1.12. Les migracions 20261114000100,
   20261115030000 i 20261115170000 es van aplicar al servidor compartit el 15-11-2026 a les 23.11 (acta Marmota
   261116_0103, amb captura); la 20261115230000 (control de versions de les revisions de WordPress) no s'havia aplicat
   quan es va escriure esta crònica (el client es degrada amb gràcia sense ella).
   Onada R32 · Llei 0 · El Mestre la va aplicar al servidor compartit el 16-11-2026 a la vesprada (receptari
   261116_sql_produccio_r30_r31/RECEPTARI_SQL_PRODUCCIO_R30_R31.md, pas1_wp_cas_ok, captura 15.03): l'entrada R30 ja
   no diu que «encara no s'ha aplicat», sinó que llavors encara no s'havia aplicat i que s'hi va aplicar el 16 de
   novembre. La resta del text R30 continua sent cert. */
const ENLLAC_XAT_R30 = '/xat';
const ENLLAC_MODE_RURAL_R30 = '/control?fitxa=mode-rural';
export const FITA_R30 = {
 ca: ['16 de novembre de 2026, matinada · Onada R30 · Les carpetes antigues del Bloc de Notes al servidor, una carpeta del Mode rural que es compacta sola i dos tocs que ja no compten doble',
  `L’<strong>Onada R30</strong> de <strong>Sóc de Poble</strong> porta al servidor les <strong>carpetes antigues</strong> del ${enllacIntern(ENLLAC_NOTES, '<strong>Bloc de Notes</strong>')}, fa que la carpeta de notes del ${enllacIntern(ENLLAC_MODE_RURAL_R30, '<strong>Mode rural</strong>')} es compacte sola sense perdre cap canvi i evita que <strong>dos tocs seguits</strong> facen dues vegades la mateixa operació al <strong>TPV del Bar</strong>.`,
  'Les aplicacions passen a la <strong>versió 1.2.3 (build 8)</strong> al repositori, i el <strong>connector de WordPress</strong> publicat a WordPress.org continua en la <strong>1.1.12</strong>. Les migracions <code>20261114000100</code>, <code>20261115030000</code> i <code>20261115170000</code> <strong>ja s’han aplicat</strong> al <strong>servidor compartit</strong> (15 de novembre, 23.11), i la nova del <strong>control de versions</strong> de les revisions de WordPress (<code>20261115230000</code>), que llavors encara no s’havia aplicat, s’hi va aplicar el <strong>16 de novembre</strong> a la vesprada.',
  ['Millora · La carpeta de notes del Mode rural es compacta sola', `Quan sincronitzes la <strong>carpeta de notes</strong> del ${enllacIntern(ENLLAC_MODE_RURAL_R30, '<strong>Mode rural</strong>')}, els fitxers antics <strong>sense editar</strong> que este dispositiu va confirmar fa <strong>més de 90 dies</strong> es consoliden <strong>sense perdre cap canvi</strong>, i cap <strong>nota eliminada</strong> no torna. Així, la carpeta ja no guarda <strong>per sempre</strong> les versions antigues.`],
  ['Millora · Un connector de WordPress més lleuger i menys deute per dins', 'El paquet del <strong>connector de WordPress</strong> que es construïx des del repositori arrenca uns <strong>8 KB més lleuger</strong>: la part de les <strong>revisions editorials</strong> que parla amb el servidor ja no viatja en l’arrencada. Per dins, les classes d’estil sense cap regla al darrere passen de <strong>15 a 0</strong> i els accessos directes al document, de <strong>5 a 1</strong>; la comprovació dels <strong>tokens de disseny</strong> llig també les declaracions de diverses línies, la regla per a propagar decisions a la Wiki diu on pot escriure i, en tancar una sessió de treball, l’eina de tancament proposa un <strong>títol amb data i hora</strong>.'],
  ['Correcció · Les carpetes d’abans del Bloc de Notes arriben al servidor', `Les <strong>carpetes</strong> del ${enllacIntern(ENLLAC_NOTES, '<strong>Bloc de Notes</strong>')} creades abans de la correcció de l’<strong>Onada R29</strong>, que només eren en este navegador, es creen soles al <strong>servidor</strong> quan entres amb la teua <strong>sessió</strong>. No s’esborra ni es canvia cap carpeta d’este dispositiu: les notes continuen on eren, el Bloc es veu igual i, si el servidor <strong>no la confirma</strong>, es torna a provar la pròxima vegada que entres.`],
  ['Correcció · La veu ja no llig la pàgina d’abans, i un text serè per als missatges xifrats', `Si tries «<strong>Escoltar esta pàgina en veu alta</strong>» al menú Traduir i canvies de pàgina mentre la veu encara es carrega, ja no es posa a llegir la <strong>pàgina d’abans</strong>. Al ${enllacIntern(ENLLAC_XAT_R30, '<strong>Xat</strong>')}, el <strong>xifratge d’extrem a extrem</strong> continua <strong>apagat</strong>, i darrere d’ell ja hi ha preparat el text d’un missatge xifrat que este aparell no pot obrir: «Missatge xifrat d’extrem a extrem en un altre dispositiu» quan li falta la clau, i «No s’ha pogut obrir este missatge xifrat» en la resta de casos, <strong>sense cap codi</strong> tècnic i sense deixar el missatge <strong>en blanc</strong>.`],
  ['Correcció · Dos tocs seguits al TPV del Bar, fitxers grans a la Gestoria i menys permisos', 'Al <strong>TPV del Bar</strong>, dos tocs seguits ja no fan <strong>dues devolucions</strong> del mateix tiquet, no anoten dues vegades un <strong>moviment de caixa</strong> ni anul·len unitats de més. A la <strong>Gestoria</strong>, un <strong>extracte del banc</strong> o un <strong>PDF de factura</strong> amb tires de desenes de milers de caràcters es llig en mil·lisegons, no en segons. I l’app ja no demana <strong>permisos</strong> de biometria ni de comptes que no fa servir als mòbils on els declarava.']],
 es: ['16 de noviembre de 2026, madrugada · Oleada R30 · Las carpetas antiguas del Bloc de Notas en el servidor, una carpeta del Modo rural que se compacta sola y dos toques que ya no cuentan doble',
  `La <strong>Oleada R30</strong> de <strong>Sóc de Poble</strong> lleva al servidor las <strong>carpetas antiguas</strong> del ${enllacIntern(ENLLAC_NOTES, '<strong>Bloc de Notas</strong>')}, hace que la carpeta de notas del ${enllacIntern(ENLLAC_MODE_RURAL_R30, '<strong>Modo rural</strong>')} se compacte sola sin perder ningún cambio y evita que <strong>dos toques seguidos</strong> hagan dos veces la misma operación en el <strong>TPV del Bar</strong>.`,
  'Las aplicaciones pasan a la <strong>versión 1.2.3 (build 8)</strong> en el repositorio, y el <strong>conector de WordPress</strong> publicado en WordPress.org sigue en la <strong>1.1.12</strong>. Las migraciones <code>20261114000100</code>, <code>20261115030000</code> y <code>20261115170000</code> <strong>ya se han aplicado</strong> en el <strong>servidor compartido</strong> (15 de noviembre, 23.11), y la nueva del <strong>control de versiones</strong> de las revisiones de WordPress (<code>20261115230000</code>), que entonces todavía no se había aplicado, se aplicó el <strong>16 de noviembre</strong> por la tarde.',
  ['Mejora · La carpeta de notas del Modo rural se compacta sola', `Cuando sincronizas la <strong>carpeta de notas</strong> del ${enllacIntern(ENLLAC_MODE_RURAL_R30, '<strong>Modo rural</strong>')}, los archivos antiguos <strong>sin editar</strong> que este dispositivo confirmó hace <strong>más de 90 días</strong> se consolidan <strong>sin perder ningún cambio</strong>, y ninguna <strong>nota eliminada</strong> vuelve. Así, la carpeta ya no guarda <strong>para siempre</strong> las versiones antiguas.`],
  ['Mejora · Un conector de WordPress más ligero y menos deuda por dentro', 'El paquete del <strong>conector de WordPress</strong> que se construye desde el repositorio arranca unos <strong>8 KB más ligero</strong>: la parte de las <strong>revisiones editoriales</strong> que habla con el servidor ya no viaja en el arranque. Por dentro, las clases de estilo sin ninguna regla detrás pasan de <strong>15 a 0</strong> y los accesos directos al documento, de <strong>5 a 1</strong>; la comprobación de los <strong>tokens de diseño</strong> lee también las declaraciones de varias líneas, la regla para propagar decisiones a la Wiki dice dónde puede escribir y, al cerrar una sesión de trabajo, la herramienta de cierre propone un <strong>título con fecha y hora</strong>.'],
  ['Corrección · Las carpetas de antes del Bloc de Notas llegan al servidor', `Las <strong>carpetas</strong> del ${enllacIntern(ENLLAC_NOTES, '<strong>Bloc de Notas</strong>')} creadas antes de la corrección de la <strong>Oleada R29</strong>, que solo estaban en este navegador, se crean solas en el <strong>servidor</strong> cuando entras con tu <strong>sesión</strong>. No se borra ni se cambia ninguna carpeta de este dispositivo: las notas siguen donde estaban, el Bloc se ve igual y, si el servidor <strong>no la confirma</strong>, se vuelve a intentar la próxima vez que entres.`],
  ['Corrección · La voz ya no lee la página anterior, y un texto sereno para los mensajes cifrados', `Si eliges «<strong>Escuchar esta página en voz alta</strong>» en el menú Traducir y cambias de página mientras la voz todavía se carga, ya no se pone a leer la <strong>página anterior</strong>. En el ${enllacIntern(ENLLAC_XAT_R30, '<strong>Chat</strong>')}, el <strong>cifrado de extremo a extremo</strong> sigue <strong>apagado</strong>, y detrás de él ya está preparado el texto de un mensaje cifrado que este aparato no puede abrir: «Mensaje cifrado de extremo a extremo en otro dispositivo» cuando le falta la clave, y «No se ha podido abrir este mensaje cifrado» en el resto de casos, <strong>sin ningún código</strong> técnico y sin dejar el mensaje <strong>en blanco</strong>.`],
  ['Corrección · Dos toques seguidos en el TPV del Bar, archivos grandes en la Gestoria y menos permisos', 'En el <strong>TPV del Bar</strong>, dos toques seguidos ya no hacen <strong>dos devoluciones</strong> del mismo tique, no anotan dos veces un <strong>movimiento de caja</strong> ni anulan unidades de más. En la <strong>Gestoria</strong>, un <strong>extracto del banco</strong> o un <strong>PDF de factura</strong> con tiras de decenas de miles de caracteres se lee en milisegundos, no en segundos. Y la app ya no pide <strong>permisos</strong> de biometría ni de cuentas que no usa en los móviles donde los declaraba.']],
 en: ['16 November 2026, early morning · Wave R30 · Old Notebook folders on the server, a Rural mode folder that compacts itself and two taps that no longer count twice',
  `<strong>Wave R30</strong> of <strong>Sóc de Poble</strong> brings the <strong>old folders</strong> of the ${enllacIntern(ENLLAC_NOTES, '<strong>Notebook</strong>')} to the server, lets the notes folder of ${enllacIntern(ENLLAC_MODE_RURAL_R30, '<strong>Rural mode</strong>')} compact itself without losing any change and stops <strong>two quick taps</strong> from doing the same operation twice in the <strong>TPV del Bar</strong>.`,
  'The applications move to <strong>version 1.2.3 (build 8)</strong> in the repository, and the <strong>WordPress plugin</strong> published on WordPress.org stays on <strong>1.1.12</strong>. Migrations <code>20261114000100</code>, <code>20261115030000</code> and <code>20261115170000</code> <strong>have already been applied</strong> on the <strong>shared server</strong> (15 November, 23:11), and the new <strong>version control</strong> migration for WordPress revisions (<code>20261115230000</code>), which had not yet been applied at the time, was applied on <strong>16 November</strong> in the afternoon.',
  ['Improvement · The Rural mode notes folder compacts itself', `When you sync the <strong>notes folder</strong> of ${enllacIntern(ENLLAC_MODE_RURAL_R30, '<strong>Rural mode</strong>')}, old <strong>unedited</strong> files that this device confirmed <strong>more than 90 days</strong> ago are consolidated <strong>without losing any change</strong>, and no <strong>deleted note</strong> comes back. The folder no longer keeps old versions <strong>forever</strong>.`],
  ['Improvement · A lighter WordPress plugin and less debt under the hood', 'The <strong>WordPress plugin</strong> package built from the repository starts about <strong>8 KB lighter</strong>: the part of the <strong>editorial revisions</strong> that talks to the server no longer travels at start-up. Under the hood, style classes with no rule behind them go from <strong>15 to 0</strong> and direct accesses to the document, from <strong>5 to 1</strong>; the <strong>design token</strong> check also reads declarations spread over several lines, the rule for passing decisions on to the Wiki states where it may write and, when a work session is closed, the closing tool suggests a <strong>title with date and time</strong>.'],
  ['Fix · Older Notebook folders reach the server', `The <strong>folders</strong> in the ${enllacIntern(ENLLAC_NOTES, '<strong>Notebook</strong>')} created before the <strong>Wave R29</strong> fix, which only lived in this browser, are created on the <strong>server</strong> by themselves when you <strong>sign in</strong>. No folder on this device is deleted or changed: notes stay where they were, the Notebook looks the same and, if the server <strong>does not confirm</strong> a folder, it is tried again the next time you sign in.`],
  ['Fix · The voice no longer reads the previous page, and a calm text for encrypted messages', `If you choose “<strong>Listen to this page aloud</strong>” in the Translate menu and change page while the voice is still loading, it no longer starts reading the <strong>previous page</strong>. In the ${enllacIntern(ENLLAC_XAT_R30, '<strong>Chat</strong>')}, <strong>end-to-end encryption</strong> stays <strong>switched off</strong>, and behind it the text for an encrypted message this device cannot open is already in place: “End-to-end encrypted message on another device” when the key is missing, and “This encrypted message could not be opened” in every other case, with <strong>no technical code</strong> and without leaving the message <strong>blank</strong>.`],
  ['Fix · Two quick taps in the TPV del Bar, large files in the Gestoria and fewer permissions', 'In the <strong>TPV del Bar</strong>, two quick taps no longer make <strong>two refunds</strong> of the same receipt, record a <strong>cash movement</strong> twice or void extra units. In the <strong>Gestoria</strong>, a <strong>bank statement</strong> or an <strong>invoice PDF</strong> with runs of tens of thousands of characters is read in milliseconds, not seconds. And the app no longer asks for <strong>permissions</strong> for biometrics or accounts it does not use on the phones where it declared them.']],
 eu: ['2026ko azaroaren 16a, goizaldea · R30 olatua · Koadernoko karpeta zaharrak zerbitzarian, bere kabuz trinkotzen den Landa-moduko karpeta eta bi aldiz zenbatzen ez diren bi ukitu',
  `<strong>Sóc de Poble</strong> plataformako <strong>R30 olatuak</strong> ${enllacIntern(ENLLAC_NOTES, '<strong>Koadernoko</strong>')} <strong>karpeta zaharrak</strong> zerbitzarira eramaten ditu, ${enllacIntern(ENLLAC_MODE_RURAL_R30, '<strong>Landa-moduko</strong>')} oharren karpeta bere kabuz trinkotzea lortzen du aldaketarik galdu gabe, eta <strong>TPV del Bar</strong> tresnan <strong>bi ukitu jarraian</strong> eragiketa bera bi aldiz egitea saihesten du.`,
  'Aplikazioak <strong>1.2.3 bertsiora (8. builda)</strong> igarotzen dira biltegian, eta WordPress.org direktorioan argitaratutako <strong>WordPress konektorea</strong> <strong>1.1.12</strong> da oraindik. <code>20261114000100</code>, <code>20261115030000</code> eta <code>20261115170000</code> migrazioak <strong>jada aplikatu dira</strong> <strong>zerbitzari partekatuan</strong> (azaroaren 15ean, 23:11n), eta WordPresseko berrikuspenen <strong>bertsio-kontrolaren</strong> migrazio berria (<code>20261115230000</code>), orduan oraindik aplikatu gabe zegoena, <strong>azaroaren 16an</strong> arratsaldean aplikatu zen.',
  ['Hobekuntza · Landa-moduko oharren karpeta bere kabuz trinkotzen da', `${enllacIntern(ENLLAC_MODE_RURAL_R30, '<strong>Landa-moduko</strong>')} <strong>oharren karpeta</strong> sinkronizatzen duzunean, gailu honek duela <strong>90 egun baino gehiago</strong> berretsitako <strong>editatu gabeko</strong> fitxategi zaharrak bateratu egiten dira, <strong>aldaketarik galdu gabe</strong>, eta <strong>ezabatutako oharrik</strong> ez da itzultzen. Horrela, karpetak ez ditu jada bertsio zaharrak <strong>betiko</strong> gordetzen.`],
  ['Hobekuntza · WordPress konektore arinagoa eta zor gutxiago barnean', 'Biltegitik eraikitzen den <strong>WordPress konektorearen</strong> paketea <strong>8 KB inguru arinago</strong> abiarazten da: zerbitzariarekin hitz egiten duen <strong>berrikuspen editorialen</strong> zatia ez da jada abiaraztean kargatzen. Barnean, atzean araurik ez duten estilo-klaseak <strong>15etik 0ra</strong> jaitsi dira, eta dokumenturako sarbide zuzenak, <strong>5etik 1era</strong>; <strong>diseinu-tokenen</strong> egiaztapenak lerro bat baino gehiagotan idatzitako deklarazioak ere irakurtzen ditu, Wikira erabakiak hedatzeko arauak non idatz dezakeen zehazten du eta, lan-saio bat ixtean, ixteko tresnak <strong>data eta orduko izenburu</strong> bat proposatzen du.'],
  ['Zuzenketa · Koadernoko karpeta zaharrak zerbitzarira iristen dira', `<strong>R29 olatuaren</strong> zuzenketa baino lehen sortutako ${enllacIntern(ENLLAC_NOTES, '<strong>Koadernoko</strong>')} <strong>karpetak</strong>, nabigatzaile honetan bakarrik zeudenak, bere kabuz sortzen dira <strong>zerbitzarian</strong> zure <strong>saioarekin</strong> sartzen zarenean. Gailu honetako karpetarik ez da ezabatzen ezta aldatzen ere: oharrak lehen zeuden lekuan daude, Koadernoak itxura bera du eta, zerbitzariak karpeta <strong>berresten ez badu</strong>, hurrengo aldiz sartzen zarenean berriro saiatzen da.`],
  ['Zuzenketa · Ahotsak ez du jada aurreko orria irakurtzen, eta testu lasai bat mezu zifratuentzat', `Itzulpena menuan «<strong>Entzun orri hau ozen</strong>» aukeratu eta ahotsa oraindik kargatzen ari dela orriz aldatzen baduzu, ez da jada <strong>aurreko orria</strong> irakurtzen hasten. ${enllacIntern(ENLLAC_XAT_R30, '<strong>Txatean</strong>')}, <strong>muturretik muturrerako zifratzea</strong> <strong>itzalita</strong> dago oraindik, eta haren atzean prest dago gailu honek ireki ezin duen mezu zifratu baten testua: «Beste gailu batean muturretik muturrera zifratutako mezua» gakoa falta zaionean, eta «Ezin izan da zifratutako mezu hau ireki» gainerako kasuetan, <strong>kode teknikorik gabe</strong> eta mezua <strong>hutsik</strong> utzi gabe.`],
  ['Zuzenketa · Bi ukitu jarraian TPV del Bar tresnan, fitxategi handiak Gestorian eta baimen gutxiago', '<strong>TPV del Bar</strong> tresnan, bi ukitu jarraian eginda ez dira jada tiket bereko <strong>bi itzulketa</strong> egiten, ez da <strong>kutxako mugimendu</strong> bat bi aldiz idazten eta ez dira behar baino unitate gehiago baliogabetzen. <strong>Gestorian</strong>, hamarnaka mila karaktereko kateak dituen <strong>banku-laburpen</strong> bat edo <strong>fakturako PDF</strong> bat milisegundotan irakurtzen da, ez segundotan. Eta aplikazioak ez ditu jada eskatzen erabiltzen ez dituen <strong>biometria- eta kontu-baimenak</strong>, haiek adierazten zituen mugikorretan.']],
 gl: ['16 de novembro de 2026, madrugada · Onda R30 · Os cartafoles antigos do Caderno de Notas no servidor, un cartafol do Modo rural que se compacta só e dous toques que xa non contan dobre',
  `A <strong>Onda R30</strong> de <strong>Sóc de Poble</strong> leva ao servidor os <strong>cartafoles antigos</strong> do ${enllacIntern(ENLLAC_NOTES, '<strong>Caderno de Notas</strong>')}, fai que o cartafol de notas do ${enllacIntern(ENLLAC_MODE_RURAL_R30, '<strong>Modo rural</strong>')} se compacte só sen perder ningún cambio e evita que <strong>dous toques seguidos</strong> fagan dúas veces a mesma operación no <strong>TPV del Bar</strong>.`,
  'As aplicacións pasan á <strong>versión 1.2.3 (build 8)</strong> no repositorio, e o <strong>conector de WordPress</strong> publicado en WordPress.org segue na <strong>1.1.12</strong>. As migracións <code>20261114000100</code>, <code>20261115030000</code> e <code>20261115170000</code> <strong>xa se aplicaron</strong> no <strong>servidor compartido</strong> (15 de novembro, 23.11), e a nova do <strong>control de versións</strong> das revisións de WordPress (<code>20261115230000</code>), que daquela aínda non se aplicara, aplicouse o <strong>16 de novembro</strong> pola tarde.',
  ['Mellora · O cartafol de notas do Modo rural compáctase só', `Cando sincronizas o <strong>cartafol de notas</strong> do ${enllacIntern(ENLLAC_MODE_RURAL_R30, '<strong>Modo rural</strong>')}, os ficheiros antigos <strong>sen editar</strong> que este dispositivo confirmou hai <strong>máis de 90 días</strong> consolídanse <strong>sen perder ningún cambio</strong>, e ningunha <strong>nota eliminada</strong> volve. Así, o cartafol xa non garda <strong>para sempre</strong> as versións antigas.`],
  ['Mellora · Un conector de WordPress máis lixeiro e menos débeda por dentro', 'O paquete do <strong>conector de WordPress</strong> que se constrúe desde o repositorio arrinca uns <strong>8 KB máis lixeiro</strong>: a parte das <strong>revisións editoriais</strong> que fala co servidor xa non viaxa no arranque. Por dentro, as clases de estilo sen ningunha regra detrás pasan de <strong>15 a 0</strong> e os accesos directos ao documento, de <strong>5 a 1</strong>; a comprobación dos <strong>tokens de deseño</strong> le tamén as declaracións de varias liñas, a regra para propagar decisións á Wiki di onde pode escribir e, ao pechar unha sesión de traballo, a ferramenta de peche propón un <strong>título con data e hora</strong>.'],
  ['Corrección · Os cartafoles de antes do Caderno de Notas chegan ao servidor', `Os <strong>cartafoles</strong> do ${enllacIntern(ENLLAC_NOTES, '<strong>Caderno de Notas</strong>')} creados antes da corrección da <strong>Onda R29</strong>, que só estaban neste navegador, créanse sós no <strong>servidor</strong> cando entras coa túa <strong>sesión</strong>. Non se borra nin se cambia ningún cartafol deste dispositivo: as notas seguen onde estaban, o Caderno vese igual e, se o servidor <strong>non o confirma</strong>, vólvese tentar a próxima vez que entres.`],
  ['Corrección · A voz xa non le a páxina anterior, e un texto sereno para as mensaxes cifradas', `Se escolles «<strong>Escoitar esta páxina en voz alta</strong>» no menú Traducir e cambias de páxina mentres a voz aínda se carga, xa non se pon a ler a <strong>páxina anterior</strong>. No ${enllacIntern(ENLLAC_XAT_R30, '<strong>Chat</strong>')}, o <strong>cifrado de extremo a extremo</strong> segue <strong>apagado</strong>, e detrás del xa está preparado o texto dunha mensaxe cifrada que este aparello non pode abrir: «Mensaxe cifrada de extremo a extremo noutro dispositivo» cando lle falta a chave, e «Non se puido abrir esta mensaxe cifrada» no resto dos casos, <strong>sen ningún código</strong> técnico e sen deixar a mensaxe <strong>en branco</strong>.`],
  ['Corrección · Dous toques seguidos no TPV del Bar, ficheiros grandes na Gestoria e menos permisos', 'No <strong>TPV del Bar</strong>, dous toques seguidos xa non fan <strong>dúas devolucións</strong> do mesmo tíquet, non anotan dúas veces un <strong>movemento de caixa</strong> nin anulan unidades de máis. Na <strong>Gestoria</strong>, un <strong>extracto do banco</strong> ou un <strong>PDF de factura</strong> con tiras de decenas de miles de caracteres lese en milisegundos, non en segundos. E a app xa non pide <strong>permisos</strong> de biometría nin de contas que non usa nos móbiles onde os declaraba.']]
};

const fitaR30 = (language) => {
 const [titol, obertura, abast, ...apartats] = FITA_R30[language];
 return `${section('h3', titol, obertura, abast)}\n      ${apartats.map(([t, c]) => subSection(t, c)).join('\n      ')}\n\n      `;
};

/* Onada R29 (15-11-2026, tarda) · El teclat del mòbil que no fa pujar la pàgina al Xat ni a Notes i els Ajustos del
   Xat i «Nova conversa» sense teclat en tàctil (07878998f, NAT-01), el reproductor de so que no es mou mentre llig
   (R29-02-09) i que en mode àudio parla d'àudio (R29-02-05), la lectura del menú Traduir que no es perd en canviar de
   veu ni en tocar l'Índex (R29-CV-01, R29-CV-06), l'enllaç «Entra o registra't ara» al xat de mostra
   (DECISIÓ-R29-02.7), les carpetes de Notes al servidor (PF-01; les d'abans es queden al navegador), Disseny, el receptari i el Banc de Llavors sense error per a una fitxa absent (R29-02-1,
   R29-02-1b), la fitxa registral d'El Rentonar a 360 píxels (R29-02-8a), les etiquetes enllaçades en una línia
   (R28-REG-01/02) i dues expressions lineals (SEG-R29-01, SEG-R29-03). Llei 0: la 1.2.2 (build 7) és la del
   repositori, no la de les botigues; el connector publicat continua en la 1.1.12 (1.1.15 al repositori); les
   migracions 20261115170000 i 20261115030000 encara no s'han aplicat al servidor compartit. PF-02 no hi apareix:
   només toca appendChatMessages de l'adaptador Supabase, que cap pantalla no crida; el Xat envia per XatContext →
   enviaMissatge amb un id estable, i això no ha canviat. */
const ENLLAC_XAT_R29 = '/xat';
export const FITA_R29 = {
 ca: ['15 de novembre de 2026, tarda · Onada R29 · El teclat del mòbil al seu lloc, un reproductor de so que no es mou i carpetes del Bloc de Notes que arriben al servidor',
  `L’<strong>Onada R29</strong> de <strong>Sóc de Poble</strong> fa que el <strong>teclat del mòbil</strong> ja no faça pujar la pàgina al ${enllacIntern(ENLLAC_XAT_R29, '<strong>Xat</strong>')} ni al ${enllacIntern(ENLLAC_NOTES, '<strong>Bloc de Notes</strong>')}, que el <strong>reproductor de so</strong> es quede quiet mentre llig i que les teues <strong>carpetes</strong> es creen de veres al servidor.`,
  'Les aplicacions passen a la <strong>versió 1.2.2 (build 7)</strong> al repositori, encara <strong>no publicada a les botigues</strong>, i el <strong>connector de WordPress</strong> publicat a WordPress.org continua en la <strong>1.1.12</strong> (amb la <strong>1.1.15 al repositori</strong>). La migració nova de <strong>quotes, seguretat de files i consens</strong> (<code>20261115170000</code>) és al repositori i <strong>encara no s’ha aplicat</strong> al servidor compartit, i la <code>20261115030000</code> tampoc.',
  ['Novetat · Un enllaç per a entrar des del xat de mostra i un reproductor que parla d’àudio', 'Al <strong>xat de mostra</strong> que veu qui encara no ha entrat, la invitació de la <strong>IAIA</strong> porta ara l’enllaç «<strong>Entra o registra’t ara</strong>», que obri el <strong>registre</strong>. Quan el <strong>reproductor de so</strong> fa sonar un <strong>àudio</strong>, els seus botons i avisos ja no parlen de lectura: diuen, per exemple, «<strong>Pausa l’àudio</strong>».'],
  ['Millora · El teclat del mòbil i el reproductor de so, cadascú al seu lloc', 'Quan escrius al <strong>Xat</strong> o en una <strong>nota</strong> des del mòbil, la pàgina ja no puja davall de la part de dalt de la pantalla, i en una <strong>pantalla tàctil</strong> els Ajustos del Xat i «Nova conversa» ja no obrin el <strong>teclat</strong> tot sols. El <strong>reproductor de so</strong> ja no es mou sota el dit mentre llig, i si escoltes una pàgina des del menú Traduir i <strong>canvies de veu</strong>, «<strong>Aturar la lectura en veu alta</strong>» continua aturant-la; un toc a l’<strong>Índex</strong> ja no la talla.'],
  ['Correcció · Carpetes al servidor, fitxes que no existixen i més seguretat', `Les <strong>carpetes</strong> que crees al Bloc de Notes ara es creen de veres al <strong>servidor</strong>; abans es quedaven al navegador sense avisar, i les creades abans d’ara continuen només en este navegador. Un enllaç a una fitxa que no existix ja no mostra cap <strong>error</strong>: ${enllacIntern(ENLLAC_DISSENY, '<strong>Disseny</strong>')} obri la fitxa general de la categoria, i el receptari i el Banc de Llavors diuen que l’element no és accessible o ja no existix. La fitxa registral d’El Rentonar s’ajusta a pantalles de <strong>360 píxels</strong>, les <strong>etiquetes enllaçades</strong> de les targetes tornen a ocupar una sola línia i el text de les <strong>notes locals</strong> o un concepte llarg a la Gestoria ja no poden alentir l’aplicació.`]],
 es: ['15 de noviembre de 2026, tarde · Oleada R29 · El teclado del móvil en su sitio, un reproductor de sonido que no se mueve y carpetas del Bloc de Notas que llegan al servidor',
  `La <strong>Oleada R29</strong> de <strong>Sóc de Poble</strong> hace que el <strong>teclado del móvil</strong> ya no haga subir la página en el ${enllacIntern(ENLLAC_XAT_R29, '<strong>Chat</strong>')} ni en el ${enllacIntern(ENLLAC_NOTES, '<strong>Bloc de Notas</strong>')}, que el <strong>reproductor de sonido</strong> se quede quieto mientras lee y que tus <strong>carpetas</strong> se creen de verdad en el servidor.`,
  'Las aplicaciones pasan a la <strong>versión 1.2.2 (build 7)</strong> en el repositorio, todavía <strong>no publicada en las tiendas</strong>, y el <strong>conector de WordPress</strong> publicado en WordPress.org sigue en la <strong>1.1.12</strong> (con la <strong>1.1.15 en el repositorio</strong>). La migración nueva de <strong>cuotas, seguridad de filas y consenso</strong> (<code>20261115170000</code>) está en el repositorio y <strong>todavía no se ha aplicado</strong> en el servidor compartido, y la <code>20261115030000</code> tampoco.',
  ['Novedad · Un enlace para entrar desde el chat de muestra y un reproductor que habla de audio', 'En el <strong>chat de muestra</strong> que ve quien todavía no ha entrado, la invitación de la <strong>IAIA</strong> lleva ahora el enlace «<strong>Entra o regístrate ahora</strong>», que abre el <strong>registro</strong>. Cuando el <strong>reproductor de sonido</strong> hace sonar un <strong>audio</strong>, sus botones y avisos ya no hablan de lectura: dicen, por ejemplo, «<strong>Pausar el audio</strong>».'],
  ['Mejora · El teclado del móvil y el reproductor de sonido, cada uno en su sitio', 'Cuando escribes en el <strong>Chat</strong> o en una <strong>nota</strong> desde el móvil, la página ya no sube por debajo de la parte de arriba de la pantalla, y en una <strong>pantalla táctil</strong> los Ajustes del Chat y «Nueva conversación» ya no abren el <strong>teclado</strong> solos. El <strong>reproductor de sonido</strong> ya no se mueve bajo el dedo mientras lee, y si escuchas una página desde el menú Traducir y <strong>cambias de voz</strong>, «<strong>Detener la lectura en voz alta</strong>» sigue deteniéndola; un toque en el <strong>Índice</strong> ya no la corta.'],
  ['Corrección · Carpetas en el servidor, fichas que no existen y más seguridad', `Las <strong>carpetas</strong> que creas en el Bloc de Notas ahora se crean de verdad en el <strong>servidor</strong>; antes se quedaban en el navegador sin avisar, y las creadas antes de ahora siguen solo en este navegador. Un enlace a una ficha que no existe ya no muestra ningún <strong>error</strong>: ${enllacIntern(ENLLAC_DISSENY, '<strong>Diseño</strong>')} abre la ficha general de la categoría, y el recetario y el Banco de Semillas dicen que el elemento no es accesible o ya no existe. La ficha registral de El Rentonar se ajusta a pantallas de <strong>360 píxeles</strong>, las <strong>etiquetas enlazadas</strong> de las tarjetas vuelven a ocupar una sola línea y el texto de las <strong>notas locales</strong> o un concepto largo en la Gestoria ya no pueden ralentizar la aplicación.`]],
 en: ['15 November 2026, afternoon · Wave R29 · The mobile keyboard in its place, a sound player that stays still and Notebook folders that reach the server',
  `<strong>Wave R29</strong> of <strong>Sóc de Poble</strong> stops the <strong>mobile keyboard</strong> from pushing the page up in the ${enllacIntern(ENLLAC_XAT_R29, '<strong>Chat</strong>')} and the ${enllacIntern(ENLLAC_NOTES, '<strong>Notebook</strong>')}, keeps the <strong>sound player</strong> still while it reads and makes your <strong>folders</strong> really get created on the server.`,
  'The applications move to <strong>version 1.2.2 (build 7)</strong> in the repository, <strong>not yet published in the stores</strong>, and the <strong>WordPress plugin</strong> published on WordPress.org stays on <strong>1.1.12</strong> (with <strong>1.1.15 in the repository</strong>). The new <strong>quotas, row security and consensus</strong> migration (<code>20261115170000</code>) is in the repository and <strong>has not yet been applied</strong> on the shared server, and neither has <code>20261115030000</code>.',
  ['New · A sign-in link in the sample chat and a player that talks about audio', 'In the <strong>sample chat</strong> shown to people who have not signed in yet, the invitation from the <strong>IAIA</strong> now carries the link “<strong>Sign in or sign up now</strong>”, which opens the <strong>sign-up page</strong>. When the <strong>sound player</strong> plays an <strong>audio</strong> clip, its buttons and messages no longer talk about reading: they say, for example, “<strong>Pause audio</strong>”.'],
  ['Improvement · The mobile keyboard and the sound player, each in its place', 'When you type in the <strong>Chat</strong> or in a <strong>note</strong> on your phone, the page no longer slides up under the top of the screen, and on a <strong>touch screen</strong> the Chat settings and “New conversation” no longer open the <strong>keyboard</strong> by themselves. The <strong>sound player</strong> no longer moves under your finger while it reads, and if you listen to a page from the Translate menu and <strong>change voice</strong>, “<strong>Stop reading aloud</strong>” still stops it; a tap on the <strong>Index</strong> no longer cuts it off.'],
  ['Fix · Folders on the server, cards that do not exist and more security', `The <strong>folders</strong> you create in the Notebook are now really created on the <strong>server</strong>; before, they stayed in the browser without warning, and the ones created before now are still only in this browser. A link to a card that does not exist no longer shows an <strong>error</strong>: ${enllacIntern(ENLLAC_DISSENY, '<strong>Design</strong>')} opens the general card of the category, and the recipe book and the Seed Bank say that the item is not accessible or no longer exists. El Rentonar’s registry card fits screens of <strong>360 pixels</strong>, the <strong>linked labels</strong> on cards fit on a single line again and the text of <strong>local notes</strong> or a long entry in the Gestoria can no longer slow the app down.`]],
 eu: ['2026ko azaroaren 15a, arratsaldea · R29 olatua · Mugikorreko teklatua bere lekuan, mugitzen ez den soinu-erreproduzigailua eta zerbitzarira iristen diren Koadernoko karpetak',
  `<strong>Sóc de Poble</strong> plataformako <strong>R29 olatuak</strong> lortzen du <strong>mugikorreko teklatuak</strong> orria jada ez igotzea ${enllacIntern(ENLLAC_XAT_R29, '<strong>Txatean</strong>')} eta ${enllacIntern(ENLLAC_NOTES, '<strong>Koadernoan</strong>')}, <strong>soinu-erreproduzigailua</strong> geldi egotea testua irakurtzen ari den bitartean eta zuk sortutako <strong>karpetak</strong> benetan zerbitzarian sortzea.`,
  'Aplikazioak <strong>1.2.2 bertsiora (7. builda)</strong> igarotzen dira biltegian, oraindik <strong>dendetan argitaratu gabe</strong>, eta WordPress.org direktorioan argitaratutako <strong>WordPress konektorea</strong> <strong>1.1.12</strong> da oraindik (biltegian <strong>1.1.15</strong> dagoela). <strong>Kuoten, errenkaden segurtasunaren eta adostasunaren</strong> migrazio berria (<code>20261115170000</code>) biltegian dago eta <strong>oraindik ez da aplikatu</strong> zerbitzari partekatuan, eta <code>20261115030000</code> ere ez.',
  ['Berritasuna · Sartzeko esteka adibide-txatean eta audioaz hitz egiten duen erreproduzigailua', 'Oraindik sartu ez denak ikusten duen <strong>adibide-txatean</strong>, <strong>IAIAren</strong> gonbidapenak «<strong>Sartu edo erregistratu orain</strong>» esteka darama orain, <strong>erregistroa</strong> irekitzen duena. <strong>Soinu-erreproduzigailuak</strong> <strong>audio</strong> bat jotzen duenean, bere botoiek eta oharrek ez dute jada irakurketaz hitz egiten, audioaz baizik: adibidez, «<strong>Eten audioa</strong>» diote.'],
  ['Hobekuntza · Mugikorreko teklatua eta soinu-erreproduzigailua, bakoitza bere lekuan', 'Mugikorretik <strong>Txatean</strong> edo <strong>ohar</strong> batean idazten duzunean, orria ez da jada pantailaren goialdearen azpira igotzen, eta <strong>ukipen-pantailan</strong> Txataren ezarpenek eta «Elkarrizketa berria» aukerak ez dute jada <strong>teklatua</strong> berez irekitzen. <strong>Soinu-erreproduzigailua</strong> ez da jada hatzaren azpian mugitzen irakurtzen ari den bitartean, eta Itzulpena menutik orri bat entzuten ari zarela <strong>ahotsa aldatzen</strong> baduzu, «<strong>Gelditu irakurketa ozena</strong>» aukerak gelditzen du oraindik; <strong>aurkibidean</strong> sakatzeak ez du jada eteten.'],
  ['Zuzenketa · Karpetak zerbitzarian, existitzen ez diren fitxak eta segurtasun handiagoa', `Koadernoan sortzen dituzun <strong>karpetak</strong> benetan sortzen dira orain <strong>zerbitzarian</strong>; lehen nabigatzailean geratzen ziren abisatu gabe, eta lehenago sortutakoak nabigatzaile honetan bakarrik daude oraindik. Existitzen ez den fitxa baterako esteka batek ez du jada <strong>errorerik</strong> erakusten: ${enllacIntern(ENLLAC_DISSENY, '<strong>Diseinua</strong>')} atalak kategoriaren fitxa orokorra irekitzen du, eta errezeta-liburuak eta Hazi Bankuak diote elementua ez dagoela eskuragarri edo jada ez dela existitzen. El Rentonarren erregistro-fitxa <strong>360 pixeleko</strong> pantailetara egokitzen da, txarteletako <strong>esteka duten etiketak</strong> lerro bakarrean daude berriro, eta <strong>tokiko oharren</strong> testuak edo Gestoriako kontzeptu luze batek ezin dute jada aplikazioa moteldu.`]],
 gl: ['15 de novembro de 2026, tarde · Onda R29 · O teclado do móbil no seu sitio, un reprodutor de son que non se move e cartafoles do Caderno de Notas que chegan ao servidor',
  `A <strong>Onda R29</strong> de <strong>Sóc de Poble</strong> fai que o <strong>teclado do móbil</strong> xa non faga subir a páxina no ${enllacIntern(ENLLAC_XAT_R29, '<strong>Chat</strong>')} nin no ${enllacIntern(ENLLAC_NOTES, '<strong>Caderno de Notas</strong>')}, que o <strong>reprodutor de son</strong> quede quieto mentres le e que os teus <strong>cartafoles</strong> se creen de verdade no servidor.`,
  'As aplicacións pasan á <strong>versión 1.2.2 (build 7)</strong> no repositorio, aínda <strong>non publicada nas tendas</strong>, e o <strong>conector de WordPress</strong> publicado en WordPress.org segue na <strong>1.1.12</strong> (coa <strong>1.1.15 no repositorio</strong>). A migración nova de <strong>cotas, seguridade de filas e consenso</strong> (<code>20261115170000</code>) está no repositorio e <strong>aínda non se aplicou</strong> no servidor compartido, e a <code>20261115030000</code> tampouco.',
  ['Novidade · Unha ligazón para entrar desde o chat de mostra e un reprodutor que fala de audio', 'No <strong>chat de mostra</strong> que ve quen aínda non entrou, a invitación da <strong>IAIA</strong> leva agora a ligazón «<strong>Entra ou rexístrate agora</strong>», que abre o <strong>rexistro</strong>. Cando o <strong>reprodutor de son</strong> fai soar un <strong>audio</strong>, os seus botóns e avisos xa non falan de lectura: din, por exemplo, «<strong>Pausar o audio</strong>».'],
  ['Mellora · O teclado do móbil e o reprodutor de son, cada un no seu sitio', 'Cando escribes no <strong>Chat</strong> ou nunha <strong>nota</strong> desde o móbil, a páxina xa non sobe por baixo da parte de arriba da pantalla, e nunha <strong>pantalla táctil</strong> os Axustes do Chat e «Nova conversa» xa non abren o <strong>teclado</strong> sós. O <strong>reprodutor de son</strong> xa non se move baixo o dedo mentres le, e se escoitas unha páxina desde o menú Traducir e <strong>cambias de voz</strong>, «<strong>Deter a lectura en voz alta</strong>» segue deténdoa; un toque no <strong>Índice</strong> xa non a corta.'],
  ['Corrección · Cartafoles no servidor, fichas que non existen e máis seguridade', `Os <strong>cartafoles</strong> que creas no Caderno de Notas agora créanse de verdade no <strong>servidor</strong>; antes quedaban no navegador sen avisar, e os creados antes de agora seguen só neste navegador. Unha ligazón a unha ficha que non existe xa non mostra ningún <strong>erro</strong>: ${enllacIntern(ENLLAC_DISSENY, '<strong>Deseño</strong>')} abre a ficha xeral da categoría, e o receitario e o Banco de Sementes din que o elemento non é accesible ou xa non existe. A ficha rexistral de El Rentonar axústase a pantallas de <strong>360 píxeles</strong>, as <strong>etiquetas ligadas</strong> das tarxetas volven ocupar unha soa liña e o texto das <strong>notas locais</strong> ou un concepto longo na Gestoria xa non poden ralentizar a aplicación.`]]
};

const fitaR29 = (language) => {
 const [titol, obertura, abast, ...apartats] = FITA_R29[language];
 return `${section('h3', titol, obertura, abast)}\n      ${apartats.map(([t, c]) => subSection(t, c)).join('\n      ')}\n\n      `;
};

/* Onada R28 (15-11-2026, matí) · La còpia xifrada del Xat als Ajustos (desar i comprovar, sense restaurar; al navegador,
   no a l'app mòbil), el reproductor de so centrat (IDEA-268), més contrast (dates i etiquetes a 7 a 1 o més), el teclat
   del mòbil que no tapa el camp i «Publicat» com a distintiu d'estat; i a les aplicacions, la 1.2.1 (build 6) al
   repositori, encara no a les botigues. Llei 0: la migració 20261115030000 és al repositori i no s'ha aplicat al
   servidor compartit; el connector publicat continua en la 1.1.12. */
const ENLLAC_XAT_R28 = '/xat';
export const FITA_R28 = {
 ca: ['15 de novembre de 2026, matí · Onada R28 · Una còpia xifrada del Xat, el reproductor de so centrat i més contrast i espai per a escriure al mòbil',
  `L’<strong>Onada R28</strong> de <strong>Sóc de Poble</strong> porta als Ajustos del ${enllacIntern(ENLLAC_XAT_R28, '<strong>Xat</strong>')} una <strong>còpia de seguretat xifrada</strong> que pots desar i comprovar, centra el <strong>reproductor de so</strong> al peu de la pantalla, puja el <strong>contrast</strong> de dates i etiquetes i fa que el <strong>teclat del mòbil</strong> no tape el que escrius.`,
  'Les aplicacions passen a la <strong>versió 1.2.1 (build 6)</strong> al repositori, encara <strong>no publicada a les botigues</strong>, i el <strong>connector de WordPress</strong> publicat a WordPress.org continua en la <strong>1.1.12</strong> (amb la <strong>1.1.15 al repositori</strong>). La migració nova d’<strong>exportació de dades i quotes</strong> (<code>20261115030000</code>) és al repositori i <strong>encara no s’ha aplicat</strong> al servidor compartit.',
  ['Novetat · Una còpia xifrada del Xat als Ajustos, per a desar-la i comprovar-la', `Als Ajustos del ${enllacIntern(ENLLAC_XAT_R28, '<strong>Xat</strong>')}, «<strong>Còpia de seguretat</strong>» desa en un arxiu <code>.sdpbackup</code>, xifrat amb una <strong>contrasenya que tries tu</strong>, les converses i els missatges que este dispositiu ha carregat, <strong>sense fotos, àudios ni vídeos</strong>, i «<strong>Comprova una còpia</strong>» confirma que s’obri sense canviar res. <strong>Restaurar-la</strong> dins de l’app encara <strong>no és possible</strong>, i en les aplicacions mòbils la còpia es fa des del <strong>navegador</strong>.`],
  ['Millora · El reproductor de so, centrat al peu, i més contrast i espai al mòbil', 'La barra del <strong>reproductor de so</strong> queda <strong>centrada al peu</strong> tant al mòbil com a l’ordinador. Les <strong>dates</strong> de la barra taronja i les <strong>etiquetes</strong> de les targetes arriben a un contrast de <strong>7 a 1</strong> o més, les etiquetes llargues s’ajusten a pantalles de 360 píxels i, quan obris el <strong>teclat</strong> al mòbil, la barra inferior s’amaga perquè el camp on escrius quede a la vista. Al Bloc de Notes, «<strong>Publicat</strong>» és ara un <strong>distintiu d’estat</strong> i ja no pareix un botó.'],
  ['Correcció · Textos compartits que no passen d’una sessió a l’altra i una còpia que no amaga claus', 'A les <strong>aplicacions mòbils</strong>, un text compartit cap a l’app abans de <strong>tancar la sessió</strong> ja no pot arribar a la <strong>sessió següent</strong>. La <strong>còpia del Xat</strong> rebutja un bloc de dades massa gran per a revisar-lo, perquè <strong>cap clau privada</strong> hi passe amagada, i la <strong>icona de l’aplicació</strong> s’adapta als <strong>temes de color</strong> del sistema en els mòbils que en tenen.']],
 es: ['15 de noviembre de 2026, mañana · Oleada R28 · Una copia cifrada del Chat, el reproductor de sonido centrado y más contraste y espacio para escribir en el móvil',
  `La <strong>Oleada R28</strong> de <strong>Sóc de Poble</strong> lleva a los Ajustes del ${enllacIntern(ENLLAC_XAT_R28, '<strong>Chat</strong>')} una <strong>copia de seguridad cifrada</strong> que puedes guardar y comprobar, centra el <strong>reproductor de sonido</strong> al pie de la pantalla, sube el <strong>contraste</strong> de fechas y etiquetas y hace que el <strong>teclado del móvil</strong> no tape lo que escribes.`,
  'Las aplicaciones pasan a la <strong>versión 1.2.1 (build 6)</strong> en el repositorio, todavía <strong>no publicada en las tiendas</strong>, y el <strong>conector de WordPress</strong> publicado en WordPress.org sigue en la <strong>1.1.12</strong> (con la <strong>1.1.15 en el repositorio</strong>). La migración nueva de <strong>exportación de datos y cuotas</strong> (<code>20261115030000</code>) está en el repositorio y <strong>todavía no se ha aplicado</strong> en el servidor compartido.',
  ['Novedad · Una copia cifrada del Chat en los Ajustes, para guardarla y comprobarla', `En los Ajustes del ${enllacIntern(ENLLAC_XAT_R28, '<strong>Chat</strong>')}, «<strong>Copia de seguridad</strong>» guarda en un archivo <code>.sdpbackup</code>, cifrado con una <strong>contraseña que eliges tú</strong>, las conversaciones y los mensajes que este dispositivo ha cargado, <strong>sin fotos, audios ni vídeos</strong>, y «<strong>Comprobar una copia</strong>» confirma que se abre sin cambiar nada. <strong>Restaurarla</strong> dentro de la app todavía <strong>no es posible</strong>, y en las aplicaciones móviles la copia se hace desde el <strong>navegador</strong>.`],
  ['Mejora · El reproductor de sonido, centrado al pie, y más contraste y espacio en el móvil', 'La barra del <strong>reproductor de sonido</strong> queda <strong>centrada al pie</strong> tanto en el móvil como en el ordenador. Las <strong>fechas</strong> de la barra naranja y las <strong>etiquetas</strong> de las tarjetas llegan a un contraste de <strong>7 a 1</strong> o más, las etiquetas largas se ajustan a pantallas de 360 píxeles y, cuando abres el <strong>teclado</strong> en el móvil, la barra inferior se oculta para que el campo donde escribes quede a la vista. En el Bloc de Notas, «<strong>Publicado</strong>» es ahora un <strong>distintivo de estado</strong> y ya no parece un botón.'],
  ['Corrección · Textos compartidos que no pasan de una sesión a otra y una copia que no esconde claves', 'En las <strong>aplicaciones móviles</strong>, un texto compartido con la app antes de <strong>cerrar la sesión</strong> ya no puede llegar a la <strong>sesión siguiente</strong>. La <strong>copia del Chat</strong> rechaza un bloque de datos tan grande que no se puede revisar, para que <strong>ninguna clave privada</strong> pase escondida, y el <strong>icono de la aplicación</strong> se adapta a los <strong>temas de color</strong> del sistema en los móviles que los tienen.']],
 en: ['15 November 2026, morning · Wave R28 · An encrypted Chat backup, a centred sound player and more contrast and room to type on mobile',
  `<strong>Wave R28</strong> of <strong>Sóc de Poble</strong> brings to the ${enllacIntern(ENLLAC_XAT_R28, '<strong>Chat</strong>')} settings an <strong>encrypted backup</strong> you can save and check, centres the <strong>sound player</strong> at the bottom of the screen, raises the <strong>contrast</strong> of dates and labels and keeps the <strong>mobile keyboard</strong> from covering what you type.`,
  'The applications move to <strong>version 1.2.1 (build 6)</strong> in the repository, <strong>not yet published in the stores</strong>, and the <strong>WordPress plugin</strong> published on WordPress.org stays on <strong>1.1.12</strong> (with <strong>1.1.15 in the repository</strong>). The new <strong>data export and quotas</strong> migration (<code>20261115030000</code>) is in the repository and <strong>has not yet been applied</strong> on the shared server.',
  ['New · An encrypted Chat backup in the settings, to save and to check', `In the ${enllacIntern(ENLLAC_XAT_R28, '<strong>Chat</strong>')} settings, “<strong>Chat backup</strong>” saves the conversations and messages this device has loaded, <strong>without photos, voice notes or videos</strong>, to a <code>.sdpbackup</code> file encrypted with a <strong>password you choose</strong>, and “<strong>Check a backup</strong>” confirms it opens without changing anything. <strong>Restoring it</strong> inside the app is <strong>not possible yet</strong>, and in the mobile apps the backup is made from the <strong>browser</strong>.`],
  ['Improvement · The sound player, centred at the bottom, and more contrast and room on mobile', 'The <strong>sound player</strong> bar sits <strong>centred at the bottom</strong> on both mobile and desktop. The <strong>dates</strong> on the orange bar and the <strong>labels</strong> on cards reach a contrast of <strong>7 to 1</strong> or more, long labels wrap on 360-pixel screens and, when you open the <strong>keyboard</strong> on mobile, the bottom bar hides so the field you are typing in stays in view. In the Notebook, “<strong>Published</strong>” is now a <strong>status badge</strong> and no longer looks like a button.'],
  ['Fix · Shared text that does not cross from one session to the next, and a backup that hides no keys', 'In the <strong>mobile apps</strong>, text shared to the app before <strong>signing out</strong> can no longer reach the <strong>next session</strong>. The <strong>Chat backup</strong> rejects a block of data too large to inspect, so that <strong>no private key</strong> slips through hidden, and the <strong>app icon</strong> adapts to the system <strong>colour themes</strong> on phones that have them.']],
 eu: ['2026ko azaroaren 15a, goiza · R28 olatua · Txataren kopia zifratua, soinu-erreproduzigailua erdian eta kontraste eta idazteko leku gehiago mugikorrean',
  `<strong>Sóc de Poble</strong> plataformako <strong>R28 olatuak</strong> ${enllacIntern(ENLLAC_XAT_R28, '<strong>Txataren</strong>')} ezarpenetara <strong>segurtasun-kopia zifratu</strong> bat dakar, gorde eta egiazta dezakezuna; gainera, <strong>soinu-erreproduzigailua</strong> pantailaren behealdean erdiratzen du, data eta etiketen <strong>kontrastea</strong> igotzen du eta <strong>mugikorreko teklatuak</strong> idazten duzuna ez estaltzea lortzen du.`,
  'Aplikazioak <strong>1.2.1 bertsiora (6. builda)</strong> igarotzen dira biltegian, oraindik <strong>dendetan argitaratu gabe</strong>, eta WordPress.org direktorioan argitaratutako <strong>WordPress konektorea</strong> <strong>1.1.12</strong> da oraindik (biltegian <strong>1.1.15</strong> dagoela). <strong>Datuak esportatzeko eta kuotetarako</strong> migrazio berria (<code>20261115030000</code>) biltegian dago eta <strong>oraindik ez da aplikatu</strong> zerbitzari partekatuan.',
  ['Berritasuna · Txataren kopia zifratua ezarpenetan, gordetzeko eta egiaztatzeko', `${enllacIntern(ENLLAC_XAT_R28, '<strong>Txataren</strong>')} ezarpenetan, «<strong>Babeskopia</strong>» aukerak <code>.sdpbackup</code> fitxategi batean gordetzen ditu gailu honek kargatu dituen elkarrizketak eta mezuak, <strong>zuk aukeratutako pasahitz</strong> batekin zifratuta eta <strong>argazki, audio eta bideorik gabe</strong>, eta «<strong>Egiaztatu kopia bat</strong>» aukerak ezer aldatu gabe irekitzen dela baieztatzen du. Aplikazioaren barruan <strong>leheneratzea</strong> <strong>ez da posible oraindik</strong>, eta aplikazio mugikorretan kopia <strong>nabigatzailetik</strong> egiten da.`],
  ['Hobekuntza · Soinu-erreproduzigailua behealdean erdian, eta kontraste eta leku gehiago mugikorrean', '<strong>Soinu-erreproduzigailuaren</strong> barra <strong>behealdean erdian</strong> geratzen da, bai mugikorrean bai ordenagailuan. Barra laranjako <strong>datek</strong> eta txarteletako <strong>etiketek</strong> <strong>7 eta 1</strong>eko kontrastea edo handiagoa dute, etiketa luzeak 360 pixeleko pantailetara egokitzen dira eta, mugikorrean <strong>teklatua</strong> irekitzean, beheko barra ezkutatzen da idazten ari zaren eremua bistan gera dadin. Koadernoan, «<strong>Argitaratua</strong>» <strong>egoera-ikur</strong> bat da orain, eta jada ez du botoi itxurarik.'],
  ['Zuzenketa · Saio batetik hurrengora igarotzen ez diren testu partekatuak eta gakorik ezkutatzen ez duen kopia', '<strong>Aplikazio mugikorretan</strong>, <strong>saioa itxi</strong> aurretik aplikaziora partekatutako testu batek ezin du jada <strong>hurrengo saiora</strong> iritsi. <strong>Txataren kopiak</strong> berrikusteko handiegia den datu-bloke bat baztertzen du, <strong>gako pribaturik</strong> ezkutuan sar ez dadin, eta <strong>aplikazioaren ikonoa</strong> sistemaren <strong>kolore-gaietara</strong> egokitzen da gaiak dituzten mugikorretan.']],
 gl: ['15 de novembro de 2026, mañá · Onda R28 · Unha copia cifrada do Chat, o reprodutor de son centrado e máis contraste e espazo para escribir no móbil',
  `A <strong>Onda R28</strong> de <strong>Sóc de Poble</strong> leva aos Axustes do ${enllacIntern(ENLLAC_XAT_R28, '<strong>Chat</strong>')} unha <strong>copia de seguridade cifrada</strong> que podes gardar e comprobar, centra o <strong>reprodutor de son</strong> ao pé da pantalla, sobe o <strong>contraste</strong> de datas e etiquetas e fai que o <strong>teclado do móbil</strong> non tape o que escribes.`,
  'As aplicacións pasan á <strong>versión 1.2.1 (build 6)</strong> no repositorio, aínda <strong>non publicada nas tendas</strong>, e o <strong>conector de WordPress</strong> publicado en WordPress.org segue na <strong>1.1.12</strong> (coa <strong>1.1.15 no repositorio</strong>). A migración nova de <strong>exportación de datos e cotas</strong> (<code>20261115030000</code>) está no repositorio e <strong>aínda non se aplicou</strong> no servidor compartido.',
  ['Novidade · Unha copia cifrada do Chat nos Axustes, para gardala e comprobala', `Nos Axustes do ${enllacIntern(ENLLAC_XAT_R28, '<strong>Chat</strong>')}, «<strong>Copia de seguridade</strong>» garda nun ficheiro <code>.sdpbackup</code>, cifrado cun <strong>contrasinal que escolles ti</strong>, as conversas e as mensaxes que este dispositivo cargou, <strong>sen fotos, audios nin vídeos</strong>, e «<strong>Comprobar unha copia</strong>» confirma que se abre sen cambiar nada. <strong>Restaurala</strong> dentro da app aínda <strong>non é posible</strong>, e nas aplicacións móbiles a copia faise dende o <strong>navegador</strong>.`],
  ['Mellora · O reprodutor de son, centrado ao pé, e máis contraste e espazo no móbil', 'A barra do <strong>reprodutor de son</strong> queda <strong>centrada ao pé</strong> tanto no móbil coma no ordenador. As <strong>datas</strong> da barra laranxa e as <strong>etiquetas</strong> das tarxetas chegan a un contraste de <strong>7 a 1</strong> ou máis, as etiquetas longas axústanse a pantallas de 360 píxeles e, cando abres o <strong>teclado</strong> no móbil, a barra inferior ocúltase para que o campo onde escribes quede á vista. No Caderno de Notas, «<strong>Publicado</strong>» é agora un <strong>distintivo de estado</strong> e xa non parece un botón.'],
  ['Corrección · Textos compartidos que non pasan dunha sesión a outra e unha copia que non agocha chaves', 'Nas <strong>aplicacións móbiles</strong>, un texto compartido cara á app antes de <strong>pechar a sesión</strong> xa non pode chegar á <strong>sesión seguinte</strong>. A <strong>copia do Chat</strong> rexeita un bloque de datos tan grande que non se pode revisar, para que <strong>ningunha chave privada</strong> pase agochada, e a <strong>icona da aplicación</strong> adáptase aos <strong>temas de cor</strong> do sistema nos móbiles que os teñen.']]
};

const fitaR28 = (language) => {
 const [titol, obertura, abast, ...apartats] = FITA_R28[language];
 return `${section('h3', titol, obertura, abast)}\n      ${apartats.map(([t, c]) => subSection(t, c)).join('\n      ')}\n\n      `;
};

/* Onades R26 i R27 (15-11-2026, matinada) · L'article «El Farcellet Digital» al Mur (full de ruta en quatre capes i
   simulador didàctic que no copia res), l'edició avançada en un desplegable i l'avís d'esborrany privat al Bloc de
   Notes, el selector d'opcions de Disseny, i l'enduriment de xarxa de les aplicacions, del connector i del motor de
   còpia del Xat. Llei 0: el motor de còpia no té cap botó per al veïnat; les aplicacions continuen en la 1.2.0 i la
   configuració nova és la del repositori; les cinc comprovacions SQL són les de la captura del Mestre (261114_2339). */
const ENLLAC_FARCELLET = '/mur/copies-de-seguretat-soc-de-poble';
export const FITA_R26 = {
 ca: ['15 de novembre de 2026, matinada · Onades R26 i R27 · El Farcellet Digital al Mur, una edició més clara al Bloc de Notes i més seguretat a les aplicacions i al connector',
  `Les <strong>Onades R26 i R27</strong> de <strong>Sóc de Poble</strong> publiquen al Mur l’article ${enllacIntern(ENLLAC_FARCELLET, '<strong>«El Farcellet Digital»</strong>')}, que explica com dissenyem les <strong>còpies de seguretat</strong>, aclarixen l’edició al ${enllacIntern(ENLLAC_NOTES, '<strong>Bloc de Notes</strong>')} i reforcen la <strong>seguretat</strong> de les aplicacions i del <strong>connector de WordPress</strong>.`,
  'Les aplicacions continuen en la <strong>versió 1.2.0</strong> i el <strong>connector de WordPress</strong> publicat a WordPress.org és la <strong>1.1.12</strong> (amb la <strong>1.1.15 al repositori</strong>). Les <strong>cinc comprovacions SQL</strong> del servidor compartit (refranyer, consens comarcal <code>20261114023000</code>, límits d’octets <code>20261114171500</code>, rebuts del xat i una funció d’administració tancada al públic) ja donen <strong>resultat cert</strong>; el <strong>resum comarcal</strong> del joc continua apagat mentre es decidix com mostrar-lo.',
  ['Novetat · «El Farcellet Digital», l’article de les còpies de seguretat amb un simulador didàctic', `L’article ${enllacIntern(ENLLAC_FARCELLET, '<strong>«El Farcellet Digital»</strong>')} explica en <strong>cinc llengües</strong> el <strong>full de ruta en quatre capes</strong> per a converses, notes, publicacions i fotos, amb un <strong>simulador didàctic</strong> que no fa cap còpia ni envia cap dada. El <strong>motor de còpia portàtil</strong> ja existix i està provat per al <strong>Xat</strong>, però encara <strong>no té cap botó</strong> per al veïnat.`],
  ['Millora · Edició avançada en un desplegable, avís d’esborrany privat i botons que respiren', `Al ${enllacIntern(ENLLAC_NOTES, '<strong>Bloc de Notes</strong>')}, les eines d’<strong>edició avançada</strong> s’agrupen en un <strong>desplegable</strong>, el grup de <strong>publicació</strong> no s’encongix en pantalles estretes i una nota en <strong>esborrany privat</strong> avisa quin àmbit cal triar abans de publicar-la. El nou <strong>selector d’opcions</strong> de ${enllacIntern(ENLLAC_DISSENY, '<strong>Disseny</strong>')} i els <strong>botons grans</strong>, amb 32 píxels de marge lateral, es lligen millor al mòbil.`],
  ['Correcció · Connexions xifrades a les aplicacions, secrets protegits al connector i un motor de còpia sense credencials', 'La configuració de les <strong>aplicacions mòbils</strong> del repositori només admet <strong>connexions xifrades</strong> i certificats del sistema, i el web demana <strong>HTTPS durant un any</strong> al domini principal. El <strong>connector de WordPress</strong> del repositori guarda les claus d’API com a <strong>secrets protegits</strong> i comprova el permís de lectura de cada contingut, i el <strong>motor de còpia</strong> descarta <strong>claus privades i credencials</strong>.']],
 es: ['15 de noviembre de 2026, madrugada · Oleadas R26 y R27 · El Hatillo Digital en el Mur, una edición más clara en el Bloc de Notas y más seguridad en las aplicaciones y el conector',
  `Las <strong>Oleadas R26 y R27</strong> de <strong>Sóc de Poble</strong> publican en el Mur el artículo ${enllacIntern(ENLLAC_FARCELLET, '<strong>«El Hatillo Digital»</strong>')}, que explica cómo diseñamos las <strong>copias de seguridad</strong>, aclaran la edición en el ${enllacIntern(ENLLAC_NOTES, '<strong>Bloc de Notas</strong>')} y refuerzan la <strong>seguridad</strong> de las aplicaciones y del <strong>conector de WordPress</strong>.`,
  'Las aplicaciones siguen en la <strong>versión 1.2.0</strong> y el <strong>conector de WordPress</strong> publicado en WordPress.org es la <strong>1.1.12</strong> (con la <strong>1.1.15 en el repositorio</strong>). Las <strong>cinco comprobaciones SQL</strong> del servidor compartido (refranero, consenso comarcal <code>20261114023000</code>, límites de octetos <code>20261114171500</code>, recibos del chat y una función de administración cerrada al público) ya dan <strong>resultado cierto</strong>; el <strong>resumen comarcal</strong> del juego sigue apagado mientras se decide cómo mostrarlo.',
  ['Novedad · «El Hatillo Digital», el artículo de las copias de seguridad con un simulador didáctico', `El artículo ${enllacIntern(ENLLAC_FARCELLET, '<strong>«El Hatillo Digital»</strong>')} explica en <strong>cinco lenguas</strong> la <strong>hoja de ruta en cuatro capas</strong> para conversaciones, notas, publicaciones y fotos, con un <strong>simulador didáctico</strong> que no hace ninguna copia ni envía ningún dato. El <strong>motor de copia portátil</strong> ya existe y está probado para el <strong>Chat</strong>, pero todavía <strong>no tiene ningún botón</strong> para el vecindario.`],
  ['Mejora · Edición avanzada en un desplegable, aviso de borrador privado y botones que respiran', `En el ${enllacIntern(ENLLAC_NOTES, '<strong>Bloc de Notas</strong>')}, las herramientas de <strong>edición avanzada</strong> se agrupan en un <strong>desplegable</strong>, el grupo de <strong>publicación</strong> no se encoge en pantallas estrechas y una nota en <strong>borrador privado</strong> avisa de qué ámbito hay que elegir antes de publicarla. El nuevo <strong>selector de opciones</strong> de ${enllacIntern(ENLLAC_DISSENY, '<strong>Diseño</strong>')} y los <strong>botones grandes</strong>, con 32 píxeles de margen lateral, se leen mejor en el móvil.`],
  ['Corrección · Conexiones cifradas en las aplicaciones, secretos protegidos en el conector y un motor de copia sin credenciales', 'La configuración de las <strong>aplicaciones móviles</strong> del repositorio solo admite <strong>conexiones cifradas</strong> y certificados del sistema, y la web exige <strong>HTTPS durante un año</strong> en el dominio principal. El <strong>conector de WordPress</strong> del repositorio guarda las claves de API como <strong>secretos protegidos</strong> y comprueba el permiso de lectura de cada contenido, y el <strong>motor de copia</strong> descarta <strong>claves privadas y credenciales</strong>.']],
 en: ['15 November 2026, early morning · Waves R26 and R27 · The Digital Bundle on the Mur, clearer editing in the Notebook and stronger security in the apps and the plugin',
  `<strong>Waves R26 and R27</strong> of <strong>Sóc de Poble</strong> publish on the Mur the article ${enllacIntern(ENLLAC_FARCELLET, '<strong>“The Digital Bundle”</strong>')}, which explains how we are designing <strong>backups</strong>, make editing clearer in the ${enllacIntern(ENLLAC_NOTES, '<strong>Notebook</strong>')} and strengthen the <strong>security</strong> of the apps and the <strong>WordPress plugin</strong>.`,
  'The applications stay on <strong>version 1.2.0</strong> and the <strong>WordPress plugin</strong> published on WordPress.org is <strong>1.1.12</strong> (with <strong>1.1.15 in the repository</strong>). The <strong>five SQL checks</strong> on the shared server (proverb book, regional consensus <code>20261114023000</code>, byte limits <code>20261114171500</code>, chat receipts and an admin function closed to the public) already return <strong>true</strong>; the game’s <strong>regional summary</strong> stays switched off while we decide how to show it.',
  ['New · “The Digital Bundle”, the backup article with a teaching simulator', `The article ${enllacIntern(ENLLAC_FARCELLET, '<strong>“The Digital Bundle”</strong>')} explains in <strong>five languages</strong> the <strong>four-layer roadmap</strong> for conversations, notes, posts and photos, with a <strong>teaching simulator</strong> that makes no copy and sends no data. The <strong>portable backup engine</strong> already exists and is tested for the <strong>Chat</strong>, but it still has <strong>no button</strong> for residents.`],
  ['Improvement · Advanced editing in a drop-down, a private-draft reminder and buttons with room to breathe', `In the ${enllacIntern(ENLLAC_NOTES, '<strong>Notebook</strong>')}, the <strong>advanced editing</strong> tools are grouped in a <strong>drop-down</strong>, the <strong>publishing</strong> group no longer shrinks on narrow screens and a note in <strong>private draft</strong> tells you which scope to choose before publishing it. The new <strong>options selector</strong> in ${enllacIntern(ENLLAC_DISSENY, '<strong>Design</strong>')} and the <strong>large buttons</strong>, with 32 pixels of side padding, read better on mobile.`],
  ['Fix · Encrypted connections in the apps, protected secrets in the plugin and a backup engine without credentials', 'The repository’s configuration for the <strong>mobile apps</strong> only allows <strong>encrypted connections</strong> and system certificates, and the website requires <strong>HTTPS for one year</strong> on the main domain. The repository’s <strong>WordPress plugin</strong> stores API keys as <strong>protected secrets</strong> and checks the read permission of each item, and the <strong>backup engine</strong> discards <strong>private keys and credentials</strong>.']],
 eu: ['2026ko azaroaren 15a, goizaldea · R26 eta R27 olatuak · Fardeltxo Digitala Murrean, edizio argiagoa Koadernotik-en eta segurtasun handiagoa aplikazioetan eta konektorean',
  `<strong>Sóc de Poble</strong> plataformako <strong>R26 eta R27 olatuek</strong> ${enllacIntern(ENLLAC_FARCELLET, '<strong>«Fardeltxo Digitala»</strong>')} artikulua argitaratzen dute Murrean, <strong>segurtasun-kopiak</strong> nola diseinatzen ari garen azaltzeko; gainera, ${enllacIntern(ENLLAC_NOTES, '<strong>Koadernotik</strong>')} aplikazioko edizioa argitzen dute eta aplikazioen eta <strong>WordPress konektorearen</strong> <strong>segurtasuna</strong> indartzen dute.`,
  'Aplikazioek <strong>1.2.0 bertsioan</strong> jarraitzen dute eta WordPress.org direktorioan argitaratutako <strong>WordPress konektorea</strong> <strong>1.1.12</strong> da (biltegian <strong>1.1.15</strong> dagoela). Zerbitzari partekatuko <strong>bost SQL egiaztapenek</strong> (esaera zaharrak, eskualdeko adostasuna <code>20261114023000</code>, byte-mugak <code>20261114171500</code>, txateko agiriak eta publikoarentzat itxitako administrazio-funtzio bat) <strong>emaitza egiazkoa</strong> ematen dute; jokoaren <strong>eskualdeko laburpena</strong> itzalita dago oraindik, nola erakutsi erabaki arte.',
  ['Berritasuna · «Fardeltxo Digitala», segurtasun-kopien artikulua simulagailu didaktiko batekin', `${enllacIntern(ENLLAC_FARCELLET, '<strong>«Fardeltxo Digitala»</strong>')} artikuluak <strong>bost hizkuntzatan</strong> azaltzen du elkarrizketa, ohar, argitalpen eta argazkietarako <strong>lau geruzako ibilbide-orria</strong>, eta <strong>simulagailu didaktiko</strong> bat dakar, kopiarik egiten ez duena eta daturik bidaltzen ez duena. <strong>Kopia-motor eramangarria</strong> badago eta <strong>Txaterako</strong> probatuta dago, baina oraindik <strong>ez du botoirik</strong> bizilagunentzat.`],
  ['Hobekuntza · Edizio aurreratua zabalgarri batean, zirriborro pribatuaren oharra eta arnasa duten botoiak', `${enllacIntern(ENLLAC_NOTES, '<strong>Koadernotik</strong>')} aplikazioan, <strong>edizio aurreratuko</strong> tresnak <strong>zabalgarri</strong> batean biltzen dira, <strong>argitalpen-taldea</strong> ez da txikitzen pantaila estuetan, eta <strong>zirriborro pribatuan</strong> dagoen ohar batek argitaratu aurretik zein eremu aukeratu behar den gogorarazten du. ${enllacIntern(ENLLAC_DISSENY, '<strong>Diseinua</strong>')} ataleko <strong>aukera-hautatzaile</strong> berria eta <strong>botoi handiak</strong>, alboetan 32 pixeleko tartearekin, hobeto irakurtzen dira mugikorrean.`],
  ['Zuzenketa · Konexio zifratuak aplikazioetan, sekretu babestuak konektorean eta kredentzialik gabeko kopia-motorra', 'Biltegiko <strong>aplikazio mugikorren</strong> konfigurazioak <strong>konexio zifratuak</strong> eta sistemaren ziurtagiriak soilik onartzen ditu, eta webguneak <strong>urtebetez HTTPS</strong> eskatzen du domeinu nagusian. Biltegiko <strong>WordPress konektoreak</strong> APIaren gakoak <strong>sekretu babestu</strong> gisa gordetzen ditu eta eduki bakoitzaren irakurtzeko baimena egiaztatzen du, eta <strong>kopia-motorrak</strong> <strong>gako pribatuak eta kredentzialak</strong> baztertzen ditu.']],
 gl: ['15 de novembro de 2026, madrugada · Ondas R26 e R27 · O Fardelo Dixital no Mur, unha edición máis clara no Caderno de Notas e máis seguridade nas aplicacións e no conector',
  `As <strong>Ondas R26 e R27</strong> de <strong>Sóc de Poble</strong> publican no Mur o artigo ${enllacIntern(ENLLAC_FARCELLET, '<strong>«O Fardelo Dixital»</strong>')}, que explica como deseñamos as <strong>copias de seguridade</strong>, aclaran a edición no ${enllacIntern(ENLLAC_NOTES, '<strong>Caderno de Notas</strong>')} e reforzan a <strong>seguridade</strong> das aplicacións e do <strong>conector de WordPress</strong>.`,
  'As aplicacións seguen na <strong>versión 1.2.0</strong> e o <strong>conector de WordPress</strong> publicado en WordPress.org é a <strong>1.1.12</strong> (coa <strong>1.1.15 no repositorio</strong>). As <strong>cinco comprobacións SQL</strong> do servidor compartido (refraneiro, consenso comarcal <code>20261114023000</code>, límites de octetos <code>20261114171500</code>, recibos do chat e unha función de administración pechada ao público) xa dan <strong>resultado certo</strong>; o <strong>resumo comarcal</strong> do xogo segue apagado mentres se decide como mostralo.',
  ['Novidade · «O Fardelo Dixital», o artigo das copias de seguridade cun simulador didáctico', `O artigo ${enllacIntern(ENLLAC_FARCELLET, '<strong>«O Fardelo Dixital»</strong>')} explica en <strong>cinco linguas</strong> a <strong>folla de ruta en catro capas</strong> para conversas, notas, publicacións e fotos, cun <strong>simulador didáctico</strong> que non fai ningunha copia nin envía ningún dato. O <strong>motor de copia portátil</strong> xa existe e está probado para o <strong>Chat</strong>, pero aínda <strong>non ten ningún botón</strong> para a veciñanza.`],
  ['Mellora · Edición avanzada nun despregable, aviso de borrador privado e botóns que respiran', `No ${enllacIntern(ENLLAC_NOTES, '<strong>Caderno de Notas</strong>')}, as ferramentas de <strong>edición avanzada</strong> agrúpanse nun <strong>despregable</strong>, o grupo de <strong>publicación</strong> non se encolle en pantallas estreitas e unha nota en <strong>borrador privado</strong> avisa de que ámbito hai que escoller antes de publicala. O novo <strong>selector de opcións</strong> de ${enllacIntern(ENLLAC_DISSENY, '<strong>Deseño</strong>')} e os <strong>botóns grandes</strong>, con 32 píxeles de marxe lateral, lense mellor no móbil.`],
  ['Corrección · Conexións cifradas nas aplicacións, segredos protexidos no conector e un motor de copia sen credenciais', 'A configuración das <strong>aplicacións móbiles</strong> do repositorio só admite <strong>conexións cifradas</strong> e certificados do sistema, e a web esixe <strong>HTTPS durante un ano</strong> no dominio principal. O <strong>conector de WordPress</strong> do repositorio garda as chaves de API como <strong>segredos protexidos</strong> e comproba o permiso de lectura de cada contido, e o <strong>motor de copia</strong> descarta <strong>chaves privadas e credenciais</strong>.']]
};

const fitaR26 = (language) => {
 const [titol, obertura, abast, ...apartats] = FITA_R26[language];
 return `${section('h3', titol, obertura, abast)}\n      ${apartats.map(([t, c]) => subSection(t, c)).join('\n      ')}\n\n      `;
};


