export const CRONICA_FUNDACIONAL_VERSIONS_HTML = "\n      <h3>3 de novembre de 2026 · v1.1.0 (build pendent de desplegar) · Connector WordPress v1.1.12 a WordPress.org</h3>\n      <p>La <strong>versió 1.1.0</strong> recull la feina dels últims dies: l'<strong>app d'iPhone i iPad</strong> enviada a <strong>revisió a l'App Store</strong>, el bloc <strong>«On es publica?»</strong> dins de l'editor, les subtargetes i unes pàgines que es lligen d'un colp d'ull. El codi web i la configuració de les apps passen a la 1.1.0, i el <strong>número de build</strong> de les apps, el 2, <strong>no canvia</strong>. Tot <strong>està pendent de desplegar</strong>. El build del web portarà la <strong>data del desplegament</strong>.</p>\n      <p>Les entregues del <strong>29 d'octubre</strong> a l'<strong>1 de novembre</strong> portaven totes el número <strong>v1.0.0</strong>. La numeració <strong>v1.0.1–v1.0.4</strong> se'ls dona ara, <strong>en retrospectiva</strong>, perquè l'historial mostre l'<strong>evolució</strong>.</p>\n      <h4>Novetat · L'app d'iPhone i iPad, a revisió</h4>\n      <p>La <strong>versió 1.0</strong> de l'<strong>app d'iPhone i iPad</strong> s'ha <strong>enviat a revisió</strong> a l'App Store: a App Store Connect, el Mestre l'ha vista en l'estat <strong>«Waiting for Review»</strong>. Les <strong>captures per a la fitxa</strong> s'han fet <strong>en mode app</strong>, a la mida exacta de <strong>1290 × 2796</strong> i <strong>2048 × 2732</strong> píxels.</p>\n      <h4>Novetat · L'app per a Android, a revisió a Google Play</h4>\n      <p>A <strong>Google Play</strong>, la <strong>versió 2 (1.0.0)</strong> és <strong>«En revisió»</strong>, segons el que el Mestre ha vist a la consola, i l'<strong>APK signat</strong> 1.0.0 (build 2) ja és <strong>compilat</strong>. La <strong>descàrrega directa</strong> encara <strong>no és oberta</strong>.</p>\n      <h4>Novetat · «On es publica?» dins de l'editor</h4>\n      <p>Al Bloc de Notes, el bloc <strong>«On es publica?»</strong> viu <strong>en línia</strong> dins de l'<strong>«Edició avançada»</strong>, sense cap finestra modal, en este ordre: capçalera, logotip, «On es publica?» i classificació. Hi tries <strong>on va la nota</strong> (Mur, Mercat, Compartir cotxe, Treball o Habitatge), n'omplis la <strong>fitxa</strong> i en veus la <strong>targeta pública</strong>. Una adreça amb <code>?ambit=</code> l'obri amb l'<strong>àmbit triat</strong>, i el catàleg el mostra a <a href=\"/disseny?categoria=formularis&amp;item=formularis-ambit\">Disseny › Formularis</a>.</p>\n      <h4>Novetat · Subtargetes</h4>\n      <p>La <strong>subtargeta</strong> és una <strong>targeta interna</strong> amb títol, línia de context i cos, dins del text d'una pàgina o d'una nota. A l'editor s'inserix amb el <strong>botó de la segona fila</strong> de la barra o amb l'<strong>ordre «/»</strong>, i ja n'hi ha a <a href=\"/projecte\">Projecte</a>, <a href=\"/descarregues\">Descàrregues</a> i <a href=\"/page/fediversity\">Fediversity</a>. El títol pren el <strong>nivell del context</strong>, i la <strong>traducció</strong> de la pàgina <strong>conserva les caixes</strong>.</p>\n      <h4>Novetat · Dades obertes enllaçades, també dins de WordPress</h4>\n      <p>La pàgina <a href=\"/page/fediversity\">Fediversity</a> enllaça recursos del <strong>paquet públic</strong> de La Torre. El <strong>manifest descriu els recursos</strong> i les empremtes del <strong>format 1.2.0</strong>. La captura contrastada porta una notícia, un acte històric, tres entitats i una memòria documental; no cap fitxa oral revisada. A <a href=\"/control?fitxa=opendata\">Control</a> ja hi ha <strong>comprovació i previsualització</strong> amb SHA de confiança i <strong>restauració local</strong>. A WordPress, els enllaços conserven la <strong>base del paquet</strong>. La capacitat de restaurar a Supabase <strong>continua absent</strong>.</p>\n      <h4>Novetat · Pilot Node 0, vídeos pesants, 2n Aplec i Oli de La Torre</h4>\n      <p>La pàgina <a href=\"/page/node-zero\">Node 0 · Mac mini M4</a> explica l'arquitectura del <strong>servidor físic local</strong> de La Torre de les Maçanes i com allotja <strong>vídeos pesants per streaming HTTP 206</strong> i manifest signat, s'incorpora l'esdeveniment dels <strong>Cursos de pedra en sec</strong> de Fageca i Alcosser i la crònica del <strong>2n Aplec pel Territori</strong>, i el catàleg reunix els <strong>set formats d'Oli de La Torre</strong> amb la seua <strong>fitxa nutricional</strong>.</p>\n      <h4>Millora · Capacitat del Traductor Sobirà</h4>\n      <p>El <strong>Traductor Sobirà</strong> amplia el límit per pàgina fins a <strong>vint-i-quatre lots</strong> i <strong>60.000 caràcters</strong> per a traduir <strong>articles i cròniques llargues</strong> sense tallar el text, amb un topall diari de <strong>100.000 caràcters per lloc</strong> i d'<strong>1.000.000 al servidor</strong>.</p>\n      <h4>Millora · Calaixos davall de la barra negra</h4>\n      <p>El calaix <strong>«Amb qui actues?»</strong>, el <strong>Crom del sistema</strong> i el <strong>menú compacte</strong> s'obrin ara <strong>davall de la barra negra</strong>, com ja feia l'<strong>Índex</strong>, i en prenen <strong>la resta de la pantalla</strong>; la barra, amb la zona segura de dalt del mòbil, es queda <strong>a la vista</strong>.</p>\n      <h4>Millora · Pàgines que es lligen d'un colp d'ull</h4>\n      <p>Esta pàgina i les <strong>pàgines del sistema</strong>, <strong>llevat de Legal</strong>, passen les <strong>llistes de punts</strong> llargues a <strong>subtítols</strong> seguits de paràgrafs, i cada paràgraf llarg porta de <strong>sis a huit negretes</strong>. Llegint només els <strong>títols i les negretes</strong>, s'ha d'entendre <strong>què diu cada frase</strong>.</p>\n      <h4>Millora · Actualitzacions automàtiques a gentdelatorre.net</h4>\n      <p>El Mestre ha activat el <strong>3 de novembre</strong> les <strong>actualitzacions automàtiques</strong> de WordPress.org a <strong>gentdelatorre.net</strong>, perquè el node reba tot sol cada <strong>versió nova</strong> del connector. El <strong>connector 1.1.12</strong> ja està <strong>publicat a WordPress.org</strong>, amb <strong>trunk i etiqueta oficial</strong> i els <strong>assets de la fitxa</strong> actualitzats.</p>\n      <h4>Millora · Proves i enllaços</h4>\n      <p>La matinada del <strong>3 de novembre</strong>, la suite de Vitest va executar <strong>31.458 proves</strong> en <strong>1.765 fitxers</strong>, <strong>totes en verd</strong>. El <strong>certificador d'enllaços</strong> comprova també que cada <code>?item=</code> de la Wiki porte a un <strong>ítem que existix</strong>.</p>\n\n      <h3>1 de novembre de 2026, tarda · v1.0.4 (build pendent de desplegar) · Connector WordPress v1.1.11 al repositori</h3>\n      <p>L'<strong>assalt</strong> a les <strong>quinze dimensions</strong> del projecte, fet a la tarda de l'1 de novembre. Tot és al repositori i <strong>està pendent de desplegar</strong>; les <strong>dues migracions</strong> noves estan <strong>pendents d'aplicar</strong> i el <strong>xifratge</strong> d'extrem a extrem continua <strong>apagat</strong>. El build portarà la <strong>data del desplegament</strong>.</p>\n      <h4>Novetat · Segon adaptador complet del port neutral</h4>\n      <p><code>src/data/local/</code> <strong>respon en memòria</strong> a tot el <strong>contracte de dades</strong>, llevat de la <strong>versió mínima</strong> de l'app, que només té sentit amb un servidor (els serveis que un node sense servidor no té, com l'entrada amb compte o el xifratge, <strong>els rebutja</strong> amb el codi que prescriu el contracte), i passa el mateix <strong>kit de conformitat</strong> que l'adaptador de Supabase. Demostra que les dades del poble es poden endollar a un <strong>altre servidor</strong> sense tocar cap pantalla. <strong>Cap pantalla de producció</strong> no el fa servir.</p>\n      <h4>Novetat · Dades obertes 1.2.0 i restaurador</h4>\n      <p>El <strong>paquet del poble</strong> ja pot portar, a més del directori, les <strong>notícies</strong> i els actes de l'<strong>agenda</strong> públics que signa una entitat del poble, i la <strong>memòria oral</strong> en OKF hi té el seu lloc (<code>data/okf/</code>), encara que el servidor no en guarda <strong>cap fitxa</strong>. Un <strong>restaurador nou</strong> comprova cada <strong>SHA-256</strong> del manifest, rebutja els fitxers alterats, absents, sobrers o amb camins fora del paquet, i torna a carregar el poble sense duplicar res en un adaptador que ho admeta: hui, <strong>només el local</strong>.</p>\n      <h4>Novetat · Federació, segona fase (biblioteca)</h4>\n      <p><code>src/data/federacio/inboxActivityPub.js</code> verifica <strong>signatures HTTP</strong> (rsa-sha256, hs2019 i ed25519), respon un <strong>Follow</strong> amb un <strong>Accept</strong> i només admet <strong>alertes municipals</strong> de <strong>nodes de confiança</strong>. Encara <strong>no s'ha desplegat</strong> cap <strong>bústia d'entrada</strong>: hui ningú no pot seguir ni escriure a Sóc de Poble <strong>des del Fedivers</strong>.</p>\n      <h4>Novetat · Nodes germans amb veu pròpia</h4>\n      <p>El <strong>generador de federació</strong> ja publica el poble de cada <strong>node germà</strong> amb el seu actor, el seu <strong>WebFinger</strong>, la seua bústia de sortida i el seu <strong>NodeInfo 2.1</strong>, i la bústia de sortida de <strong>La Torre</strong> porta la <strong>pàgina pública</strong> del poble. L'instal·lador ho farà amb la <strong>pròxima versió confirmada</strong> del codi.</p>\n      <h4>Novetat · Fitxa de memòria oral</h4>\n      <p>En revisar-la, es poden afegir <strong>etiquetes pròpies</strong> (<strong>fins a cinc</strong>) i <strong>triar el poble</strong> pel seu <strong>nom popular</strong> o <strong>en castellà</strong> (Jijona, Torremanzanas, la Torre…).</p>\n      <h4>Novetat · App per al mòbil (pròxima compilació)</h4>\n      <p>Si el servidor demana una <strong>versió més nova</strong>, l'app <strong>ho diu</strong> i oferix l'enllaç per a <strong>actualitzar-la</strong> i el <strong>camí de la web</strong>; mentre la migració no s'aplique, l'app <strong>entra sempre</strong>. A l'iPhone, el botó <strong>«Continua amb Apple»</strong> només ix quan la compilació el <strong>porta encés</strong>.</p>\n      <h4>Millora · Arrencada més lleugera</h4>\n      <p>El <strong>fitxer d'entrada</strong> passa d'<strong>1,47 MB</strong> (407 kB comprimits) a <strong>640 kB</strong> (224 kB comprimits), i <strong>el build para</strong> si torna a passar de <strong>250 kB</strong> comprimits. L'arrencada sencera <strong>baixa un 3,5 %</strong> i el JavaScript total <strong>creix un 3,4 %</strong>, perquè React, els estils, DOMPurify i el valencià van ara en <strong>peces pròpies</strong>.</p>\n      <h4>Millora · Service worker</h4>\n      <p>Guarda fins a <strong>600 recursos</strong> i <strong>16 MiB</strong>, i <strong>mai no esborra</strong> els de l'<strong>última closca confirmada</strong> de les apps, perquè continuen obrint-se <strong>sense xarxa</strong> després d'un desplegament.</p>\n      <h4>Millora · Alertes municipals</h4>\n      <p>Cada avís del Mur diu fins quan és <strong>vigent</strong> i, quan <strong>caduca</strong>, ix de l'avís <strong>sense recarregar</strong> la pàgina. Quan s'aplique la <strong>migració nova</strong>, un ajuntament <strong>només podrà signar</strong> publicacions del <strong>seu poble</strong>.</p>\n      <h4>Millora · Cinc llengües a Connectar, Membres i l'enquadrament d'imatges</h4>\n      <p>Unes <strong>250 frases</strong> que només eren en valencià <strong>ja es traduïxen</strong> al <strong>castellà</strong>, l'anglés, el basc i el gallec. La <strong>revisió</strong> per <strong>persones natives</strong> del basc i del gallec <strong>continua pendent</strong>.</p>\n      <h4>Millora · Captures al xat</h4>\n      <p>Les <strong>captures de pantalla</strong> s'envien amb <strong>2048 píxels</strong> de costat perquè el text es puga llegir; les fotos continuen a <strong>1200</strong>.</p>\n      <h4>Millora · Bloc de Notes</h4>\n      <p>La Card <strong>«Bloc de notes»</strong>, la de la mà amb la ploma, és <strong>sempre la primera</strong> de «Tot», amb <strong>qualsevol ordenació</strong>.</p>\n      <h4>Millora · Xifratge d'extrem a extrem (apagat)</h4>\n      <p>La comprovació del <strong>número de seguretat</strong> de cada conversa i el bloc <strong>«Persones de confiança»</strong> de «Privacitat i dades» estan <strong>preparats</strong> darrere de la <strong>bandera</strong>, que <strong>continua apagada</strong>. <strong>Cap conversa</strong> no es xifra encara.</p>\n      <h4>Millora · Edat mínima</h4>\n      <p>Les condicions diuen <strong>16 anys</strong>, <strong>sense excepcions</strong>, a la web i a les apps.</p>\n      <h4>Millora · Connector WordPress 1.1.11</h4>\n      <p>És <strong>al repositori</strong>, amb el visor d'esta entrega, i està <strong>pendent de publicar</strong> a WordPress.org.</p>\n      <h4>Millora · IAIA sense xarxa</h4>\n      <p>Quan <strong>no troba</strong> la resposta a la Wiki, la <strong>IAIA MarIA</strong> pot explicar <strong>setze temes</strong> de <strong>cultura rural</strong> i d'ús veïnal (la pedra seca, la pilota, un receptari, com convocar una reunió o avisar d'un objecte perdut) <strong>sense connexió</strong>, i diu que <strong>no publica</strong> ni envia res <strong>en nom teu</strong>.</p>\n      <h4>Millora · Camps de formulari</h4>\n      <p>Els <strong>textos d'exemple</strong> dels camps tenen ara un <strong>contrast de 7:1</strong> o més en tema <strong>clar i fosc</strong>.</p>\n      <h4>Millora · Exportació de les teues dades (pendent d'aplicar)</h4>\n      <p><strong>Queda preparat</strong> el contracte de les <strong>dades de federació</strong>; quan <strong>s'aplique la migració</strong>, només hi anirà <strong>el que és teu</strong>, i si una part no es pot exportar, <strong>ho dirà</strong> sense deixar de donar-te <strong>la resta</strong>.</p>\n      <h4>Correcció · Focus a «Privacitat i dades»</h4>\n      <p>Després d'acceptar, retirar o cancel·lar, el <strong>focus del teclat</strong> ja <strong>no es perd</strong>: va al <strong>missatge</strong> que diu què ha passat o, si <strong>l'acció falla</strong>, a <strong>l'error</strong>.</p>\n      <h4>Correcció · Columna de navegació a 1024 píxels</h4>\n      <p>Els noms de les <strong>carpetes</strong> salten de línia <strong>sencers</strong> en lloc de tallar-se amb <strong>punts suspensius</strong>.</p>\n      <h4>Correcció · Mur, Notes i Xat sense identitat</h4>\n      <p>Si es munten sense el <strong>proveïdor d'identitat</strong> (per exemple, en una recàrrega en calent), ja <strong>no tomben</strong> l'aplicació: queden en <strong>només lectura</strong>.</p>\n\n      <h3>1 de novembre de 2026 · v1.0.3 (build pendent de desplegar) · Connector WordPress v1.1.10</h3>\n      <p>El <strong>connector oficial</strong> de Sóc de Poble ja és <strong>públic a WordPress.org</strong>. La resta d'esta entrega és al repositori i <strong>està pendent de desplegar</strong>: les <strong>alertes municipals</strong> al Mur, la <strong>fitxa de memòria oral</strong> al Bloc de Notes, l'<strong>agenda en iCalendar</strong> a l'Open Data i els canvis de davall. El build portarà la <strong>data del desplegament</strong>.</p>\n      <h4>Novetat · Connector a WordPress.org (<a href=\"https://wordpress.org/plugins/socdepoble/\" target=\"_blank\" rel=\"noopener noreferrer\">wordpress.org/plugins/socdepoble</a>)</h4>\n      <p>El <strong>connector</strong> <code>socdepoble</code>, en la versió 1.1.10, és al <strong>directori oficial</strong> de WordPress.org. La pàgina de <a href=\"/descarregues\">Descàrregues</a> <strong>n'enllaça la fitxa</strong> i explica com <strong>encastar l'aplicació</strong> amb el <strong>codi curt</strong> i la <strong>plantilla</strong> «Sóc de Poble · full screen».</p>\n      <h4>Novetat · Alertes municipals al Mur</h4>\n      <p>Quan un <strong>ajuntament signa</strong> una publicació amb l'etiqueta <strong>«Alerta»</strong>, «Emergència» o «Bàndol urgent», la targeta porta el <strong>distintiu</strong> «Alerta municipal» o «Bàndol urgent» i, fins a <strong>72 hores</strong> després de la seua data, puja al <strong>capdamunt del Mur</strong> amb un avís que la nomena, amb un contrast d'almenys <strong>7:1</strong> en tema clar i fosc. La mateixa etiqueta posada per <strong>un veí</strong> no fa <strong>cap alerta</strong>.</p>\n      <h4>Novetat · Fitxa de memòria oral (OKF v0.2) al Bloc de Notes</h4>\n      <p><strong>«Proposa Card»</strong> llig el <strong>relat oral</strong> transcrit en una nota i en proposa una fitxa en <strong>Open Knowledge Format</strong> v0.2: el títol, una descripció, un resum fet només amb frases del relat, les etiquetes d'un <strong>vocabulari rural tancat</strong> i el poble esmentat. Tot es fa dins del navegador, <strong>sense xarxa</strong> ni <strong>models de llenguatge</strong>. La fitxa naix com a <strong>esborrany</strong> i es descarrega en Markdown; només una <strong>persona amb sessió</strong> la pot marcar com a revisada, després de corregir-ne, si cal, les etiquetes i el poble.</p>\n      <h4>Novetat · Agenda en iCalendar a l'Open Data (format 1.1.0)</h4>\n      <p>El paquet de <strong>dades obertes</strong> per municipi afig <code>agenda.ics</code> (<strong>iCalendar</strong>, RFC 5545) amb els actes que tenen <strong>data d'inici</strong>, per a importar-los a <strong>qualsevol calendari</strong>, i la data de fi d'un acte de dies sencers és el seu <strong>últim dia</strong>, com a schema.org. En esta entrega, la fitxa del poble encara <strong>només hi exportava</strong> el <strong>directori d'entitats</strong>; la lectura pública de les notícies i de l'agenda arriba amb el <strong>format 1.2.0</strong>, en una entrega posterior.</p>\n      <h4>Millora · Candidatura NGI Fediversity verificable (<a href=\"/page/fediversity\">/page/fediversity</a>)</h4>\n      <p>Cada <strong>partida</strong> separa el <strong>«Fet hui (verificable)»</strong> del <strong>«Pendent»</strong>, i un apartat final enllaça les <strong>comprovacions en viu</strong>: la fitxa de WordPress.org, el node <strong>gentdelatorre.net</strong> i els <strong>documents de federació</strong> (NodeInfo, actors, bústies de sortida i host-meta). El que el <strong>codi no fa</strong> es queda a «Pendent».</p>\n      <h4>Millora · Bloc de Notes</h4>\n      <p>La <strong>Card tutorial</strong> «Bloc de notes», la de la mà amb la ploma, torna a ser dins de «Tot» i és la <strong>vista inicial</strong>, també amb sessió. Una nota nova mostra una <strong>guia d'estructura</strong> mentre el cos és buit, i la guia <strong>no es desa</strong>. El <strong>desplegable d'encapçalaments</strong> ordena H3, H4, H5, H6 i H2; el <strong>subratllat ix</strong> de la barra i de la drecera Ctrl/Cmd+U (es conserven la negreta i la cursiva), i el <strong>botó «⋯»</strong> (Més eines) obri una <strong>segona fila</strong> amb el ratllat, la citació, el divisor i les eines que no caben a la primera.</p>\n      <h4>Millora · Volums locals a Multimèdia (<a href=\"/multimedia\">/multimedia</a>)</h4>\n      <p><strong>«Volums i carpetes locals»</strong>, amb <strong>«Vincular carpeta local»</strong>, passa a la <strong>columna de navegació</strong>, davall de les vistes: <strong>una sola barra</strong> per a tot l'Arxiu, des de <strong>qualsevol vista</strong>. En <strong>pantalles estretes</strong>, on la columna es plega, <strong>cal desplegar-la</strong> per a vore-la.</p>\n      <h4>Millora · Miniatura de l'avatar al Xat</h4>\n      <p>Les <strong>cares del Xat</strong> pinten la foto de perfil de <strong>Javi Llinares</strong> amb una <strong>miniatura</strong> de <strong>256 × 256 píxels</strong> (17 KB en JPEG i 14 KB en WebP) en lloc de la de <strong>1.200 píxels</strong> (<strong>252 KB</strong>). La fitxa i el perfil continuen amb la <strong>foto gran</strong>.</p>\n      <h4>Correcció · Noms accessibles en la llengua de la interfície</h4>\n      <p>Els botons de la <strong>barra blava</strong> (Tornar arrere, Índex de secció, Tornar endavant, Traduir, Comentar i Compartir), la regió <strong>«Autoria i data»</strong>, el <strong>calaix de l'Índex</strong>, les <strong>llistes de categories</strong> de la capçalera i de les targetes i el botó de <strong>pantalla completa</strong> es llegien <strong>sempre en valencià</strong>. Ara els <strong>lectors de pantalla</strong> els diuen en la <strong>llengua triada</strong>: valencià, castellà, anglés, basc o gallec.</p>\n      <h4>Correcció · Títols de l'Open Data</h4>\n      <p>El <strong>títol del paquet</strong> i el de la seua memòria <strong>contrauen i apostrofen</strong> el <strong>nom del poble</strong> (<strong>«Dades obertes d'Alcoi»</strong>, «del Campello», «dels Poblets»): abans deien <strong>«de Alcoi»</strong> i «de El Campello».</p>\n\n      <h3>31 d'octubre de 2026 · v1.0.2 (build 261101) · Connector WordPress v1.1.10</h3>\n      <p>Entrega de les <strong>Rondes 1, 2 i 3</strong> del 31 d'octubre, publicada a <strong>socdepoble.org</strong> la matinada de l'1 de novembre: la <strong>Consola pública</strong>, el tauler del <strong>comptador de visites</strong>, la primera <strong>federació de només lectura</strong>, el paquet de <strong>dades obertes</strong> del poble i <strong>correccions de fons</strong>.</p>\n      <h4>Novetat · Consola pública (<a href=\"/consola\">/consola</a>)</h4>\n      <p>S'obri <strong>sense compte</strong> ni rol. A la <strong>web publicada</strong>, cada pàgina llig la <strong>instantània sanejada</strong> que es fa en cada publicació i diu <strong>de quan és</strong>; si una <strong>font</strong> no hi ha arribat, la Consola <strong>no n'inventa</strong> cap dada.</p>\n      <h4>Novetat · Tauler del comptador de visites (<a href=\"/legal\">/legal</a>)</h4>\n      <p>La pàgina <strong>«Legal i privacitat»</strong> mostra les <strong>xifres públiques</strong> del comptador de les últimes <strong>24 hores</strong>, <strong>sense cap iframe</strong>, i el navegador les demana <strong>sense galetes</strong> ni <strong>referent</strong>.</p>\n      <h4>Novetat · Federació de només lectura</h4>\n      <p>socdepoble.org publica <strong>documents estàtics</strong> d'<strong>ActivityPub</strong>, NodeInfo 2.1 i <strong>WebFinger</strong> per a Sóc de Poble i La Torre de les Maçanes. Els <strong>pobles de mostra</strong> <strong>no es poden descobrir</strong>, i seguir o respondre des del Fedivers <strong>encara està pendent</strong>.</p>\n      <h4>Novetat · Dades obertes del poble</h4>\n      <p>A la web, des de la <strong>fitxa de cada poble</strong> es pot <strong>descarregar</strong> el seu paquet de <strong>dades obertes</strong>. <strong>En esta entrega</strong>, el paquet portava el <strong>directori públic</strong> d'entitats; les notícies, l'agenda i la memòria cultural encara <strong>no s'hi exportaven</strong>.</p>\n      <h4>Millora · Telemetria més clara</h4>\n      <p>El <strong>tauler de privacitat</strong> diu de <strong>cada intent</strong> si està <strong>pendent de resposta</strong> del comptador, si el comptador <strong>ha respost bé</strong> o si <strong>no se sap</strong> si ha arribat. El registre final <strong>no es pot comprovar</strong> des del <strong>navegador</strong>.</p>\n      <h4>Millora · Fletxes del teclat a les graelles de targetes</h4>\n      <p>A <strong>Pobles</strong>, al <strong>Mur</strong> i a la <strong>Consola</strong>, les <strong>fletxes</strong> passen d'una targeta a l'altra i <strong>salten els avisos</strong> i les <strong>targetes ocultes</strong> o desactivades.</p>\n      <h4>Millora · Perfil públic en cinc llengües</h4>\n      <p>Els textos de la <strong>fitxa pública</strong> que encara eixien <strong>sempre en valencià</strong> ixen ara en la <strong>llengua triada</strong>: valencià, castellà, anglés, basc o gallec.</p>\n      <h4>Millora · Atles de la IAIA</h4>\n      <p>Respon també sobre l'<strong>oli</strong> i l'oliva, l'<strong>horta</strong> i les tomaques i les <strong>festes</strong> i l'agenda, entén més <strong>paraules de camp</strong> dites <strong>en castellà</strong> i porta a la <strong>Cerca</strong>, al <strong>Calendari</strong>, a les Traduccions i al teu perfil.</p>\n      <h4>Correcció · Fitxers del núvol</h4>\n      <p><strong>Cada crida</strong> a l'<strong>emmagatzematge</strong> (pujar, baixar, signar un enllaç, llistar o retirar un fitxer) té un <strong>termini</strong> que compta <strong>des que arranca</strong>, i l'espera a la <strong>cua</strong> també té <strong>sostre</strong>: <strong>cap crida</strong> no es queda esperant per sempre.</p>\n      <h4>Correcció · Llistes</h4>\n      <p>Les <strong>graelles</strong>, les barres del calendari i de l'<strong>histograma</strong> i els <strong>missatges del Xat</strong> ja <strong>no sumen</strong> el <strong>marge</strong> de cada element de llista al <strong>buit</strong> que ja els separa, i totes les barres d'un quadre, <strong>també l'última</strong>, partixen de la <strong>mateixa base</strong>.</p>\n      <h4>Correcció · Fitxa d'empreses, entitats i ajuntaments</h4>\n      <p>El selector de visibilitat ja <strong>no oferix «Fitxa privada»</strong>, perquè són <strong>figures públiques</strong> del directori; els <strong>grups conserven</strong> la tria.</p>\n\n      <h3>29 d'octubre de 2026 · v1.0.1 (build 261029) · Connector WordPress v1.1.10</h3>\n      <p>Entrega de <strong>tancament d'auditoria</strong> que deixa preparat, <strong>encara apagat</strong>, el <strong>xifratge d'extrem a extrem</strong> del Xat, l'<strong>empaquetat oficial</strong> del connector per a <strong>WordPress.org</strong> i l'alineació de les <strong>portes de qualitat</strong> i accessibilitat.</p>\n      <h4>Novetat · Xat xifrat d'extrem a extrem (E2EE · Fase 4)</h4>\n      <p>La implementació <code>sdp-xat-v1</code> està <strong>preparada</strong> darrere d'una <strong>bandera apagada</strong> (<code>E2EE_ACTIU_PER_DEFECTE = false</code>), <strong>pendent d'activació</strong>: el <strong>sobre criptogràfic</strong> <code>SDPH</code> (corba P-256, HKDF-SHA-256 i AES-256-GCM) per a les <strong>converses privades</strong>, la verificació visual de <strong>números de seguretat</strong> (12 grups de 5 dígits) i la recuperació social de clau mitjançant <strong>esquemes de Shamir</strong> (3 de 3, 4 o 5 persones de confiança). Fins que s'active, les converses privades <strong>no fan servir</strong> este xifratge.</p>\n      <h4>Novetat · Registre viu de versions</h4>\n      <p><strong>Renovació</strong> d'aquesta pàgina amb l'estructura de <strong>Novetats</strong>, <strong>Millorat</strong> i <strong>Corregit</strong>, pensada perquè tant el <strong>veïnat</strong> com els <strong>agents d'intel·ligència artificial</strong> puguen seguir l'evolució del sistema <strong>sense soroll</strong>.</p>\n      <h4>Novetat · Governança documental v3.11.0</h4>\n      <p>Actualització de les <strong>plantilles operatives</strong> amb la <strong>matriu d'exclusivitat</strong> de carrils per al <strong>treball simultani</strong> d'agents i la <strong>guia gràfica</strong> d'estil <strong>còmic valencià</strong> a sang (<code>v2.0.0</code>).</p>\n      <h4>Millora · Connector WordPress v1.1.10</h4>\n      <p>Paquet <code>socdepoble.zip</code> llest per al <strong>repositori oficial</strong> de WordPress.org i per a la comunitat de <strong>Gent de La Torre</strong>, amb <strong>guia de compatibilitat</strong> davant sistemes agressius de <strong>memòria cau</strong> (SiteGround Speed Optimizer), <strong>internacionalització</strong> i <strong>desinstal·lació neta</strong>.</p>\n      <h4>Millora · Contrast cromàtic AAA (&#35;0e662e)</h4>\n      <p>Ajust del <strong>verd institucional</strong> en tema <strong>clar i fosc</strong> fins a assolir una ràtio de contrast de <strong>7.09:1</strong>, garantint una <strong>lectura nítida</strong> al <strong>sol directe</strong> (Mode Bancal).</p>\n      <h4>Millora · Targetes socials OpenGraph (1200 × 630)</h4>\n      <p>Generació i prerenderitzat d'<strong>imatges de previsualització</strong> per a les <strong>seccions públiques</strong> i documents de la Wiki en <strong>compartir enllaços</strong>.</p>\n      <h4>Correcció · Portes immunitàries i bateria de verificació</h4>\n      <p>Resolució dels <strong>avisos de frontera</strong> en scripts d'arrel, validació de <strong>polítiques RLS</strong> sobre <strong>taules SQL</strong> i consolidació de més de <strong>24.400 proves unitàries</strong> i <strong>1.430 proves d'infraestructura</strong>.</p>\n      <h4>Correcció · Aïllament d'entorns mòbils</h4>\n      <p>Depuració automàtica de <strong>mencions creuades</strong> entre plataformes en les <strong>compilacions natives</strong> per a complir les <strong>directrius de revisió</strong> de les botigues oficials.</p>\n\n      <h3>26 d'octubre de 2026 · v1.0.0 (build 261026) · Connector WordPress v1.1.9</h3>\n      <p>Obertura del <strong>canal d'aplicacions</strong> per a dispositius mòbils, estandardització de la <strong>identitat ciutadana per municipi</strong> i publicació completa del <strong>catàleg de components</strong>.</p>\n      <h4>Novetat · Pàgina de Descàrregues i Aplicacions (<a href=\"/descarregues\">/descarregues</a>)</h4>\n      <p><strong>Guia directa</strong> per a instal·lar l'<strong>aplicació web</strong> des de <strong>qualsevol navegador</strong> d'escriptori o mòbil i <strong>seguiment transparent</strong> de l'estat de les <strong>proves internes</strong> en dispositius mòbils i tauletes.</p>\n      <h4>Novetat · Identitat canònica (@usuari i poble)</h4>\n      <p>Model <strong>unificat</strong> d'alta i perfil amb <strong>identificador únic</strong> <code>@usuari</code>, selector oficial de <strong>municipis</strong> i <strong>La Torre de les Maçanes</strong> com a <strong>poble pilot</strong> de referència.</p>\n      <h4>Novetat · Catàleg interactiu Pedra Seca (<a href=\"/disseny\">/disseny</a>)</h4>\n      <p>Obertura de l'<strong>aparador viu</strong> amb les <strong>157 peces</strong> del sistema de disseny (àtoms, molècules, organismes i composicions) documentades i provades en <strong>temps real</strong>.</p>\n      <h4>Millora · Bústia d'avisos i connexions al Xat</h4>\n      <p>Lectura integrada de les pàgines i <strong>fitxes connectades</strong> a la <strong>columna dreta</strong> del Xat i separació clara dels <strong>avisos del sistema</strong>.</p>\n      <h4>Millora · Optimització visual WebP i Arxiu Multimèdia</h4>\n      <p><strong>Compressió automàtica</strong> d'imatges amb bessones <code>.webp</code> d'alta eficiència conservant l'<strong>original intacte</strong> i el <strong>cens complet</strong> a l'Arxiu Visual (<a href=\"/multimedia\">/multimedia</a>).</p>\n      <h4>Correcció · Rutes d'accés i barreres d'error</h4>\n      <p><strong>Unificació</strong> de totes les <strong>adreces d'entrada</strong> (<code>/login</code>, <code>/accedir</code>, <code>/entrar</code>, <code>/registre</code> i <code>/registra</code>) i <strong>reinici net</strong> de les <strong>barreres de seguretat</strong> de React en <strong>canviar de pantalla</strong>.</p>\n\n      <h3>17 d'octubre de 2026 · v0.9.5 · El Llibre d'Or i la Plataforma d'Apps</h3>\n      <p>Consolidació de la <strong>memòria episòdica verificada</strong> del projecte, llançament de l'arquitectura de <strong>mòduls enxufables</strong> i obertura dels <strong>taulers d'inspecció</strong> tècnica.</p>\n      <h4>Novetat · El Llibre d'Or de Sóc de Poble</h4>\n      <p>Destil·lació i <strong>contrast adversarial</strong> en 34 lots dels <strong>617 documents</strong> de l'arxiu històric per a preservar les decisions arquitectòniques i evitar l'<strong>amnèsia tècnica</strong>.</p>\n      <h4>Novetat · Plataforma d'Apps Enxufables (<a href=\"/app\">/app</a>)</h4>\n      <p>Motor de càrrega <strong>sota demanda</strong> per a les eines comunitàries i professionals (<strong>Gestoria</strong>, <strong>El Bar</strong>, <strong>La Nevera</strong>, <strong>Salut</strong> i <strong>El Lector</strong>) amb frontera de <strong>seguretat pròpia</strong>.</p>\n      <h4>Novetat · Consola Termodinàmica i El Cervell (<a href=\"/consola\">/consola</a>)</h4>\n      <p><strong>Tauler de diagnòstic</strong> amb <strong>nou vistes</strong> d'estat i <strong>explorador interactiu</strong> del graf de peces del sistema.</p>\n      <h4>Novetat · Pàgina de Drets d'autor (<a href=\"/page/drets-autor\">/page/drets-autor</a>)</h4>\n      <p>Explicació en <strong>llenguatge planer</strong> de la <strong>llicència lliure</strong> del codi (<code>AGPL-3.0</code>), la llicència <strong>per defecte</strong> del contingut (<code>CC BY-NC-SA 4.0</code>) i l'<strong>atribució</strong> de la <strong>Viquipèdia</strong> i <strong>Wikimedia Commons</strong>.</p>\n\n      <h3>Crònica fundacional (2013 – setembre de 2026)</h3>\n      <p>Abans d'adoptar la <strong>numeració semàntica</strong> actual (<code>v1.0.0</code>), Sóc de Poble <strong>es va forjar</strong> a través de <strong>vint-i-cinc iteracions</strong> fundacionals que van definir l'<strong>arquitectura</strong> i l'<strong>ètica</strong> del projecte:</p>\n\n      <h4>2 de setembre de 2026 · V25.0025: Bloc de Notes i Ajustos del Sistema</h4>\n      <p>S'introdueix el model de <strong>Bloc de Notes privat i asíncron</strong>. Es poleixen les <strong>targetes de la Constitució</strong>, s'unifica l'etiquetatge amb la <strong>insígnia «Sistema»</strong> i s'ajusten els <strong>espaiats de lectura</strong> complint els manaments del <strong>Trellat</strong>.</p>\n\n      <h4>26 d'agost de 2026 · V25: Transparència Absoluta (Cinquena Auditoria Global)</h4>\n      <p>Obertura del <strong>cervell documental</strong> del projecte a la <strong>Wiki de Poble</strong>, mostrant l'<strong>enciclopèdia d'arquitectura</strong>, les <strong>regles de govern</strong> i la configuració de la IAIA MarIA per assolir la màxima <strong>transparència ètica</strong> i tècnica.</p>\n\n      <h4>21 d'agost de 2026 · V24: La Gran Destil·lació (Disseny Pedra Seca)</h4>\n      <p><strong>Reescriptura</strong> de la interfície sota la llei de la <strong>Pedra Seca</strong>: <strong>HTML5 semàntic pur</strong>, <strong>variables de disseny</strong> pròpies (<code>--sdp-</code>), <strong>tipografia generosa</strong> per a la gent gran i eliminació de <strong>dependències d'estils</strong> efímeres.</p>\n\n      <h4>Juliol de 2026 · V20: Consolidació de l'App Instal·lable (PWA)</h4>\n      <p><strong>Tancament</strong> de l'arquitectura <em>AppShell</em> perquè el portal funcione com una <strong>aplicació web progressiva instal·lable</strong> al mòbil i a l'ordinador <strong>sense dependre d'intermediaris</strong>.</p>\n\n      <h4>Juliol de 2026 · V18: L'Aliança Online-First (ADR-2026-08)</h4>\n      <p><strong>Decisió pragmàtica</strong> d'arquitectura per a utilitzar <strong>Supabase i l'amfitrió Sollutia</strong> com a pont de sincronització en <strong>temps real</strong>, prioritzant l'<strong>estabilitat immediata</strong> per als pobles mentre es prepara l'<strong>horitzó descentralitzat</strong>.</p>\n\n      <h4>Juny de 2026 · V15: El Despertar de la IAIA MarIA i la Guàrdia de Nit</h4>\n      <p>Naix la <strong>identitat</strong> de la <strong>IAIA MarIA</strong> com a <strong>assistent valenciana</strong> propera i protectora, regulada pels <strong>principis del Trellat</strong> i acompanyada pels primers sistemes de <strong>destil·lació de memòria</strong>.</p>\n\n      <h4>Juny de 2026 · V12: L'Era de la Forja i l'Ecosistema React</h4>\n      <p><strong>Reconstrucció completa</strong> del nucli sobre <strong>React</strong> per a donar vida al <strong>Xat interactiu</strong>, el <strong>Mur de Poble</strong> i el <strong>Mercat d'intercanvi</strong> veïnal sota l'escrutini del Consell d'agents.</p>\n\n      <h4>Gener – Juny de 2026 · V8: L'Arquitectura de la Vella Wiki</h4>\n      <p>Etapa d'<strong>experimentació i prototipatge</strong> on van nàixer les llavors de <strong>quatre pilars</strong> que hui formen part de l'<strong>ADN del sistema</strong>: la <strong>Gestoria</strong>, simplificació de formularis i tràmits per al veïnat i les associacions; la <strong>Llibreria i El Lector</strong>, catalogació i lectura accessible per a la comunitat; els <strong>Tràmits agraris</strong>, assistència documental per al camp i la cooperativa, i la <strong>Consola Termodinàmica</strong>, tauler de control per a vigilar la salut del codi i el consum de recursos.</p>\n\n      <h4>2018 · V2: L'Abandonament dels CMS Tradicionals</h4>\n      <p>Decisió d'<strong>abandonar</strong> els <strong>gestors clàssics</strong> carregats de <strong>complements comercials</strong> per a construir una <strong>infraestructura lleugera</strong>, lliure de <strong>rastrejadors publicitaris</strong> i pensada per a <strong>durar dècades</strong>.</p>\n\n      <h4>2013 – 2018 · V1: Els Fonaments i el Manifest del Portal de Pobles Connectats</h4>\n      <p>L'<strong>origen conceptual</strong> a <em>socdepoble.net</em> i a <strong>La Torre de les Maçanes</strong>: la <strong>llavor ciutadana</strong> per a connectar els pobles, preservar el <strong>patrimoni oral</strong> i defensar la <strong>sobirania tecnològica</strong> rural.</p>\n      <img src=\"/assets/uploads/brain/nano_versions_ibanez_v1_1_10.webp\" alt=\"Il·lustració de còmic d'estil Bruguera i Ibáñez on la IAIA MarIA i dos apanyadors amb boina i faixa roja claven al mur de pedra seca el rètol de fusta Versions v1.1.10 amb les tauletes Novetats, Millorat i Corregit\" />\n";

const LLENGUES_VERSIONS = new Set(['ca', 'es', 'en', 'eu', 'gl']);

/**
 * Retorna l'HTML històric complet de /versions (des de R32.33 fins a la crònica
 * fundacional 2013–2026) en la llengua indicada ('ca', 'es', 'en', 'eu', 'gl').
 */
export function obteHtmlHistoricVersions(language = 'ca') {
  const codi = String(language || 'ca').toLowerCase().split('-')[0];
  const lang = LLENGUES_VERSIONS.has(codi) ? codi : 'ca';
  const d = DOSSIER_VERSIONS_R10[lang];
  const entry = section('h3', `${d.date} · ${d.version}`, d.prod, d.db, d.bridge, d.kit, d.todo);
  const fitesAnteriors = `${fitaR32_33(lang)}${fitaR32_28(lang)}${fitaR32_26(lang)}${fitaR32_24(lang)}${fitaR32_20(lang)}${fitaR32_18(lang)}${fitaR32_17(lang)}${fitaR32_15(lang)}${fitaR32_14(lang)}${fitaR32_13(lang)}${fitaR32_12(lang)}${fitaR32_8(lang)}${fitaR32_5(lang)}${fitaR32_4(lang)}${fitaR32_3(lang)}${fitaR32(lang)}${fitaR30(lang)}${fitaR29(lang)}${fitaR28(lang)}${fitaR26(lang)}${fitaR24(lang)}${fitaR23(lang)}${fitaR21C5(lang)}${fitaR21(lang)}${fitaR20(lang)}${fitaR19(lang)}${fitaR18(lang)}${fitaR16(lang)}${fitaR15(lang)}${fitaR13R14(lang)}${fitaAppStore(lang)}`;
  const fundacional = lang === 'ca'
    ? `\n      ${CRONICA_FUNDACIONAL_VERSIONS_HTML}`
    : `<div lang="ca">${CRONICA_FUNDACIONAL_VERSIONS_HTML}</div>`;
  return `${fitesAnteriors}${entry}${fundacional}`;
}

/**
 * Recompòn la pàgina /versions completa (Nivell 1 + Nivell 2 històric) exactament
 * com abans de la partició IDEA-332, per a verificacions d'honestedat històrica.
 */
export function obtePaginaVersionsCompleta(pageNivell1, language = 'ca') {
  const codi = String(language || 'ca').toLowerCase().split('-')[0];
  const lang = LLENGUES_VERSIONS.has(codi) ? codi : 'ca';
  const base = localitzaPagina(pageNivell1, lang, 'versions');
  const nivell1 = String(base?.html ?? '').trimEnd();
  return {
    ...base,
    html: `${nivell1}\n\n      ${obteHtmlHistoricVersions(lang)}`,
  };
}
